INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个家过得好不好，有没有钱。", "primary_collocate": null, "pronunciation": "jiā dào", "ipa": "tɕja˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们家家道好，有很多钱。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家家道不好，常常没钱买菜。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道不错的人，不一定快乐。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家道慢慢好起来了。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为生意失败，他家的家道差了。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家人家道很好，房子又大又新。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道好不好，不能只看房子。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说他小时候家道很差，一年吃不上几次肉。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从家道中落，亲戚们都疏远了他。", "target_word": "家道", "complexity_tier": "T3", "furigana": "zì cóng jiā dào zhōng luò, qīn qi men dōu shū yuǎn le tā", "sentence_source": "generated"}, {"text": "我朋友家道一般，但是一家人很快乐。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "家道：一个家过得好不好，有没有钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：一个家过得好不好、有没有钱，即听到的词。"}, {"text": "街道", "is_correct": false, "explanation": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。"}, {"text": "驾到", "is_correct": false, "explanation": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。"}, {"text": "交到", "is_correct": false, "explanation": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}], "explanations": {"家道": "家道：一个家过得好不好、有没有钱，即听到的词。", "街道": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。", "驾到": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。", "交到": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家过得好不好、有没有钱，与“有很多钱”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是家里的状况，“家天气好”不成立。"}, {"text": "皮肤", "is_correct": false, "explanation": "体貌：“皮肤”是人身体的外表，不用来说家里的情况。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“好”不修饰年龄，“年龄好”不成立。"}], "explanations": {"家道": "家道：家过得好不好、有没有钱，与“有很多钱”的语境相符。", "天气": "语义：“天气”不是家里的状况，“家天气好”不成立。", "皮肤": "体貌：“皮肤”是人身体的外表，不用来说家里的情况。", "年龄": "搭配：“好”不修饰年龄，“年龄好”不成立。"}, "sentence_index": 0, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的家道在南方，一年回去两次。", "explanation": "这里应该用〈家乡〉。家乡是地方，可以说“在南方”“回去”；家道是经济状况，不是地方。"}, {"text": "他的家道很高，一米九。", "explanation": "这里应该用〈身高〉。身高指身体的高矮，可以说“一米九”；家道指经济状况，不指身高。"}, {"text": "他的家道慢慢大起来了。", "explanation": "这里应该用〈年纪〉。年纪可以“大起来”；家道指经济状况，不能说“大起来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95525, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：一个家过得好不好、有没有钱，即听到的词。"}, {"text": "接到", "is_correct": false, "explanation": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。"}, {"text": "嫁到", "is_correct": false, "explanation": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。"}, {"text": "交道", "is_correct": false, "explanation": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}], "explanations": {"家道": "家道：一个家过得好不好、有没有钱，即听到的词。", "接到": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。", "嫁到": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。", "交道": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家过得好不好、有没有钱，能与“好不好”搭配作评价。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不说“身高好不好”，也与“看房子”无关。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不指家里的状况，不能与“看房子”对应。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：“戒指”是饰品，不指家里有没有钱。"}], "explanations": {"家道": "家道：家过得好不好、有没有钱，能与“好不好”搭配作评价。", "身高": "体貌：“身高”指身体的高矮，不说“身高好不好”，也与“看房子”无关。", "课本": "语义：“课本”是书，不指家里的状况，不能与“看房子”对应。", "戒指": "语义：“戒指”是饰品，不指家里有没有钱。"}, "sentence_index": 6, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把家道搬进了新房子。", "explanation": "这里应该用〈家具〉。家具可以搬进新房子；家道指家庭的经济状况，不是能搬动的东西。"}, {"text": "他的家道一百斤，很结实。", "explanation": "这里应该用〈体重〉。体重指身体的重量，可以说“一百斤”；家道是经济状况，不用斤计算。"}, {"text": "他每天请家道补习数学。", "explanation": "这里应该用〈家教〉。家教是请来教课的人，可以请；家道指经济状况，不能被请来补习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 