INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家庭的经济状况。", "primary_collocate": null, "pronunciation": "jiā dào", "ipa": "tɕja˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他家家道不错，从小不愁吃穿。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年家道中落，他只好出去工作。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在家道富裕的人家。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家道很一般，上学全靠奖学金。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道好了以后，他们搬进了大房子。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王家道殷实，大家都知道。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时家道贫寒，母亲常常做针线赚钱。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲生病以后，家道一年不如一年。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他穿的衣服，家道应该不错。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家道不同，孩子受的教育也不一样。", "target_word": "家道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "家道：家庭的经济状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，即听到的词。"}, {"text": "街道", "is_correct": false, "explanation": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。"}, {"text": "驾到", "is_correct": false, "explanation": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。"}, {"text": "交到", "is_correct": false, "explanation": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}], "explanations": {"家道": "家道：家庭的经济状况，即听到的词。", "街道": "街道 jiēdào 的韵母不同（e 与 a），意思是城市里的道路。", "驾到": "驾到 jiàdào 第一音节声调不同（第四声与第一声），意思是帝王或长辈来到。", "交到": "交到 jiāodào 的韵母不同（ao 与 a），意思是结交到（朋友）。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，与“不愁吃穿”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是家庭的状况，“他家天气不错”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的重量，不能用来说家里的情况。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“不错”不说年龄，“年龄不错”不成立。"}], "explanations": {"家道": "家道：家庭的经济状况，与“不愁吃穿”的语境相符。", "天气": "语义：“天气”不是家庭的状况，“他家天气不错”不成立。", "体重": "体貌：“体重”指身体的重量，不能用来说家里的情况。", "年龄": "搭配：“不错”不说年龄，“年龄不错”不成立。"}, "sentence_index": 0, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他继承了父亲的家道，每天经营饭店。", "explanation": "这里应该用〈家业〉。家业指家里的产业，可以继承和经营；家道指经济状况，不能被继承。"}, {"text": "我的家道有五口人，都住在北京。", "explanation": "这里应该用〈家庭〉。家庭指一家人，可以数人口；家道指经济状况，不能说有几口人。"}, {"text": "他每月的家道很高，买了一辆车。", "explanation": "这里应该用〈收入〉。收入指一段时间获得的钱，可以说“每月的收入”；家道指整体经济状况，不说“每月的家道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_err