INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，即听到的词。"}, {"text": "接到", "is_correct": false, "explanation": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。"}, {"text": "嫁到", "is_correct": false, "explanation": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。"}, {"text": "交道", "is_correct": false, "explanation": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}], "explanations": {"家道": "家道：家庭的经济状况，即听到的词。", "接到": "接到 jiēdào 的韵母不同（e 与 a），意思是收到。", "嫁到": "嫁到 jiàdào 第一音节声调不同（第四声与第一声），意思是嫁入某家。", "交道": "交道 jiāodào 的韵母不同（ao 与 a），意思是往来、交往。"}, "sentence_index": null, "correct_answer": "家道"}, "level_3": {"options": [{"text": "家道", "is_correct": true, "explanation": "家道：家庭的经济状况，与“贫寒”的语境相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能用“贫寒”来形容。"}, {"text": "道路", "is_correct": false, "explanation": "语义：“道路”指路，不指家庭的经济状况。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个人性情，不指家庭的经济状况，也不能被“贫寒”修饰。"}], "explanations": {"家道": "家道：家庭的经济状况，与“贫寒”的语境相符。", "身高": "体貌：“身高”指身体的高矮，不能用“贫寒”来形容。", "道路": "语义：“道路”指路，不指家庭的经济状况。", "性格": "语义：“性格”指个人性情，不指家庭的经济状况，也不能被“贫寒”修饰。"}, "sentence_index": 6, "correct_answer": "家道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的家道很严，从不让孩子玩手机。", "explanation": "这里应该用〈家教〉。家教指家庭的教育和规矩，可以说“家教很严”；家道指经济状况，不能说“很严”。"}, {"text": "客厅里的家道是新买的。", "explanation": "这里应该用〈家具〉。家具是物品，可以说“新买的家具”；家道指经济状况，不能作为物品。"}, {"text": "妈妈每天做家道，很辛苦。", "explanation": "这里应该用〈家务〉。家务是家里要做的事，可以说“做家务”；家道指经济状况，不能做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲去世以后，家道落中了。", "corrected_sentence": "父亲去世以后，家道中落了。", "error_description": "补语错误：“中落”不能拆开颠倒，应说“家道中落”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一家人的家道们不错，大家都很满足。", "corrected_sentence": "他们一家人的家道不错，大家都很满足。", "error_description": "“们”错误：“家道”是抽象的经济状况，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
