INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "带兵打仗的军官。", "primary_collocate": null, "pronunciation": "jiàng lǐng", "ipa": "tɕjɑŋ˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位将领带着士兵上了战场。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的将领要会骑马打仗。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很有名的将领。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将领们坐在帐篷里商量办法。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们都很相信自己的将领。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的将领已经逃走了。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的将领想出了一个好办法。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个将领打过很多次仗。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将领对士兵说：“明天早上出发。”", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了许多古代将领的故事。", "target_word": "将领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "將領", "label": "繁体"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面", "sense_fingerprint": "在战场上带兵打仗的军官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将领", "is_correct": true, "explanation": "正确：将领是带兵打仗的军官，“带着士兵上了战场”说得通。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不带兵打仗，与“带着士兵上了战场”矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不是军官，不会带兵上战场。"}, {"text": "小学生", "is_correct": false, "explanation": "搭配：“带着士兵上战场”需要军人身份，不能说小学生。"}], "explanations": {"将领": "正确：将领是带兵打仗的军官，“带着士兵上了战场”说得通。", "歌手": "语义：歌手不带兵打仗，与“带着士兵上了战场”矛盾。", "厨师": "语义：厨师不是军官，不会带兵上战场。", "小学生": "搭配：“带着士兵上战场”需要军人身份，不能说小学生。"}, "sentence_index": 0, "correct_answer": "将领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在下棋时大声说：“将领！”", "explanation": "这里应该用〈将军〉（下棋时“将军”的意思）。将领指军队中带兵的军官，下棋时不能用。"}, {"text": "这把将领带着士兵上了战场。", "explanation": "量词错误：将领指人，应用〈位〉或〈名〉；〈把〉用于有柄的器具，不能用于人。"}, {"text": "他是我们足球队的将领。", "explanation": "词义误用：将领专指军队中带兵的高级军官，足球队的负责人应说「队长」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将领", "is_correct": true, "explanation": "正确：年轻的将领能想出办法，指的是带兵的军官。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会想办法。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟没有思考能力，不能“想出办法”。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“想出一个好办法”的主语应是人，不能说花园。"}], "explanations": {"将领": "正确：年轻的将领能想出办法，指的是带兵的军官。", "石头": "语义：石头不会想办法。", "闹钟": "语义：闹钟没有思考能力，不能“想出办法”。", "花园": "搭配：“想出一个好办法”的主语应是人，不能说花园。"}, "sentence_index": 6, "correct_answer": "将领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都去菜市场买一个将领。", "explanation": "用法错误：将领指带兵的军官，是人，不是可以买卖的商品，这里误把它当成了货物。"}, {"text": "他每天早上把将领当成书包背去学校。", "explanation": "用法错误：将领是人，不能当作书包背着，这里误把它当成了物品。"}, {"text": "士兵们在将领里休息。", "explanation": "用法错误：将领指人，不是可以“在里面”休息的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只将领命令士兵停下来休息。", "corrected_sentence": "那位将领命令士兵停下来休息。", "error_description": "量词错误：将领指人，应用“位”或“名”；“只”多用于动物等，不能用于人。正确形式为“那位将领”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只年轻的将领带着部队渡过了河。", "corrected_sentence": "那位年轻的将领带着部队渡过了河。", "error_description": "量词错误：将领指人，量词应用“位”或“名”；“只”多用于动物，不能用于人。正确形式为“那位年轻的将领”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "台前", "is_correct": true, "explanation": "台前：指公开露面的一面，与“不让人看见的背后”相对。"}, {"text": "大门", "is_correct": false, "explanation": "大门：房屋的正门，与“幕后”的意思没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房：做饭的房间，与“幕后”的意思没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空：地面上方的广阔空间，与“幕后”的意思没有反义关系。"}], "correct_answer": "台前", "explanations": {"台前": "台前：指公开露面的一面，与“不让人看见的背后”相对。", "大门": "大门：房屋的正门，与“幕后”的意思没有反义关系。", "厨房": "厨房：做饭的房间，与“幕后”的意思没有反义关系。", "天空": "天空：地面上方的广阔空间，与“幕后”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前台", "is_correct": true, "explanation": "前台：指台前、公开的一面，与“不让人看见的背后”相对。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：房屋墙上透光通风的开口，与“幕后”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流：流动的水道，与“幕后”的意思没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包：装书本用的包，与“幕后”的意思没有反义关系。"}], "correct_answer": "前台", "explanations": {"前台": "前台：指台前、公开的一面，与“不让人看见的背后”相对。", "窗户": "窗户：房屋墙上透光通风的开口，与“幕后”没有反义关系。", "河流": "河流：流动的水道，与“幕后”的意思没有反义关系。", "书包": "书包：装书本用的包，与“幕后”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不让人看见的后面。", "primary_collocate": null, "pronunciation": "mù hòu", "ipa": "mu˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事的幕后，还有别人在帮忙。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这支球队的幕后英雄。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找出这次事故幕后的原因。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想出名，一直在幕后帮助大家。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的成功，离不开幕后的努力。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想知道新闻幕后的故事。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了这个案子的幕后黑手。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影幕后的花絮很有意思。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在幕后做了决定，没有告诉别人。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕后的人是谁，没有人知道。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幕後", "label": "繁体"}, {"form": "幕后英雄", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情中不被外人看见的背后，常指暗中做事的人或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，指暗中做事的人或原因。"}, {"text": "母后", "is_correct": false, "explanation": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。"}, {"text": "母猴", "is_correct": false, "explanation": "mǔ hóu 与 mù hòu 两个音节的声调都不同，意思是雌性的猴子。"}, {"text": "木偶", "is_correct": false, "explanation": "第二音节 ǒu 与 hòu 不同：少了 h 声母，声调也不同，意思是用木头等做的玩偶。"}, {"text": "末后", "is_correct": false, "explanation": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。"}], "explanations": {"幕后": "幕后：不让人看见的背后，指暗中做事的人或原因。", "母后": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。", "母猴": "mǔ hóu 与 mù hòu 两个音节的声调都不同，意思是雌性的猴子。", "木偶": "第二音节 ǒu 与 hòu 不同：少了 h 声母，声调也不同，意思是用木头等做的玩偶。", "末后": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。"}, "sentence_index": null, "correct_answer": "幕后"}, "level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，这里指暗中帮忙的人或原因。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是台下看演出的人，不能是这件事的一部分。"}, {"text": "舞台", "is_correct": false, "explanation": "语义：舞台是表演的场地，与“还有别人在帮忙”的说法不符。"}, {"text": "幕布", "is_correct": false, "explanation": "搭配：“这件事的……”要接抽象的方面，“幕布”是具体的布，不能这样搭配。"}], "explanations": {"幕后": "幕后：不让人看见的背后，这里指暗中帮忙的人或原因。", "观众": "语义：观众是台下看演出的人，不能是这件事的一部分。", "舞台": "语义：舞台是表演的场地，与“还有别人在帮忙”的说法不符。", "幕布": "搭配：“这件事的……”要接抽象的方面，“幕布”是具体的布，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在幕后，所有人都能看见他。", "explanation": "这里应该用〈台前〉。幕后指不让人看见的后面，“所有人都能看见他”说明位置是公开的，应说“站在台前”。"}, {"text": "他有幕后，所以没人敢管他。", "explanation": "这里应该用〈后台〉。“后台”指背后的靠山，“幕后”指不公开的背后，不指可以依靠的力量。"}, {"text": "他站在我的幕后，我看不见他。", "explanation": "这里应该用〈背后〉。幕后指不让人看见的后面，人身后的位置只能说背后，不能说幕后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：不让人看见的背后，这里指隐藏身份的人。"}, {"text": "台上", "is_correct": false, "explanation": "语义：“台上”是公开的地方，“幕后黑手”指隐在背后操纵事情的人，“台上黑手”不成立。"}, {"text": "窗口", "is_correct": false, "explanation": "语义：“窗口”是房屋上的开口，不指隐在背后操纵事情的人，“窗口黑手”不成立。"}, {"text": "灯光", "is_correct": false, "explanation": "搭配：“灯光”是光线，不能指隐在背后操纵事情的人，“灯光黑手”不成搭配。"}], "explanations": {"幕后": "幕后：不让人看见的背后，这里指隐藏身份的人。", "台上": "语义：“台上”是公开的地方，“幕后黑手”指隐在背后操纵事情的人，“台上黑手”不成立。", "窗口": "语义：“窗口”是房屋上的开口，不指隐在背后操纵事情的人，“窗口黑手”不成立。", "灯光": "搭配：“灯光”是光线，不能指隐在背后操纵事情的人，“灯光黑手”不成搭配。"}, "sentence_index": 6, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的幕后很重，搬不动。", "explanation": "这里应该用〈底部〉。“幕后”指舞台幕布后或事情不公开的背后，不指物体的部位，箱子的部位应说〈底部〉。"}, {"text": "这件事我们幕后再谈吧。", "explanation": "这里应该用〈以后〉。幕后不表示时间上的先后，应说“以后再谈”。"}, {"text": "这张纸的幕后写着字，你看见了吗？", "explanation": "这里应该用〈背面〉。幕后指不让人看见的后面，纸的另一面应说背面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的幕后面原因，大家都还不清楚。", "corrected_sentence": "这件事的幕后原因，大家都还不清楚。", "error_description": "“幕后”本身已表示方位，后面再加“面”（幕后面）是错误形式，应写“幕后原因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直到幕后支持我们，从不出面。", "corrected_sentence": "他一直在幕后支持我们，从不出面。", "error_description": "介词错误：表示在某个场所做事用“在”，“到”表示动作到达某处，这里应说“在幕后支持”，不能说“到幕后支持”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
