INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "舞台幕布的后面，比喻不公开的背后。", "primary_collocate": null, "pronunciation": "mù hòu", "ipa": "mu˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "演员在幕后等着上台。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕后传来一阵笑声。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开演前，孩子们都躲在幕后。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在幕后，看着台下的人。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕后有人在小声说话。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场演出，幕后的工作人员特别辛苦。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这件事的幕后老板？", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢上台，只愿意在幕后工作。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察想找出这件事幕后的人。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这部电影的幕后做了很多事。", "target_word": "幕后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幕後", "label": "繁体"}, {"form": "幕后英雄", "label": "复合"}], "register": "中性", "sense_fingerprint": "舞台幕布的后面，也比喻事情不公开的背后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：舞台幕布的后面，比喻不公开的背后。"}, {"text": "母后", "is_correct": false, "explanation": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。"}, {"text": "母猴", "is_correct": false, "explanation": "mǔ hóu 与 mù hòu 两个音节的声调都不同，意思是雌性的猴子。"}, {"text": "木偶", "is_correct": false, "explanation": "第二音节 ǒu 与 hòu 不同：少了 h 声母，声调也不同，意思是用木头等做的玩偶。"}, {"text": "末后", "is_correct": false, "explanation": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。"}], "explanations": {"幕后": "幕后：舞台幕布的后面，比喻不公开的背后。", "母后": "mǔ hòu（第三声）与 mù hòu（第四声）声调不同，意思是皇帝的母亲，即太后。", "母猴": "mǔ hóu 与 mù hòu 两个音节的声调都不同，意思是雌性的猴子。", "木偶": "第二音节 ǒu 与 hòu 不同：少了 h 声母，声调也不同，意思是用木头等做的玩偶。", "末后": "mò hòu（第四声）与 mù hòu 第一音节的韵母不同（o 与 u），意思是最后、末尾。"}, "sentence_index": null, "correct_answer": "幕后"}, "level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：舞台幕布的后面，演员在此等候出场。"}, {"text": "观众席", "is_correct": false, "explanation": "语义：观众席是台下给观众坐的座位，演员不会在那里等着上台。"}, {"text": "幕布", "is_correct": false, "explanation": "搭配：“在”后要接可以停留的场所，幕布是挂在舞台上的布，不能说“在幕布等”。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，与舞台上的演出无关。"}], "explanations": {"幕后": "幕后：舞台幕布的后面，演员在此等候出场。", "观众席": "语义：观众席是台下给观众坐的座位，演员不会在那里等着上台。", "幕布": "搭配：“在”后要接可以停留的场所，幕布是挂在舞台上的布，不能说“在幕布等”。", "银行": "语义：银行是办理金融业务的地方，与舞台上的演出无关。"}, "sentence_index": 0, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众都坐在幕后，等着看演出。", "explanation": "这里应该用〈台下〉。幕后指舞台幕布的后面，观众坐的是台下，不能说坐在幕后。"}, {"text": "舞台上的幕后很厚。", "explanation": "这里应该用〈幕布〉。幕布是挂在舞台上的布，幕后指幕布的后面这个位置，不能指布本身。"}, {"text": "他躲在树的幕后，没有被人发现。", "explanation": "这里应该用〈背后〉。幕后特指舞台幕布后面或不公开的背后，树的背后只能说背后，不能说幕后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幕后", "is_correct": true, "explanation": "幕后：舞台幕布的后面，比喻不公开的背后，这里指暗中操控这件事的人。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：课堂是上课的教室，不能成为这件事的老板。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是能经营或管理事情的人。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“农田”是土地，不能作为“老板”的修饰语，与“这件事的……老板”不搭。"}], "explanations": {"幕后": "幕后：舞台幕布的后面，比喻不公开的背后，这里指暗中操控这件事的人。", "课堂": "语义：课堂是上课的教室，不能成为这件事的老板。", "天气": "语义：天气是自然现象，不是能经营或管理事情的人。", "农田": "搭配：“农田”是土地，不能作为“老板”的修饰语，与“这件事的……老板”不搭。"}, "sentence_index": 6, "correct_answer": "幕后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我们幕后再说吧。", "explanation": "这里应该用〈以后〉。幕后指幕布后面或不公开的背后，不表示时间上的先后，应说“以后再说”。"}, {"text": "这个箱子的幕后很重，搬不动。", "explanation": "这里应该用〈底部〉。“幕后”指舞台幕布后或事情不公开的背后，不指物体的部位，箱子的部位应说〈底部〉。"}, {"text": "这张纸的幕后写着一行字。", "explanation": "这里应该用〈背面〉。幕后指舞台幕布的后面或不公开的背后，纸的另一面只能说背面，不能说幕后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出开始前，化妆师都在幕后面忙碌。", "corrected_sentence": "演出开始前，化妆师都在幕后忙碌。", "error_description": "“幕后”本身已表示方位，后面再加“面”（幕后面）是错误形式，应写“幕后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直到幕后工作，从不出面。", "corrected_sentence": "他一直在幕后工作，从不出面。", "error_description": "介词错误：表示在某个场所做事用“在”，“到”表示动作到达某处，这里应说“在幕后工作”，不能说“到幕后工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
