INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把一个东西做起来的人。", "primary_collocate": null, "pronunciation": "jiàn lì zhě", "ipa": "tɕjɛn˥˩ li˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是这家小店的建立者。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的建立者是一位老师。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这个城市的建立者？", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的建立者每天最早到办公室。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个俱乐部的建立者是我的朋友。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建立者花了很多年才做成这件事。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的建立者想帮助穷人。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要感谢这个小组的建立者。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只是建立者，也是第一个老师。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的建立者是两个大学生。", "target_word": "建立者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面", "sense_fingerprint": "把店、学校、网站等做起来的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：「学生」指在学校学习的人，小店不是学校，说“这家小店的学生”不成立。"}, {"text": "建立者", "is_correct": true, "explanation": "正确：「建立者」指把这家小店做起来的人，与句意相符。"}, {"text": "总统", "is_correct": false, "explanation": "搭配：「总统」只用于国家，不能说某家小店的总统。"}, {"text": "校长", "is_correct": false, "explanation": "语义：「校长」是学校的负责人，不能用来指小店的负责人。"}], "explanations": {"学生": "语义：「学生」指在学校学习的人，小店不是学校，说“这家小店的学生”不成立。", "建立者": "正确：「建立者」指把这家小店做起来的人，与句意相符。", "总统": "搭配：「总统」只用于国家，不能说某家小店的总统。", "校长": "语义：「校长」是学校的负责人，不能用来指小店的负责人。"}, "sentence_index": 0, "correct_answer": "建立者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的建立者写得很好。", "explanation": "这里应该用〈作者〉。建立者指把店、学校、网站等做起来的人，写书的人要说〈作者〉。"}, {"text": "这部电影的建立者是李明。", "explanation": "这里应该用〈导演〉。建立者不用于电影，拍电影的负责人要说〈导演〉。"}, {"text": "我们学校有一本建立者。", "explanation": "这里应该用〈位〉或〈个〉。〈本〉用于书籍，建立者指人，不能用〈本〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌手", "is_correct": false, "explanation": "语义：「歌手」指唱歌的人，医院里不能有“这家医院的歌手”这样的身份。"}, {"text": "球员", "is_correct": false, "explanation": "搭配：「球员」需要球队，不能说医院的球员。"}, {"text": "建立者", "is_correct": true, "explanation": "正确：「建立者」指创办这家医院的人，与“想帮助穷人”的语境相符。"}, {"text": "作家", "is_correct": false, "explanation": "语义：「作家」指写作的人，与创办医院无关，句意不通。"}], "explanations": {"歌手": "语义：「歌手」指唱歌的人，医院里不能有“这家医院的歌手”这样的身份。", "球员": "搭配：「球员」需要球队，不能说医院的球员。", "建立者": "正确：「建立者」指创办这家医院的人，与“想帮助穷人”的语境相符。", "作家": "语义：「作家」指写作的人，与创办医院无关，句意不通。"}, "sentence_index": 6, "correct_answer": "建立者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的建立者是一位大学生。", "explanation": "这里应该用〈画家〉。建立者指把店、学校、网站等做起来的人，画画的人要说〈画家〉。"}, {"text": "这个网站有一条建立者。", "explanation": "这里应该用〈位〉或〈个〉。〈条〉用于细长的东西，建立者指人，不能用〈条〉来数。"}, {"text": "这首歌的建立者很年轻。", "explanation": "这里应该用〈作曲家〉。建立者指做起来某事物的人，写歌的人要说〈作曲家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家书店的一只建立者昨天来过。", "corrected_sentence": "那家书店的一位建立者昨天来过。", "error_description": "量词错误：指人的「建立者」不能用〈只〉（〈只〉多用于动物）。应为「一位建立者」，〈位〉是指人的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位建立者们昨天来过我们学校。", "corrected_sentence": "这两位建立者昨天来过我们学校。", "error_description": "“们”误用：「这两位」已表明人数，不能再加“们”。应为「这两位建立者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人活着的这条命。", "primary_collocate": null, "pronunciation": "xìng mìng", "ipa": "ɕiŋ˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生救了他的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大火夺走了很多人的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了救孩子，丢了性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术很成功，他的性命已经没有危险了。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很急，别拿性命开玩笑。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保住性命，他跳进了河里。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次手术关系到病人的性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人说：不想丢性命，就别出声。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车祸中捡回了一条性命。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，再晚一点，他的性命就难保了。", "target_word": "性命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人活着的那条命，常指受到威胁或需要保住的命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“救”的对象是人的生命，“救他的性命”指使他脱离生命危险。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：医生救的是人的生命，“钱包”不是需要被救的对象。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“救”针对的是人或生命，病房不是医生要去救的对象。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“救”不跟“脾气”搭配，“救”后面接的是人或生命。"}], "explanations": {"性命": "正确。“救”的对象是人的生命，“救他的性命”指使他脱离生命危险。", "钱包": "语义：医生救的是人的生命，“钱包”不是需要被救的对象。", "病房": "语义：“救”针对的是人或生命，病房不是医生要去救的对象。", "脾气": "搭配：“救”不跟“脾气”搭配，“救”后面接的是人或生命。"}, "sentence_index": 0, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在农村过着平静的性命。", "explanation": "这里应该用〈生活〉。“过”后接“生活”，“性命”指一个人活着的这条命，不能说“过性命”。"}, {"text": "运动可以增强性命的抵抗力。", "explanation": "这里应该用〈身体〉。“抵抗力”属于身体，“性命”不能修饰“抵抗力”。"}, {"text": "科学家一直在研究性命的起源。", "explanation": "这里应该用〈生命〉。研究生物的起源说“生命”，“性命”指个人的命，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性命", "is_correct": true, "explanation": "正确。“关系到”的是病人活着的这条命，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：手术的结果关系到的是人身安危，不是工资。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“关系到”说的是重大利害，车票与手术结果无关。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“关系到”不跟“发型”搭配，它通常接健康、安危一类的事。"}], "explanations": {"性命": "正确。“关系到”的是病人活着的这条命，符合句意。", "工资": "语义：手术的结果关系到的是人身安危，不是工资。", "车票": "语义：“关系到”说的是重大利害，车票与手术结果无关。", "发型": "搭配：“关系到”不跟“发型”搭配，它通常接健康、安危一类的事。"}, "sentence_index": 6, "correct_answer": "性命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种手机的电池很耐用，性命很长。", "explanation": "这里应该用〈寿命〉。“性命”只指人或动物活着的这条命，电池的使用期限要说“寿命”。"}, {"text": "这场事故夺走了他的一只性命。", "explanation": "这里应该用〈条〉。“性命”的量词是“条”，“只”不能用于“性命”。"}, {"text": "春天到了，花园里充满了性命。", "explanation": "这里应该用〈生机〉。“充满”后接“生机”“活力”，“性命”不能用来描写整个花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场事故差点夺走他一个性命。", "corrected_sentence": "这场事故差点夺走他一条性命。", "error_description": "量词错误：“性命”的量词应为“条”，这里误用“个”。应说“一条性命”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生终于买下了他的性命。", "corrected_sentence": "医生终于救下了他的性命。", "error_description": "搭配错误：“性命”不能用“买”，应说“救下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
