INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "付款超出价款时，把多余的钱退还给对方。", "primary_collocate": null, "pronunciation": "zhǎo qián", "ipa": "ʈʂau̯˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我给了一百块，老板马上给我找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的收银员正在给客人找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款多了，店员就要找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给的钱太多，我得给你找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车司机没有零钱，不能找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只有一百元大钞，他没法找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收银员算错了，找钱时多给了客人。", "target_word": "找钱", "complexity_tier": "T3", "furigana": "shōuyínyuán suàn cuò le, zhǎoqián shí duō gěi le kèrén.", "sentence_source": "generated"}, {"text": "付完款后，别忘了让店员找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以自动找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板忙着接电话，忘了给客人找钱。", "target_word": "找钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找了钱", "label": "完成体（离合）"}, {"form": "找过钱", "label": "经历体（离合）"}, {"form": "找錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "付款超出价款后退还多余的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：付款后老板退还多付的余款，正是“找钱”的意思。"}, {"text": "付钱", "is_correct": false, "explanation": "语义：“付钱”是顾客把钱交给对方，句中是老板把钱还给顾客，方向不符。"}, {"text": "欠钱", "is_correct": false, "explanation": "语义：“欠钱”指欠别人钱款，与老板给我找回余款的情境不符。"}, {"text": "借钱", "is_correct": false, "explanation": "语义：“借钱”指借入或借出款项，“老板马上给我借钱”与找回多付的余款不符。"}], "explanations": {"找钱": "正确：付款后老板退还多付的余款，正是“找钱”的意思。", "付钱": "语义：“付钱”是顾客把钱交给对方，句中是老板把钱还给顾客，方向不符。", "欠钱": "语义：“欠钱”指欠别人钱款，与老板给我找回余款的情境不符。", "借钱": "语义：“借钱”指借入或借出款项，“老板马上给我借钱”与找回多付的余款不符。"}, "sentence_index": 0, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一瓶水，找钱给了店员。", "explanation": "这里应该用〈付钱〉。找钱是卖家把多付的余款还给顾客，买东西应是顾客付钱。"}, {"text": "我向朋友找钱，他找给了我一百。", "explanation": "这里应该用〈借钱〉。找钱只指退还多付的余款，不能表示向别人借钱。"}, {"text": "他找钱很大方。", "explanation": "这里应该用〈花钱〉。找钱指退还余款，不表示消费，说“他花钱很大方”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找钱", "is_correct": true, "explanation": "正确：收银员算错后，多给客人的钱要退还，正是“找钱”的意思。"}, {"text": "赔钱", "is_correct": false, "explanation": "语义：“赔钱”指亏损或赔偿，与找回多给客人的钱无关。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：“收钱”是接受对方的钱，句中是把钱退还给客人，方向相反。"}, {"text": "交钱", "is_correct": false, "explanation": "配价：“交钱”需要说明交给谁、为何交，句中“多给了客人”无法接续。"}], "explanations": {"找钱": "正确：收银员算错后，多给客人的钱要退还，正是“找钱”的意思。", "赔钱": "语义：“赔钱”指亏损或赔偿，与找回多给客人的钱无关。", "收钱": "语义：“收钱”是接受对方的钱，句中是把钱退还给客人，方向相反。", "交钱": "配价：“交钱”需要说明交给谁、为何交，句中“多给了客人”无法接续。"}, "sentence_index": 6, "correct_answer": "找钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向银行找钱买房。", "explanation": "这里应该用〈贷款〉。找钱是退还余款，向银行借款要说贷款。"}, {"text": "他把这件事找给了妈妈。", "explanation": "这里应该用〈告诉〉。找给是把找回的钱交还对方，不能用来转达事情，应说告诉。"}, {"text": "他把邻居的窗户打碎了，要找钱。", "explanation": "这里应该用〈赔钱〉。找钱是退还余款，打碎别人的东西后应说赔钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前在超市打工时找钱过。", "corrected_sentence": "我以前在超市打工时找过钱。", "error_description": "错误：经历体“过”应紧跟动词，应说“找过钱”，不能放在“钱”后面说“找钱过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板把找钱给了我。", "corrected_sentence": "老板把钱找给了我。", "error_description": "错误：“把”字句中，宾语“钱”应放在动词“找”之前，应说“把钱找给了我”，不能说“把找钱给了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送出", "is_correct": true, "explanation": "反义：“送出”是把东西送给别人，与“收回”把送出去的东西拿回来正相反。"}, {"text": "保管", "is_correct": false, "explanation": "无关：“保管”指妥善看管物品，与“收回”没有反义关系。"}, {"text": "测量", "is_correct": false, "explanation": "无关：“测量”指量出长短或大小，与“收回”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指使坏的东西恢复正常，与“收回”不是反义词。"}], "correct_answer": "送出", "explanations": {"送出": "反义：“送出”是把东西送给别人，与“收回”把送出去的东西拿回来正相反。", "保管": "无关：“保管”指妥善看管物品，与“收回”没有反义关系。", "测量": "无关：“测量”指量出长短或大小，与“收回”不构成反义。", "修理": "无关：“修理”指使坏的东西恢复正常，与“收回”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "借出", "is_correct": true, "explanation": "反义：“借出”是把东西借给别人，与“收回”把借出的东西拿回来相对。"}, {"text": "清点", "is_correct": false, "explanation": "无关：“清点”指逐个数清，与“收回”没有反义关系。"}, {"text": "归类", "is_correct": false, "explanation": "无关：“归类”指按类别整理，与“收回”不构成反义。"}, {"text": "修补", "is_correct": false, "explanation": "无关：“修补”指把破损的地方补好，与“收回”不是反义词。"}], "correct_answer": "借出", "explanations": {"借出": "反义：“借出”是把东西借给别人，与“收回”把借出的东西拿回来相对。", "清点": "无关：“清点”指逐个数清，与“收回”没有反义关系。", "归类": "无关：“归类”指按类别整理，与“收回”不构成反义。", "修补": "无关：“修补”指把破损的地方补好，与“收回”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把给出去的东西拿回来。", "primary_collocate": null, "pronunciation": "shōu huí", "ipa": "ʂou̯˥˥ xu̯eɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我把借给他的书收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把发下去的试卷都收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把给弟弟的玩具收回去了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把送给朋友的帽子又收回来了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借出去的伞，我下周就收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把给客人的菜单收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把给我的零花钱收回了，因为我乱花。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把借出的车收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把给小狗的骨头收回来了，它很生气。", "target_word": "收回", "complexity_tier": "T3", "furigana": "wǒ bǎ gěi xiǎo gǒu de gǔ tou shōu huí lái le, tā hěn shēng qì.", "sentence_source": "generated"}, {"text": "图书馆把借出的旧书全部收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收回了", "label": "完成体"}, {"form": "收回过", "label": "经历体"}, {"form": "收回来", "label": "复合趋向"}, {"form": "收回去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "把借出或给出的实物拿回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：听到的是“收回”（shōu huí），意思是把借出或给出的东西拿回来。"}, {"text": "收获", "is_correct": false, "explanation": "huò（第四声）与 huí（第二声）韵母和声调都不同，意思是收成、得到成果，不是取回。"}, {"text": "首回", "is_correct": false, "explanation": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。"}, {"text": "搜回", "is_correct": false, "explanation": "sōu 与 shōu 声母不同（s 与 sh），声调相同，意思是搜找后找回。"}, {"text": "收汇", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}], "explanations": {"收回": "正确：听到的是“收回”（shōu huí），意思是把借出或给出的东西拿回来。", "收获": "huò（第四声）与 huí（第二声）韵母和声调都不同，意思是收成、得到成果，不是取回。", "首回": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。", "搜回": "sōu 与 shōu 声母不同（s 与 sh），声调相同，意思是搜找后找回。", "收汇": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}, "sentence_index": null, "correct_answer": "收回"}, "level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“收回”表示把借出去的书拿回来，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能用于食物，书不能被吃。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于烹饪食物，书不能被煮。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算出数目，与借出去的书被拿回无关。"}], "explanations": {"收回": "正确：“收回”表示把借出去的书拿回来，符合句意。", "吃": "搭配：“吃”只能用于食物，书不能被吃。", "煮": "搭配：“煮”用于烹饪食物，书不能被煮。", "计算": "语义：“计算”指算出数目，与借出去的书被拿回无关。"}, "sentence_index": 0, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家停车场每小时向每辆车收回十元的停车费。", "explanation": "这里应该用〈收取〉。停车费是向车主收取的；“收回”指把原先给出或发出的东西拿回来。"}, {"text": "他在果园里收回了一大筐苹果。", "explanation": "这里应该用〈采摘〉。苹果是从树上摘下来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}, {"text": "他靠自己的努力，终于收回了冠军。", "explanation": "这里应该用〈取得〉。冠军是靠努力争取来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“因为我乱花”说明零花钱被拿回，“收回”符合句意。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”指称赞人或事，与零花钱被拿回的因果关系不符。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不能用于零花钱。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于庆贺喜事，不能用于零花钱。"}], "explanations": {"收回": "正确：“因为我乱花”说明零花钱被拿回，“收回”符合句意。", "赞美": "语义：“赞美”指称赞人或事，与零花钱被拿回的因果关系不符。", "感谢": "搭配：“感谢”的对象是人或帮助，不能用于零花钱。", "祝贺": "搭配：“祝贺”用于庆贺喜事，不能用于零花钱。"}, "sentence_index": 6, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在海边收回了很多漂亮的贝壳。", "explanation": "这里应该用〈收集〉。贝壳是自己捡来的，没有先前给出的东西，应用“收集”。"}, {"text": "政府向企业收回了一笔高额的税款。", "explanation": "这里应该用〈征收〉。税款是政府向企业征收的，并不是原先给出的东西；“收回”指取回已给出的东西，不能这样用。"}, {"text": "他在超市收回了一大袋零食。", "explanation": "这里应该用〈买〉。零食是在超市买来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把借出去的伞收回了来。", "corrected_sentence": "我把借出去的伞收回来了。", "error_description": "错误：趋向补语“来”应紧跟在“收回”之后，构成“收回来了”，不能说“收回了来”。正确说法是“我把借出去的伞收回来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没把借出的车收回了。", "corrected_sentence": "我没把借出的车收回。", "error_description": "错误：否定词“没”表示未发生，不能与句末的“了”同用，应去掉“了”，说“我没把借出的车收回”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发出", "is_correct": true, "explanation": "反义：“发出”是把东西送出去，与“收回”把东西取回的动作正相反。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指妥善留存，与“收回”没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "无关：“检查”指查看是否有问题，与“收回”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“收回”不是反义词。"}], "correct_answer": "发出", "explanations": {"发出": "反义：“发出”是把东西送出去，与“收回”把东西取回的动作正相反。", "保存": "无关：“保存”指妥善留存，与“收回”没有反义关系。", "检查": "无关：“检查”指查看是否有问题，与“收回”不构成反义。", "讨论": "无关：“讨论”指交换意见，与“收回”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下达", "is_correct": true, "explanation": "反义：“下达”指把命令发布下去，与“收回命令”正相反。"}, {"text": "执行", "is_correct": false, "explanation": "无关：“执行”指实施命令，与收回命令不构成反义。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指深入探讨，与收回命令没有反义关系。"}, {"text": "通过", "is_correct": false, "explanation": "无关：“通过”指批准或获准，与收回命令不是反义词。"}], "correct_answer": "下达", "explanations": {"下达": "反义：“下达”指把命令发布下去，与“收回命令”正相反。", "执行": "无关：“执行”指实施命令，与收回命令不构成反义。", "研究": "无关：“研究”指深入探讨，与收回命令没有反义关系。", "通过": "无关：“通过”指批准或获准，与收回命令不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把发出或给出的东西取回。", "primary_collocate": null, "pronunciation": "shōu huí", "ipa": "ʂou̯˥˥ xu̯eɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "公司收回了发出的通知。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说错了话，想收回却来不及。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把给小李的权力收回了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把寄出的材料收回了，因为内容有误。", "target_word": "收回", "complexity_tier": "T3", "furigana": "tā bǎ jì chū de cái liào shōu huí le, yīn wèi nèi róng yǒu wù.", "sentence_source": "generated"}, {"text": "政府收回了借给公司的那块地。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现填错了表，就把交上去的表收回来了。", "target_word": "收回", "complexity_tier": "T3", "furigana": "tā fā xiàn tián cuò le biǎo, jiù bǎ jiāo shàng qù de biǎo shōu huí lái le.", "sentence_source": "generated"}, {"text": "学校收回了给他的奖学金。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把说过的话收回，对不起。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行把发出的卡全部收回。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理收回命令，大家不用加班了。", "target_word": "收回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收回了", "label": "完成体"}, {"form": "收回过", "label": "经历体"}, {"form": "收回来", "label": "复合趋向"}, {"form": "收回去", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "把已发出或给出的东西取回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：听到的是“收回”（shōu huí），意思是把发出或给出的东西取回。"}, {"text": "收获", "is_correct": false, "explanation": "huò（第四声）与 huí（第二声）韵母和声调都不同，意思是收成、得到成果，不是取回。"}, {"text": "首回", "is_correct": false, "explanation": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。"}, {"text": "搜回", "is_correct": false, "explanation": "sōu 与 shōu 声母不同（s 与 sh），声调相同，意思是搜找后找回。"}, {"text": "收汇", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}], "explanations": {"收回": "正确：听到的是“收回”（shōu huí），意思是把发出或给出的东西取回。", "收获": "huò（第四声）与 huí（第二声）韵母和声调都不同，意思是收成、得到成果，不是取回。", "首回": "声调混淆：shǒu（第三声）与 shōu（第一声）声调不同，首回指第一次或头一回，不是取回。", "搜回": "sōu 与 shōu 声母不同（s 与 sh），声调相同，意思是搜找后找回。", "收汇": "huì（第四声）与 huí（第二声）声调不同，意思是外汇或货款的收入。"}, "sentence_index": null, "correct_answer": "收回"}, "level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“收回”表示把已发出的通知取回，符合句中语境。"}, {"text": "订购", "is_correct": false, "explanation": "搭配：“订购”用于买货或订服务，通知不能被订购。"}, {"text": "收买", "is_correct": false, "explanation": "语义：“收买”指用钱或好处拉拢他人，与已发出的通知无关。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算出数目，与通知被取回无关。"}], "explanations": {"收回": "正确：“收回”表示把已发出的通知取回，符合句中语境。", "订购": "搭配：“订购”用于买货或订服务，通知不能被订购。", "收买": "语义：“收买”指用钱或好处拉拢他人，与已发出的通知无关。", "计算": "语义：“计算”指算出数目，与通知被取回无关。"}, "sentence_index": 0, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家网站每年向会员收回一百元的服务费。", "explanation": "这里应该用〈收取〉。服务费是向会员收取的；“收回”指把原先给出或发出的东西拿回来，不能用于收费。"}, {"text": "农民们在秋天收回了一大片小麦。", "explanation": "这里应该用〈收割〉。收割是把成熟的庄稼割下来；“收回”指把原先给出或发出的东西拿回，不能用于庄稼。"}, {"text": "他的脾气收回了很多。", "explanation": "这里应该用〈收敛〉。脾气逐渐变得温和要用“收敛”；“收回”只用于取回原先给出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收回", "is_correct": true, "explanation": "正确：“给他的奖学金”是学校发放的，“收回”指取回，符合语境。"}, {"text": "赚取", "is_correct": false, "explanation": "语义：“赚取”指靠劳动或经营获得利益，奖学金是学校发给的，不能被赚取。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”用于买东西，奖学金不能被购买。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱并赞赏美好的事物，与学校取回奖学金无关。"}], "explanations": {"收回": "正确：“给他的奖学金”是学校发放的，“收回”指取回，符合语境。", "赚取": "语义：“赚取”指靠劳动或经营获得利益，奖学金是学校发给的，不能被赚取。", "购买": "搭配：“购买”用于买东西，奖学金不能被购买。", "欣赏": "语义：“欣赏”指喜爱并赞赏美好的事物，与学校取回奖学金无关。"}, "sentence_index": 6, "correct_answer": "收回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用钱收回了那位证人。", "explanation": "这里应该用〈收买〉。收买是用钱或好处拉拢他人；“收回”指取回原先给出的东西，不能这样用。"}, {"text": "他通过多年的努力，终于收回了属于自己的成功。", "explanation": "这里应该用〈取得〉。成功是靠努力争取来的，不是原先给出的东西；“收回”只用于取回已给出的东西。"}, {"text": "这次旅行，我收回了很多感悟。", "explanation": "这里应该用〈收获〉。感悟是从经历中得到的，要用“收获”；“收回”需要有先前给出或发出的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把借给朋友的伞收回的了。", "corrected_sentence": "我把借给朋友的伞收回了。", "error_description": "错误：动词后多加了“的”，“收回的了”不成句，应说“收回了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把发出的通知收回了去。", "corrected_sentence": "老师把发出的通知收回去了。", "error_description": "错误：趋向补语“去”应紧跟动词“收回”，应说“收回去了”，“了”放在句末，不能说“收回了去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
