INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写在墙上或布上，用几句话告诉大家的话。", "primary_collocate": null, "pronunciation": "biāo yǔ", "ipa": "pi̯ɑʊ˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "墙上的红色标语很大，老远就能看见。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们举着布做的标语走在路上。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在楼前挂了一条长标语。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，门口的标语掉下来了。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着笔在白布上写标语。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上挂着一条标语，上面写着“欢迎回家”。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这张标语贴在门上。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路边的标语已经很旧了。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会上，每个班都在看台上挂了自己的标语。", "target_word": "标语", "complexity_tier": "T3", "furigana": "yùndònghuì shàng měi ge bān dōu zài kàntái shàng guà le zìjǐ de biāoyǔ", "sentence_source": "generated"}, {"text": "那条标语的字是用黑色油漆写的。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条标语", "label": "量词"}, {"form": "标语牌", "label": "复合"}, {"form": "標語", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写在墙或布上的醒目标语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标语", "is_correct": true, "explanation": "正确：标语是写在墙上的醒目文字，可以“老远就能看见”。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地上，不会挂在墙上，与“墙上的”矛盾。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能“墙上的红色”并且“老远就能看见”。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：拖鞋一般不说“很大”，也不说“老远就能看见”。"}], "explanations": {"标语": "正确：标语是写在墙上的醒目文字，可以“老远就能看见”。", "地毯": "语义：地毯铺在地上，不会挂在墙上，与“墙上的”矛盾。", "饼干": "语义：饼干是食物，不能“墙上的红色”并且“老远就能看见”。", "拖鞋": "搭配：拖鞋一般不说“很大”，也不说“老远就能看见”。"}, "sentence_index": 0, "correct_answer": "标语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶酸奶的标语上写着生产日期。", "explanation": "这里应该用〈标签〉。标签是贴在商品上标明信息的纸，标语是写在墙上或布上宣传鼓动的话，不用来标生产日期。"}, {"text": "他给同学寄了一条标语，邀请大家参加生日会。", "explanation": "这里应该用〈请柬〉。请柬是邀请客人的书面卡片，标语不能寄出去邀请人。"}, {"text": "墙上挂着一条标语，上面标着各个城市的位置。", "explanation": "这里应该用〈地图〉。地图才用来标注各个城市的位置，标语只写宣传鼓动的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标语", "is_correct": true, "explanation": "正确：“把这张标语贴在门上”指把写着字的宣传品贴上去，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能被“贴”在门上。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发太大，无法“贴”在门上。"}, {"text": "床", "is_correct": false, "explanation": "配价：“贴”要求可以附着的平面物作宾语，床不能作“贴”的对象。"}], "explanations": {"标语": "正确：“把这张标语贴在门上”指把写着字的宣传品贴上去，符合句意。", "桌子": "语义：桌子是家具，不能被“贴”在门上。", "沙发": "语义：沙发太大，无法“贴”在门上。", "床": "配价：“贴”要求可以附着的平面物作宾语，床不能作“贴”的对象。"}, "sentence_index": 6, "correct_answer": "标语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸在宴会上说了一段标语。", "explanation": "这里应该用〈祝酒词〉。祝酒词是宴会上举杯时说的话，标语是写在墙上或布上的口号，不在宴会上说。"}, {"text": "我的标语写得很长，每天都记录一件事。", "explanation": "这里应该用〈日记〉。日记是每天记录生活的本子，标语是写在墙上或布上的几句话，不用来记录每天的事。"}, {"text": "学校的标语每天早上负责开门。", "explanation": "这里应该用〈门卫〉。标语是写在墙上或布上的字，不能负责开门，指做这件事的人应说门卫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上挂着一位红色标语。", "corrected_sentence": "墙上挂着一条红色标语。", "error_description": "量词错误：“位”只用于人，标语是条幅，应用“条”。正确说法是“墙上挂着一条红色标语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这本标语贴到门口去。", "corrected_sentence": "请你把这条标语贴到门口去。", "error_description": "量词错误：标语应用“条”，“本”用于书册。正确说法是“这条标语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
