INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灰色的粉，加水以后会变得很硬，用来盖房子。", "primary_collocate": null, "pronunciation": "shuǐ ní", "ipa": "ʂueɪ˨˩˦ ni˧˥", "syllable_count": 2, "sentences": [{"text": "工人们在用水泥盖房子。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两袋水泥，要修院子的墙。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥加水以后，过几天就变硬了。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地上到处堆着灰色的水泥。", "target_word": "水泥", "complexity_tier": "T3", "furigana": "gōng dì shàng dào chù duī zhe huī sè de shuǐ ní", "sentence_source": "generated"}, {"text": "请把水泥和沙子放在一起搅一搅。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的地是用水泥做的。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水泥很重，一个人搬不动。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手上沾着水泥，洗了很久。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅在墙上抹了一层水泥。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，工人把水泥盖好了。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "吨", "label": "量词"}], "register": "中性", "sense_fingerprint": "水泥：灰色粉末，加水变硬，用来盖房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来盖房子，“用空气盖房子”句意不通。"}, {"text": "水泥", "is_correct": true, "explanation": "正确答案。水泥是建筑材料，与“盖房子”相合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是建筑材料，无法用来盖房子。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“盖房子”需要建筑材料，“眼泪”与“盖房子”搭配不当。"}], "explanations": {"空气": "语义：空气不能用来盖房子，“用空气盖房子”句意不通。", "水泥": "正确答案。水泥是建筑材料，与“盖房子”相合。", "歌曲": "语义：歌曲不是建筑材料，无法用来盖房子。", "眼泪": "搭配：“盖房子”需要建筑材料，“眼泪”与“盖房子”搭配不当。"}, "sentence_index": 0, "correct_answer": "水泥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民把水泥撒在地里当肥料。", "explanation": "这里应该用〈化肥〉。水泥遇水会硬化，不能当肥料撒在地里。"}, {"text": "工地上堆着三只水泥。", "explanation": "这里应该用〈袋〉或〈吨〉。“只”多用于动物，不用来称量水泥。"}, {"text": "他买了一个水泥，准备修院子。", "explanation": "这里应该用〈袋〉或〈吨〉。水泥是物质名词，不能用“个”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是人的器官，不能用“很重”来形容其分量。"}, {"text": "水泥", "is_correct": true, "explanation": "正确答案。水泥有重量，一个人搬不动，与句意相合。"}, {"text": "大海", "is_correct": false, "explanation": "配价：“搬不动”要求可以搬动的具体物体，“大海”不能被搬动。"}, {"text": "春天", "is_correct": false, "explanation": "配价：“春天”是时间，不能被搬动，与“搬不动”不搭。"}], "explanations": {"眼睛": "体貌：“眼睛”是人的器官，不能用“很重”来形容其分量。", "水泥": "正确答案。水泥有重量，一个人搬不动，与句意相合。", "大海": "配价：“搬不动”要求可以搬动的具体物体，“大海”不能被搬动。", "春天": "配价：“春天”是时间，不能被搬动，与“搬不动”不搭。"}, "sentence_index": 6, "correct_answer": "水泥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生用水泥固定了他的断腿。", "explanation": "这里应该用〈石膏〉。石膏用于医疗固定骨折，水泥是建筑材料，不能用来固定骨头。"}, {"text": "工人搬来一支水泥。", "explanation": "这里应该用〈袋〉或〈吨〉。“支”用于细长的物件，不用来量水泥。"}, {"text": "请用水泥把这张纸粘在墙上。", "explanation": "这里应该用〈胶水〉。水泥靠加水凝固，不能用来粘纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两个水泥，准备修院子。", "corrected_sentence": "他买了两袋水泥，准备修院子。", "error_description": "“水泥”是物质名词，应用量词“袋”（或“吨”）。“个”不能用于水泥，应改为“两袋水泥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把水泥们搬进了院子。", "corrected_sentence": "工人把水泥搬进了院子。", "error_description": "“水泥”是物质名词，不能加复数词尾“们”，应说“把水泥搬进了院子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
