INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体能动、能走来走去的本事。", "primary_collocate": null, "pronunciation": "huó dòng néng lì", "ipa": "xuo˧˥ tʊŋ˥˩ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "爷爷腿受伤以后，活动能力变差了。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他的活动能力正在慢慢恢复。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的活动能力不如年轻人，走路很慢。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病会影响孩子的活动能力，让他走不稳。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了三个月轮椅，她的活动能力下降了很多。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完手术，医生让他多练习，提高活动能力。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的腿好了，活动能力和以前一样。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的活动能力很强，八十岁还能爬山。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的活动能力很差，一个人走不到楼下。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位病人已经失去了活动能力，只能躺在床上。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体能动、能走动的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0240c25c-1339-443c-bf73-9fd83a71d5f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活动能力", "is_correct": true, "explanation": "活动能力：身体能活动、走动的本事，与“腿受伤”相符。"}, {"text": "智力", "is_correct": false, "explanation": "语义：腿受伤不会直接影响智力，“智力变差了”与句意不合。"}, {"text": "鉴赏力", "is_correct": false, "explanation": "搭配：“鉴赏力”指审美判断，不能和“腿受伤以后变差”搭配。"}, {"text": "词汇量", "is_correct": false, "explanation": "搭配：“词汇量”指词语的数量，不能用来说腿受伤后的变化。"}], "explanations": {"活动能力": "活动能力：身体能活动、走动的本事，与“腿受伤”相符。", "智力": "语义：腿受伤不会直接影响智力，“智力变差了”与句意不合。", "鉴赏力": "搭配：“鉴赏力”指审美判断，不能和“腿受伤以后变差”搭配。", "词汇量": "搭配：“词汇量”指词语的数量，不能用来说腿受伤后的变化。"}, "sentence_index": 0, "correct_answer": "活动能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校这学期组织了很多活动能力，丰富了课余生活。", "explanation": "这里应该用〈课外活动〉。活动能力指个体身体能动的本事，不指学校组织开展的各项活动。"}, {"text": "他的活动能力很强，能讲三种语言。", "explanation": "这里应该用〈表达能力〉。活动能力指身体能动，不指语言表达。"}, {"text": "这家公司的活动能力很强，业务遍布各地。", "explanation": "这里应该用〈扩张能力〉。活动能力指个体身体能动的本事，不能用来形容公司的业务拓展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活动能力", "is_correct": true, "explanation": "活动能力：身体能活动的能力，与“腿好了”相符。"}, {"text": "学历", "is_correct": false, "explanation": "语义：小猫的腿好了，“学历”与此毫不相干，句子荒谬。"}, {"text": "户口", "is_correct": false, "explanation": "搭配：“户口”不能用于形容动物的身体状况。"}, {"text": "身份", "is_correct": false, "explanation": "语义：“身份”指社会地位，与小猫的腿好了无关。"}], "explanations": {"活动能力": "活动能力：身体能活动的能力，与“腿好了”相符。", "学历": "语义：小猫的腿好了，“学历”与此毫不相干，句子荒谬。", "户口": "搭配：“户口”不能用于形容动物的身体状况。", "身份": "语义：“身份”指社会地位，与小猫的腿好了无关。"}, "sentence_index": 6, "correct_answer": "活动能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位经理的活动能力很强，任务都能按时完成。", "explanation": "这里应该用〈执行能力〉。活动能力指身体能动，不指办事、执行任务的能力。"}, {"text": "这首歌的活动能力很强，听了让人想跳舞。", "explanation": "这里应该用〈感染力〉。活动能力指身体能动的本事，不能用来形容歌曲的感染力。"}, {"text": "他活动能力充沛，一天工作十小时。", "explanation": "这里应该用〈精力〉。活动能力指身体能动的本事，不能说“充沛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人的活动能力很长，走路要人扶。", "corrected_sentence": "这位老人的活动能力很差，走路要人扶。", "error_description": "“活动能力”的高低用“强、差”描述，不能用“长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "训练后，他的活动能力增多了很多。", "corrected_sentence": "训练后，他的活动能力提高了很多。", "error_description": "“活动能力”不能与“增多”搭配，“增多”说数量，应说“提高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bade41-f44b-48bc-8fad-b923e7b51524') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
