INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95591, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个会里管事的人。", "primary_collocate": null, "pronunciation": "lǐ shì", "ipa": "li˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他是我们学会的理事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会有五位理事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生当了商会的理事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事今天要在会上讲话。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李是校友会的理事，常常帮大家做事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会里的理事每月开一次会。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选他做理事，因为他很热心。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位理事住在北京，不常来。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事们都同意这个办法。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当理事，帮会里做更多的事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "理事会", "label": "复合"}], "register": "书面", "sense_fingerprint": "理事：学会、协会里管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af1f0b90-466a-4ce3-a330-0972cf8aba73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95591, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：学会里管事的人，即听到的词。"}, {"text": "历史", "is_correct": false, "explanation": "历史 lìshǐ 的两个音节声调都与理事 lǐshì 不同（lì 与 lǐ，shǐ 与 shì），意思是过去发生的事情。"}, {"text": "历时", "is_correct": false, "explanation": "历时 lìshí 第一音节声调不同（lì 与 lǐ），第二音节也不同（shí 与 shì），意思是经历的时间。"}, {"text": "力士", "is_correct": false, "explanation": "力士 lìshì 只有第一音节声调不同（lì 与 lǐ），意思是力气大的人。"}, {"text": "你是", "is_correct": false, "explanation": "你是 nǐshì 第一音节声母不同（n 与 l），意思是“你是”。"}], "explanations": {"理事": "理事：学会里管事的人，即听到的词。", "历史": "历史 lìshǐ 的两个音节声调都与理事 lǐshì 不同（lì 与 lǐ，shǐ 与 shì），意思是过去发生的事情。", "历时": "历时 lìshí 第一音节声调不同（lì 与 lǐ），第二音节也不同（shí 与 shì），意思是经历的时间。", "力士": "力士 lìshì 只有第一音节声调不同（lì 与 lǐ），意思是力气大的人。", "你是": "你是 nǐshì 第一音节声母不同（n 与 l），意思是“你是”。"}, "sentence_index": null, "correct_answer": "理事"}, "level_3": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：学会中管事的成员，可以作“他是我们学会的”之后的身份。"}, {"text": "事情", "is_correct": false, "explanation": "语义：“事情”指事件，不指人，不能作“他是……的”的身份。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：“办公室”是处所，不能作人的身份。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：「椅子」是物品，不能作人的身份。"}], "explanations": {"理事": "理事：学会中管事的成员，可以作“他是我们学会的”之后的身份。", "事情": "语义：“事情”指事件，不指人，不能作“他是……的”的身份。", "办公室": "语义：“办公室”是处所，不能作人的身份。", "椅子": "语义：「椅子」是物品，不能作人的身份。"}, "sentence_index": 0, "correct_answer": "理事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学会新来了一只理事。", "explanation": "这里应该用〈位〉。指人的量词用“位”，“只”多用于动物或物品。"}, {"text": "这栋大楼是学会的理事。", "explanation": "这里应该用〈会馆〉。会馆是供团体活动的建筑，可以说“学会的会馆”；理事指人，不能指建筑。"}, {"text": "这家公司有五位理事。", "explanation": "这里应该用〈董事〉。董事是公司的管理成员，可以说“公司的董事”；理事用于协会、基金会等非营利团体，不用于公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：学会中管事的成员，符合“选他做……，因为他很热心”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能被选来担任职务。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“选……做”后要接可担任的职务，“厨房”是处所，不能作宾语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，也不能被选做职务。"}], "explanations": {"理事": "理事：学会中管事的成员，符合“选他做……，因为他很热心”的语境。", "桌子": "语义：“桌子”是物品，不能被选来担任职务。", "厨房": "配价：“选……做”后要接可担任的职务，“厨房”是处所，不能作宾语。", "天气": "语义：“天气”不是人，也不能被选做职务。"}, "sentence_index": 6, "correct_answer": "理事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府有三位理事。", "explanation": "这里应该用〈委员〉。政府部门的成员称委员，可以说“市政府的委员”；理事用于协会、基金会等非营利团体，不用于政府机构。"}, {"text": "这辆车是学会的理事。", "explanation": "这里应该用〈财产〉。财产是学会可以拥有的东西，可以说“学会的财产”；理事指人，不能指车辆。"}, {"text": "这家商店的理事每周都来查账。", "explanation": "这里应该用〈股东〉。股东是公司的出资人，可以说“商店的股东”；理事用于协会、基金会等团体，不用于商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "协会今年选出了两只新理事。", "corrected_sentence": "协会今年选出了两位新理事。", "error_description": "量词错误：“理事”指人，应用量词“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位理事们昨天来开会了。", "corrected_sentence": "那位理事昨天来开会了。", "error_description": "“们”错误：“那位”指一个人，不能再加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8f4407-400e-4cf6-bded-765ee8a5e6c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
