INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95599, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人因为一件事吵起来，谁也不让谁。", "primary_collocate": null, "pronunciation": "jiū fēn", "ipa": "tɕjoʊ˥ fən˥", "syllable_count": 2, "sentences": [{"text": "我不想和同事有纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人又为小事闹纠纷了。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子为玩具起了纠纷，谁也不让谁。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间不要为钱产生纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和邻居的纠纷越来越大了。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张和老李因为停车位有了纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学之间有了纠纷，要好好说。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻有纠纷时，最好不要大声说话。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有纠纷，只是想法不一样。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕和客人发生纠纷，所以一直很客气。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一起纠纷", "label": "量词"}, {"form": "一场纠纷", "label": "量词"}, {"form": "糾紛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人之间因事吵起来、互不相让", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95599, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纠纷", "is_correct": true, "explanation": "纠纷（jiū fēn）：两个人因为事情吵起来，是本题的正确答案。"}, {"text": "秋分", "is_correct": false, "explanation": "qiū 与 jiū 声母不同（q/j），意思是秋分（二十四节气之一）。"}, {"text": "加分", "is_correct": false, "explanation": "jiā 与 jiū 韵母不同（a/u），意思是加分、增加分数。"}, {"text": "丢分", "is_correct": false, "explanation": "diū 与 jiū 声母不同（d/j），意思是丢掉分数。"}, {"text": "积分", "is_correct": false, "explanation": "jī 与 jiū 韵母不同（少了 u），意思是积分、累积的分数。"}], "explanations": {"纠纷": "纠纷（jiū fēn）：两个人因为事情吵起来，是本题的正确答案。", "秋分": "qiū 与 jiū 声母不同（q/j），意思是秋分（二十四节气之一）。", "加分": "jiā 与 jiū 韵母不同（a/u），意思是加分、增加分数。", "丢分": "diū 与 jiū 声母不同（d/j），意思是丢掉分数。", "积分": "jī 与 jiū 韵母不同（少了 u），意思是积分、累积的分数。"}, "sentence_index": null, "correct_answer": "纠纷"}, "level_3": {"options": [{"text": "数据", "is_correct": false, "explanation": "语义：数据是数字资料，不能与“同事”发生“有”的关系，句子说不通。"}, {"text": "纠纷", "is_correct": true, "explanation": "纠纷：两人因事吵起来、互不相让，与“我不想和同事有”相合。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”不能与“同事”构成“有”的关系，搭配不成立。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指位置，与人际关系无关，句子不通。"}], "explanations": {"数据": "语义：数据是数字资料，不能与“同事”发生“有”的关系，句子说不通。", "纠纷": "纠纷：两人因事吵起来、互不相让，与“我不想和同事有”相合。", "数量": "搭配：“数量”不能与“同事”构成“有”的关系，搭配不成立。", "方向": "语义：方向指位置，与人际关系无关，句子不通。"}, "sentence_index": 0, "correct_answer": "纠纷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两块木头之间有纠纷，所以会发热。", "explanation": "这里应该用〈摩擦〉。纠纷是人与人之间因事吵起来，木头之间的接触要用〈摩擦〉。"}, {"text": "这台电脑有纠纷，经常死机。", "explanation": "这里应该用〈故障〉。纠纷指人与人争执不下，电脑出的问题要用〈故障〉。"}, {"text": "这支笔有纠纷，写起来总是断墨。", "explanation": "这里应该用〈毛病〉。纠纷指人与人吵起来，笔出的问题要用〈毛病〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能使同学之间“有了”它，句子说不通。"}, {"text": "纠纷", "is_correct": true, "explanation": "纠纷：同学之间争执不下，与“要好好说”相合。"}, {"text": "道路", "is_correct": false, "explanation": "搭配：“道路”不能用在“有了……要好好说”这样表示争执的句子里，搭配不成立。"}, {"text": "公式", "is_correct": false, "explanation": "语义：公式是数学表达，与同学之间的争执无关，句子不成立。"}], "explanations": {"天气": "语义：天气是自然现象，不能使同学之间“有了”它，句子说不通。", "纠纷": "纠纷：同学之间争执不下，与“要好好说”相合。", "道路": "搭配：“道路”不能用在“有了……要好好说”这样表示争执的句子里，搭配不成立。", "公式": "语义：公式是数学表达，与同学之间的争执无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "纠纷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两台服务器的设置发生了纠纷，需要修改。", "explanation": "这里应该用〈冲突〉。纠纷只用于人与人之间的争执，机器设置之间的不一致要用〈冲突〉。"}, {"text": "这辆纠纷让大家很头疼。", "explanation": "这里应该用〈起〉。纠纷的量词是“起”“场”“件”，“辆”用于车，不能用于纠纷。"}, {"text": "台风给沿海城市带来了巨大纠纷，但很快恢复了。", "explanation": "这里应该用〈冲击〉。纠纷指人与人之间的争执，自然灾害对城市的影响要用〈冲击〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们曾经有了过纠纷，现在已经和好了。", "corrected_sentence": "我们曾经有过纠纷，现在已经和好了。", "error_description": "体标重复：经历体“过”与完成体“了”不能同时用在“有”上，应只用“过”，说“有过纠纷”；“有了过纠纷”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们之间有很多纠纷们。", "corrected_sentence": "我们之间有很多纠纷。", "error_description": "词缀错误：“纠纷”是抽象名词，不能加“们”表示复数；应说“很多纠纷”，不能说“纠纷们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
