INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "争执不下的事情。", "primary_collocate": null, "pronunciation": "jiū fēn", "ipa": "tɕjoʊ˥ fən˥", "syllable_count": 2, "sentences": [{"text": "邻居之间有纠纷，他们去找警察帮忙。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起纠纷已经解决了。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用法律解决这个纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和客人发生了纠纷，经理马上来处理。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了土地的纠纷，两家人谈了很久。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是处理邻里纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场纠纷让两家人不再说话。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院正在审理这个纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和房东因为房租发生了纠纷。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的小纠纷，老师很快就解决了。", "target_word": "纠纷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一起纠纷", "label": "量词"}, {"form": "一场纠纷", "label": "量词"}, {"form": "糾紛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "争执不下、需要解决的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纠纷", "is_correct": true, "explanation": "纠纷（jiū fēn）：争执不下的事情，是本题的正确答案。"}, {"text": "秋分", "is_correct": false, "explanation": "qiū 与 jiū 声母不同（q/j），意思是秋分（二十四节气之一）。"}, {"text": "加分", "is_correct": false, "explanation": "jiā 与 jiū 韵母不同（a/u），意思是加分、增加分数。"}, {"text": "丢分", "is_correct": false, "explanation": "diū 与 jiū 声母不同（d/j），意思是丢掉分数。"}, {"text": "积分", "is_correct": false, "explanation": "jī 与 jiū 韵母不同（少了 u），意思是积分、累积的分数。"}], "explanations": {"纠纷": "纠纷（jiū fēn）：争执不下的事情，是本题的正确答案。", "秋分": "qiū 与 jiū 声母不同（q/j），意思是秋分（二十四节气之一）。", "加分": "jiā 与 jiū 韵母不同（a/u），意思是加分、增加分数。", "丢分": "diū 与 jiū 声母不同（d/j），意思是丢掉分数。", "积分": "jī 与 jiū 韵母不同（少了 u），意思是积分、累积的分数。"}, "sentence_index": null, "correct_answer": "纠纷"}, "level_3": {"options": [{"text": "友谊", "is_correct": false, "explanation": "语义：友谊是好感情，与“去找警察帮忙”的情况正好相反。"}, {"text": "纠纷", "is_correct": true, "explanation": "纠纷：争执不下的事，与“去找警察帮忙”相合。"}, {"text": "保险", "is_correct": false, "explanation": "搭配：“保险”不能用在“邻居之间有……”这样的句式里，搭配不成立。"}, {"text": "利息", "is_correct": false, "explanation": "语义：利息是借贷产生的钱，邻居之间不会因此“有利息”，句子说不通。"}], "explanations": {"友谊": "语义：友谊是好感情，与“去找警察帮忙”的情况正好相反。", "纠纷": "纠纷：争执不下的事，与“去找警察帮忙”相合。", "保险": "搭配：“保险”不能用在“邻居之间有……”这样的句式里，搭配不成立。", "利息": "语义：利息是借贷产生的钱，邻居之间不会因此“有利息”，句子说不通。"}, "sentence_index": 0, "correct_answer": "纠纷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只纠纷很麻烦，我们得尽快处理。", "explanation": "这里应该用〈起〉。纠纷的常用量词是“起”“场”，“只”不能修饰纠纷。"}, {"text": "这道数学纠纷，老师讲了三遍。", "explanation": "这里应该用〈问题〉。纠纷指人与人之间争执不下的事，数学题要用〈问题〉。"}, {"text": "这部手机出了纠纷，需要修理。", "explanation": "这里应该用〈故障〉。纠纷指人与人争执不下，手机出的问题要用〈故障〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是演出活动，不能使两家人“不再说话”。"}, {"text": "纠纷", "is_correct": true, "explanation": "纠纷：争执不下的事，能让两家人不再说话，与句子相合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试”不能作“让两家人不再说话”的原因，这个搭配不成立。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：讲座是知识讲授，不会让两家人“不再说话”，句子说不通。"}], "explanations": {"演唱会": "语义：演唱会是演出活动，不能使两家人“不再说话”。", "纠纷": "纠纷：争执不下的事，能让两家人不再说话，与句子相合。", "考试": "搭配：“考试”不能作“让两家人不再说话”的原因，这个搭配不成立。", "讲座": "语义：讲座是知识讲授，不会让两家人“不再说话”，句子说不通。"}, "sentence_index": 6, "correct_answer": "纠纷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车刹车时，轮胎和路面产生了纠纷。", "explanation": "这里应该用〈摩擦〉。纠纷只用于人与人之间的争执，轮胎与路面的接触要用〈摩擦〉。"}, {"text": "两个程序的数据发生了纠纷，需要修改。", "explanation": "这里应该用〈冲突〉。纠纷只用于人与人之间的争执，数据之间的不一致要用〈冲突〉。"}, {"text": "这台机器有纠纷，经常自己停下来。", "explanation": "这里应该用〈故障〉。纠纷指人与人争执不下，机器出的问题要用〈故障〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们以前发生了过纠纷。", "corrected_sentence": "他们以前发生过纠纷。", "error_description": "体标重复：经历体“过”与完成体“了”不能同时用在“发生”上，应只用“过”，说“发生过纠纷”；“发生了过纠纷”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很快把这只纠纷解决了。", "corrected_sentence": "我们很快把这起纠纷解决了。", "error_description": "量词错误：纠纷的量词应为“起”“场”等，“只”不能修饰纠纷；应说“把这起纠纷解决了”，而“把这只纠纷解决了”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
