INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以前常常去的那个地方。", "primary_collocate": null, "pronunciation": "lǎo dì fang", "ipa": "laʊ˨˩˦ ti˥˩ faŋ", "syllable_count": 3, "sentences": [{"text": "好久不见，我们又回到了老地方。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小饭馆是我们大学时的老地方。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，他还常回老地方看看。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老地方变了很多，我差点没认出来。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我们常去的老地方，现在已经没有了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想去老地方走一走，想想以前的事。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个公园是爷爷年轻时的老地方。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到老地方，他想起了很多朋友。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们以前常在老地方吃面，现在还想去。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老地方我已经十年没来过了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "以前常去、带有回忆色彩的旧地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95603, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老地方", "is_correct": true, "explanation": "正确：“回到了老地方”指回到以前常去的地方，符合“好久不见”的语境。"}, {"text": "老花镜", "is_correct": false, "explanation": "语义：“回到”接的是地点、时间或某人身边，“老花镜”是物品，说不通。"}, {"text": "老汤", "is_correct": false, "explanation": "语义：“老汤”是食物，不能作“回到”的地点或时间，说不通。"}, {"text": "旧书", "is_correct": false, "explanation": "语义：书不是地点，“回到旧书”说不通。"}], "explanations": {"老地方": "正确：“回到了老地方”指回到以前常去的地方，符合“好久不见”的语境。", "老花镜": "语义：“回到”接的是地点、时间或某人身边，“老花镜”是物品，说不通。", "老汤": "语义：“老汤”是食物，不能作“回到”的地点或时间，说不通。", "旧书": "语义：书不是地点，“回到旧书”说不通。"}, "sentence_index": 0, "correct_answer": "老地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的老地方，认识二十年了。", "explanation": "这里应该用〈老朋友〉。老地方指以前常去的地方，不能指人。"}, {"text": "这些老地方很便宜，大家都在买。", "explanation": "这里应该用〈旧货〉。旧货指用过的旧东西，老地方指以前常去的地方，不能用来指东西。"}, {"text": "老地方住在胡同里，每天晚上都出来散步。", "explanation": "这里应该用〈老人〉。老人指年纪大的人，老地方指以前常去的地方，不能住在胡同里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老地方", "is_correct": true, "explanation": "正确：爷爷年轻时常去的地方，可以说“是…的老地方”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：公园不是玩具，“是玩具”说不通。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：公园是地点，不是习惯，“是…的习惯”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：公园不是报酬，“是工资”说不通。"}], "explanations": {"老地方": "正确：爷爷年轻时常去的地方，可以说“是…的老地方”。", "玩具": "语义：公园不是玩具，“是玩具”说不通。", "习惯": "语义：公园是地点，不是习惯，“是…的习惯”说不通。", "工资": "语义：公园不是报酬，“是工资”说不通。"}, "sentence_index": 6, "correct_answer": "老地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的老地方身体不好，要常去医院。", "explanation": "这里应该用〈老伴〉。老伴指一起生活的配偶，老地方指以前常去的地方，不能指人。"}, {"text": "他是老地方，参加过战争。", "explanation": "这里应该用〈老兵〉。老兵指经历过战争、年头长的军人，老地方不能指人。"}, {"text": "他的老地方又犯了，又开始迟到。", "explanation": "这里应该用〈老毛病〉。老毛病指长期存在的坏习惯，老地方指以前常去的地方，不能指毛病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前常去老地方还在。", "corrected_sentence": "我们以前常去的老地方还在。", "error_description": "定语标记缺失：“常去”修饰“老地方”时需要“的”，应说“我们以前常去的老地方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我十年前去着那个老地方。", "corrected_sentence": "我十年前去过那个老地方。", "error_description": "体标错误：表示去过某地的经历要用“过”，“着”表示动作持续，不能用于“去”。正确说法是“去过那个老地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
