INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经常去的或约定好的老地点。", "primary_collocate": null, "pronunciation": "lǎo dì fang", "ipa": "laʊ˨˩˦ ti˥˩ faŋ", "syllable_count": 3, "sentences": [{"text": "明天下班后，老地方见。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "还是老地方，七点我在那儿等你。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到了吗？我已经在老地方了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说好了，老地方，不见不散。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚老地方吃饭，你别忘了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发短信说：“老地方，五分钟后到。”", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们常去的老地方是学校后门的小店。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去老地方吧，那儿的咖啡又好又便宜。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老地方的位子，我已经帮你留好了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次聚会我们都选老地方，大家都习惯了。", "target_word": "老地方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "双方默认的、约定见面的固定地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59499d32-9057-46d0-9d86-6bb1baf6c73a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老地方", "is_correct": true, "explanation": "正确：“明天下班后，老地方见”是约定见面的常用说法。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是可以约定见面的地点。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“见”后接的应是人或见面的地点，窗户不符合。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是见面的地方，“电视见”说不通。"}], "explanations": {"老地方": "正确：“明天下班后，老地方见”是约定见面的常用说法。", "作业": "语义：作业不是可以约定见面的地点。", "窗户": "搭配：“见”后接的应是人或见面的地点，窗户不符合。", "电视": "语义：电视不是见面的地方，“电视见”说不通。"}, "sentence_index": 0, "correct_answer": "老地方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老地方每天早上七点响，吵醒了全家。", "explanation": "这里应该用〈闹钟〉。闹钟是定时发出响声的钟表，老地方指约定见面的地点，不会发出声音。"}, {"text": "老地方做了几十年的木工，手艺很好。", "explanation": "这里应该用〈老师傅〉。老师傅指经验丰富的老工人，老地方指约定见面的地点，不能指人。"}, {"text": "他的老地方又上来了，大声说话。", "explanation": "这里应该用〈老脾气〉。老脾气指一个人长期的性子，老地方指约定见面的地点，不能指性子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老地方", "is_correct": true, "explanation": "正确：朋友们常去的地方可以说“朋友们常去的老地方”。"}, {"text": "老板", "is_correct": false, "explanation": "语义：老板是人，不是常去的地方，“是小店”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“常去的”只搭配地点或人，不搭配课本。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是可以常去的地方。"}], "explanations": {"老地方": "正确：朋友们常去的地方可以说“朋友们常去的老地方”。", "老板": "语义：老板是人，不是常去的地方，“是小店”说不通。", "课本": "搭配：“常去的”只搭配地点或人，不搭配课本。", "手机": "语义：手机不是可以常去的地方。"}, "sentence_index": 6, "correct_answer": "老地方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的老地方开朗，很爱交朋友。", "explanation": "这里应该用〈性格〉。性格指人的性情，老地方指约定见面的地点，不能用来形容人的性情。"}, {"text": "我收到了老地方，邀请我参加婚礼。", "explanation": "这里应该用〈请柬〉。请柬是邀请人参加活动的卡片，老地方指约定见面的地点，不能用来发出邀请。"}, {"text": "他的老地方忘了，只好重新设置。", "explanation": "这里应该用〈密码〉。密码是用来登录的一串字符，老地方指约定见面的地点，不能用来指需要记住的数字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天晚上七点，我们在老地方了见。", "corrected_sentence": "今天晚上七点，我们在老地方见。", "error_description": "错误：“了”位置错误，不能插在“老地方”和“见”之间；约定见面不用“了”，应说“我们在老地方见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们约好了在这只老地方碰面。", "corrected_sentence": "我们约好了在这个老地方碰面。", "error_description": "量词错误：“老地方”是地点，应用“个”，“只”用于动物或成对的东西。正确说法是“这个老地方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01bbc7a5-90cb-4a54-b92b-a1bb5793a932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
