INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95607, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在公司或店里上班的人。", "primary_collocate": null, "pronunciation": "zhí yuán", "ipa": "ʈʂɻ̩˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我姐姐是公司的职员。", "target_word": "职员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司的职员都要穿西装上班。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家小公司当职员，每天九点上班。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行职员今天下午要开会。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸以前是职员，现在自己开店。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位职员给我拿了一杯热茶。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司新来了两位职员，都很年轻。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市的职员正在把水果放到桌子上。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职员们下班以后常常一起吃饭。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做了五年职员，想换一个工作。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公司职员", "label": "复合"}, {"form": "银行职员", "label": "复合"}, {"form": "職員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在公司或商店里上班的普通工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95607, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：听到的是“职员”（zhí yuán），指在公司或店里上班的人。"}, {"text": "支援", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是援助、支持。"}, {"text": "志愿", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是自愿，如志愿者。"}, {"text": "职院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是职业技术学院。"}], "explanations": {"职员": "正确：听到的是“职员”（zhí yuán），指在公司或店里上班的人。", "支援": "zhī（第一声）与 zhí（第二声）声调不同，意思是援助、支持。", "志愿": "zhì（第四声）与 zhí（第二声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是自愿，如志愿者。", "职院": "yuàn（第四声）与 yuán（第二声）声调不同，意思是职业技术学院。"}, "sentence_index": null, "correct_answer": "职员"}, "level_3": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：“职员”指在公司或店里上班的人，符合“我姐姐是公司的”这一语境。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在学校读书的人，与“是公司的”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指接受治疗的人，与在公司工作不符。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“乘客”是搭乘交通工具的人，不能说“公司的乘客”。"}], "explanations": {"职员": "正确：“职员”指在公司或店里上班的人，符合“我姐姐是公司的”这一语境。", "学生": "语义：“学生”指在学校读书的人，与“是公司的”矛盾。", "病人": "语义：“病人”指接受治疗的人，与在公司工作不符。", "乘客": "搭配：“乘客”是搭乘交通工具的人，不能说“公司的乘客”。"}, "sentence_index": 0, "correct_answer": "职员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的职员都很认真地听课。", "explanation": "这里应该用〈学生〉。职员是在单位工作的人，上课听讲的是学生，“职员”不能这样用。"}, {"text": "舞台上的职员正在表演节目。", "explanation": "这里应该用〈演员〉。表演节目的是演员；职员指在单位里做事务工作的人。"}, {"text": "他的职员是律师。", "explanation": "这里应该用〈职业〉。“职员”指在单位工作的人，不能用来说某人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95607, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：“新来了两位”指新加入的工作人员，“职员”符合语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”是来旅游的人，不会在公司新来工作。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：“观众”指观看演出或比赛的人，不能用于公司新来的人员。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：“囚犯”指被关押的人，与在公司新来工作矛盾。"}], "explanations": {"职员": "正确：“新来了两位”指新加入的工作人员，“职员”符合语境。", "游客": "语义：“游客”是来旅游的人，不会在公司新来工作。", "观众": "搭配：“观众”指观看演出或比赛的人，不能用于公司新来的人员。", "囚犯": "语义：“囚犯”指被关押的人，与在公司新来工作矛盾。"}, "sentence_index": 6, "correct_answer": "职员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂里的职员正在组装机器。", "explanation": "这里应该用〈工人〉。组装机器的是工人；职员做的是一般事务，不做体力生产。"}, {"text": "医院的职员正在给病人做手术。", "explanation": "这里应该用〈医生〉。给病人做手术的是医生；职员只负责一般事务。"}, {"text": "这个村子的职员天天下地种田。", "explanation": "这里应该用〈农民〉。下地种田的是农民，“职员”指在单位里从事事务工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位职员们很热情。", "corrected_sentence": "那位职员很热情。", "error_description": "错误：“们”表示复数，不能与“那位”这种指单个人的词同用。正确说法是“那位职员很热情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在一家公司当一名的职员。", "corrected_sentence": "她在一家公司当一名职员。", "error_description": "错误：量词“名”与名词“职员”之间不能加“的”。正确说法是“她在一家公司当一名职员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
