INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、企业等单位中从事一般事务的工作人员。", "primary_collocate": null, "pronunciation": "zhí yuán", "ipa": "ʈʂɻ̩˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是政府机关的一名职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位职员负责处理单位的日常事务。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局里的职员每天要整理很多文件。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学毕业后，他进了一家企业当职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不是领导，只是普通职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个单位有三十多名职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让职员把材料送到办公室。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关职员的工资每月按时发放。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办公室的职员正在准备明天的会议。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生在这个单位做了十年职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "机关职员", "label": "复合"}, {"form": "企业职员", "label": "复合"}, {"form": "職員", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机关或企业单位里处理一般事务的工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
