version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：“职员”能把材料送到办公室，符合“经理让”的语境。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能去办公室送材料，与“经理让”的语境不符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能把材料送到办公室，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“石头”不能作为“让”的执行者去完成送材料的动作。"}], "explanations": {"职员": "正确：“职员”能把材料送到办公室，符合“经理让”的语境。", "猫": "语义：猫不能去办公室送材料，与“经理让”的语境不符。", "小狗": "语义：小狗不能把材料送到办公室，句意不通。", "石头": "配价：“石头”不能作为“让”的执行者去完成送材料的动作。"}, "sentence_index": 6, "correct_answer": "职员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位职员每天在手术台上为病人开刀。", "explanation": "这里应该用〈医生〉。为病人开刀的是医生；职员只负责一般事务，不做这类工作。"}, {"text": "这张桌子是我们单位的职员。", "explanation": "这里应该用〈家具〉。桌子是家具，“职员”指人，不能用来指物品。"}, {"text": "这位职员把飞机开上了天空。", "explanation": "这里应该用〈飞行员〉。开飞机的是飞行员；“职员”指在单位做一般事务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位职员们很认真。", "corrected_sentence": "这位职员很认真。", "error_description": "错误：“们”表示复数，不能与“这位”这种指单个人的词同用。正确说法是“这位职员很认真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在政府机关当一名的职员。", "corrected_sentence": "他在政府机关当一名职员。", "error_description": "错误：量词“名”与名词“职员”之间不能加“的”。正确说法是“他在政府机关当一名职员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
