INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认真听别人的意见或报告。", "primary_collocate": null, "pronunciation": "tīng qǔ", "ipa": "tʰiŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "经理认真听取了大家的意见。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板正在听取员工的工作报告。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，领导听取了三个部门的报告。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校应该多听取学生的意见。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要听取专家的建议。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长今天上午听取了工作汇报。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师听取过很多家长的意见。", "target_word": "听取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在做决定以前会先听取客户的意见。", "target_word": "听取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你们先听取一下他的报告。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听取完报告以后，大家开始讨论。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "听取了", "label": "体标"}, {"form": "听取过", "label": "体标"}, {"form": "聽取", "label": "繁体"}], "register": "正式", "sense_fingerprint": "认真听取别人的意见、建议或工作报告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听取", "is_correct": true, "explanation": "听取：表示经理认真听大家提出的意见，与句意相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不予理会，与“认真”的态度相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示轻视讥笑，与“认真”的态度矛盾，也不符合听取意见的语境。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”针对不满的事情，不能直接接“意见”作宾语。"}], "explanations": {"听取": "听取：表示经理认真听大家提出的意见，与句意相符。", "忽视": "语义：“忽视”表示不予理会，与“认真”的态度相反。", "嘲笑": "语义：“嘲笑”表示轻视讥笑，与“认真”的态度矛盾，也不符合听取意见的语境。", "抱怨": "搭配：“抱怨”针对不满的事情，不能直接接“意见”作宾语。"}, "sentence_index": 0, "correct_answer": "听取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在教室里听取了笑声。", "explanation": "这里应该用〈听到〉。“听取”指认真听别人的意见或报告，不能用来说听到笑声这类声音。"}, {"text": "我昨天听取了一场精彩的比赛。", "explanation": "这里应该用〈看〉。“听取”只用于意见、报告这类内容，比赛要用“看”。"}, {"text": "他听取完了那本小说，就去睡觉了。", "explanation": "这里应该用〈读〉。“听取”接的是意见、报告，小说是要阅读的作品，应该用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听取", "is_correct": true, "explanation": "听取：表示老师听过很多家长的意见，与句意相符。"}, {"text": "修剪", "is_correct": false, "explanation": "配价：“修剪”的对象是枝叶、头发等，不能接“家长的意见”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，与“家长的意见”无关，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”表示清洁，与“家长的意见”无关，句子说不通。"}], "explanations": {"听取": "听取：表示老师听过很多家长的意见，与句意相符。", "修剪": "配价：“修剪”的对象是枝叶、头发等，不能接“家长的意见”作宾语。", "煮": "语义：“煮”是烹饪，与“家长的意见”无关，句子说不通。", "洗": "语义：“洗”表示清洁，与“家长的意见”无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "听取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听取了一首很好听的歌。", "explanation": "这里应该用〈欣赏〉。“听取”指认真听别人的意见或报告，听歌这种欣赏不能用它，应该用“欣赏”。"}, {"text": "我听取了厨房里飘来的香味。", "explanation": "这里应该用〈闻到〉。“听取”只用于认真听别人的意见或报告，香味要靠嗅觉感受，应该用“闻到”。"}, {"text": "她听取了这幅画的颜色。", "explanation": "这里应该用〈看〉。“听取”只用于认真听别人的意见或报告，颜色要用眼睛看，应该用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王校长耐心听取得家长的建议。", "corrected_sentence": "王校长耐心听取了家长的建议。", "error_description": "错误：“听取得”应为“听取了”。“得”不能直接接在动词“听取”后面表示完成，表示动作已经完成要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "局长仔细被听取了居民的诉求。", "corrected_sentence": "局长仔细听取了居民的诉求。", "error_description": "错误：多写了“被”。“听取”是主动动词，“局长”是听取意见的人，不能用被动结构，应直接说“局长仔细听取了居民的诉求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
