INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被指责；被指出。", "primary_collocate": null, "pronunciation": "bèi zhǐ", "ipa": "peɪ˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司被指没有遵守规定。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书被指内容太旧。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款面包被指含糖量超标。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案被指不够清楚。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻被指不是真的。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影被指内容不真实。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告被指有很多错误。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店被指价格太贵。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的手机被指电池不好用。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥被指质量有问题。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物或机构被人指出有问题、受到批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被指", "is_correct": true, "explanation": "被指：表示这家公司被人指出没有遵守规定，与句意相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示庆贺喜事，与“没有遵守规定”这种过错相矛盾。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”多用于言论、文章，不能接“没有遵守规定”这类过失作宾语。"}, {"text": "恢复", "is_correct": false, "explanation": "配价：“恢复”需要带可以复原的对象，如健康、秩序，不能接“没有遵守规定”。"}], "explanations": {"被指": "被指：表示这家公司被人指出没有遵守规定，与句意相符。", "庆祝": "语义：“庆祝”表示庆贺喜事，与“没有遵守规定”这种过错相矛盾。", "发表": "搭配：“发表”多用于言论、文章，不能接“没有遵守规定”这类过失作宾语。", "恢复": "配价：“恢复”需要带可以复原的对象，如健康、秩序，不能接“没有遵守规定”。"}, "sentence_index": 0, "correct_answer": "被指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案被指很有创意。", "explanation": "这里应该用〈被称赞〉。“被指”表示被指出问题、受到批评，不能用来说方案有创意。"}, {"text": "那座桥被指设计得很美。", "explanation": "这里应该用〈被赞扬〉。“被指”是受到批评的意思，与“设计得很美”这类正面评价矛盾。"}, {"text": "这位老师被指教得很好。", "explanation": "这里应该用〈被表扬〉。“被指”指被指出毛病，这里说老师教得好，词义正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被指", "is_correct": true, "explanation": "被指：表示报告被人指出有很多错误，与句意相符。"}, {"text": "改善", "is_correct": false, "explanation": "语义：“改善”表示变好，与“有很多错误”的意思相矛盾。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、计划等，不能接“有很多错误”这样的状态。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”需要任务之类的对象，不能接表示状态的“有很多错误”。"}], "explanations": {"被指": "被指：表示报告被人指出有很多错误，与句意相符。", "改善": "语义：“改善”表示变好，与“有很多错误”的意思相矛盾。", "批准": "搭配：“批准”的对象是申请、计划等，不能接“有很多错误”这样的状态。", "完成": "配价：“完成”需要任务之类的对象，不能接表示状态的“有很多错误”。"}, "sentence_index": 6, "correct_answer": "被指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆被指为本市最干净的饭馆。", "explanation": "这里应该用〈被称为〉。“被指”表示受到指责、被指出问题，不能用来说饭馆是最干净的饭馆这样的赞誉，应该用“被称为”。"}, {"text": "这件衣服被指为今年最流行的款式。", "explanation": "这里应该用〈被评为〉。“被指”表示受到指责、被指出问题，不能用来说衣服是最流行的款式，应该用“被评为”。"}, {"text": "这份报告被指为一份优秀的研究报告。", "explanation": "这里应该用〈被认定〉。“被指”表示受到指责、被指出问题，报告是优秀研究这类评价应该用“被认定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件被被指安全性不够。", "corrected_sentence": "这个软件被指安全性不够。", "error_description": "错误：多写了一个“被”，写成“被被指”。“被指”已经是被动结构，再加一个“被”是重复，应直接说“被指安全性不够”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅被指了卫生条件很差。", "corrected_sentence": "这家餐厅被指卫生条件很差。", "error_description": "错误：“被指”后面多了“了”，写成“被指了”。“被指”表示受到指责，是不带体标的被动结构，后面直接接被指的内容，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
