INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95615, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有权的人听完以后，决定谁对谁错。", "primary_collocate": null, "pronunciation": "cái jué", "ipa": "tsʰaɪ˧˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "老师听完两个孩子的话，裁决谁对谁错。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有了纠纷，大家都请这位德高望重的长者来裁决。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人吵了很久，最后请村长来裁决。", "target_word": "裁决", "complexity_tier": "T3", "furigana": "liǎng gè rén chǎo le hěn jiǔ, zuìhòu qǐng cūnzhǎng lái cáijué.", "sentence_source": "generated"}, {"text": "班主任听完双方的话，当场裁决这件事。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长听完兄妹俩的话，裁决妹妹没有错。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方争执不下，请校长来裁决。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时有了争议，由裁判长裁决。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长听完两家人的话，裁决那棵树归李家。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都说自己对，没人能裁决。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方为工资争执，老板听完后裁决谁对谁错。", "target_word": "裁决", "complexity_tier": "T3", "furigana": "shuāngfāng wèi gōngzī zhēngzhí, lǎobǎn tīng wán hòu cáijué shéi duì shéi cuò.", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁决了", "label": "完成体"}, {"form": "裁决过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "有权者听完双方后判定对错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁决", "is_correct": true, "explanation": "正确：裁决指有权的人听完双方后判定对错，与“谁对谁错”的语境相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误并加以责备，不表示判定谁对谁错。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”的对象是伤心的人，不能与“谁对谁错”搭配。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”需要带被表扬的对象和原因，不能只接“谁对谁错”这样的判断结果。"}], "explanations": {"裁决": "正确：裁决指有权的人听完双方后判定对错，与“谁对谁错”的语境相符。", "批评": "语义：“批评”是指出错误并加以责备，不表示判定谁对谁错。", "安慰": "搭配：“安慰”的对象是伤心的人，不能与“谁对谁错”搭配。", "表扬": "配价：“表扬”需要带被表扬的对象和原因，不能只接“谁对谁错”这样的判断结果。"}, "sentence_index": 0, "correct_answer": "裁决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快裁决了今晚吃什么。", "explanation": "这里应该用〈决定〉。裁决指有权的人听取争议双方的意见后判定对错，吃什么没有争议，只能用决定。"}, {"text": "这个小问题，我们很快就裁决了。", "explanation": "这里应该用〈解决〉。裁决用于争议和纠纷，小问题只能说解决。"}, {"text": "校长裁决了放假的消息。", "explanation": "这里应该用〈宣布〉。裁决指对争议作出判定，放假的消息不是争议，应说宣布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁决", "is_correct": true, "explanation": "正确：句中的“争议”需要有权的人作出判定，应用裁决。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是不再追究过错，与需要判定是非的争议不符。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要说明感谢的对象和原因，“由裁判长感谢”语义不完整。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是给人信心，不表示对争议作出判定。"}], "explanations": {"裁决": "正确：句中的“争议”需要有权的人作出判定，应用裁决。", "原谅": "语义：“原谅”是不再追究过错，与需要判定是非的争议不符。", "感谢": "配价：“感谢”需要说明感谢的对象和原因，“由裁判长感谢”语义不完整。", "鼓励": "语义：“鼓励”是给人信心，不表示对争议作出判定。"}, "sentence_index": 6, "correct_answer": "裁决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生裁决他得的是感冒。", "explanation": "这里应该用〈判断〉。裁决指有权的人听取争议双方意见后作出判定，诊断病情没有争议，只能说判断。"}, {"text": "警方裁决他是小偷。", "explanation": "这里应该用〈认定〉。裁决是对争议依法作出判定，警方只是认定事实，不能用裁决。"}, {"text": "老师裁决了我的作文，给了高分。", "explanation": "这里应该用〈评判〉。裁决针对争议作出判定，评阅作文不涉及争议，应说评判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官把这件事裁决。", "corrected_sentence": "法官把这件事裁决了。", "error_description": "错误：“把”字句中“裁决”后缺少“了”，应为“法官把这件事裁决了”。“把”字句的谓语动词要带“了”或其他成分，单独的“裁决”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官还没裁决了这件事。", "corrected_sentence": "法官还没裁决这件事。", "error_description": "错误：“还没”否定尚未发生的动作，后面不能再加“了”，应为“法官还没裁决这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
