INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95616, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对争议事项审理后作出决定。", "primary_collocate": null, "pronunciation": "cái jué", "ipa": "tsʰaɪ˧˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "法院审理后，裁决公司要赔钱。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仲裁委员会裁决这家店应该退钱。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法庭听完证据，裁决孩子由妈妈照顾。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院昨天裁决，这块地归农民所有。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方为合同吵了很久，法院终于裁决了。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仲裁庭看过所有材料，裁决工厂没有错。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事由国际法庭来裁决。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审理了三天，才裁决这个案子。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院裁决他败诉，他很不服气。", "target_word": "裁决", "complexity_tier": "T3", "furigana": "fǎyuàn cáijué tā bàisù, tā hěn bù fúqì.", "sentence_source": "generated"}, {"text": "委员会审理后裁决，两家公司各付一半钱。", "target_word": "裁决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裁决了", "label": "完成体"}, {"form": "裁决过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "法院或仲裁机构审理争议后作出决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97aefee6-1d4b-4741-ba2b-68199e1010b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁决", "is_correct": true, "explanation": "正确：法院审理后作出判定，裁决指争议中由有权机构决定结果，与“要赔钱”相符。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”是同意某项申请，不表示判定赔偿。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是不追究过错，与“要赔钱”的判定相反。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象是做得好的人或事，不能与“要赔钱”搭配。"}], "explanations": {"裁决": "正确：法院审理后作出判定，裁决指争议中由有权机构决定结果，与“要赔钱”相符。", "批准": "语义：“批准”是同意某项申请，不表示判定赔偿。", "原谅": "语义：“原谅”是不追究过错，与“要赔钱”的判定相反。", "表扬": "搭配：“表扬”的对象是做得好的人或事，不能与“要赔钱”搭配。"}, "sentence_index": 0, "correct_answer": "裁决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板昨天裁决，明天开会。", "explanation": "这里应该用〈决定〉。裁决指法院或仲裁机构审理争议后作出决定，开会安排不是争议。"}, {"text": "这道数学题，我们很快裁决了。", "explanation": "这里应该用〈解决〉。裁决用于争议和纠纷，数学题只能说解决。"}, {"text": "学校裁决了奖学金的名单。", "explanation": "这里应该用〈公布〉。裁决针对争议作出判定，名单不是争议，应说公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裁决", "is_correct": true, "explanation": "正确：国际法庭对争议作出判定，应用裁决。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”的对象是人，不能说“来安慰这件事”。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是表示庆贺，与对争议作出判定不符。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”后要接劝说的对象和内容，句中没有这些成分。"}], "explanations": {"裁决": "正确：国际法庭对争议作出判定，应用裁决。", "安慰": "搭配：“安慰”的对象是人，不能说“来安慰这件事”。", "祝贺": "语义：“祝贺”是表示庆贺，与对争议作出判定不符。", "劝": "配价：“劝”后要接劝说的对象和内容，句中没有这些成分。"}, "sentence_index": 6, "correct_answer": "裁决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生裁决他得了肺炎。", "explanation": "这里应该用〈诊断〉。裁决指对争议作出判定，诊断病情不涉及争议，应说诊断。"}, {"text": "工程师裁决了这座桥。", "explanation": "这里应该用〈设计〉。裁决指对争议作出判定，设计桥梁不涉及争议，应说设计。"}, {"text": "秘书裁决了会议的内容。", "explanation": "这里应该用〈记录〉。裁决指对争议作出判定，记录会议内容不涉及争议，应说记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院把这个案子裁决。", "corrected_sentence": "法院把这个案子裁决了。", "error_description": "错误：“把”字句中“裁决”后缺少“了”，应为“法院把这个案子裁决了”。“把”字句的谓语动词要带“了”或其他成分，单独的“裁决”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院还没裁决了这个案子。", "corrected_sentence": "法院还没裁决这个案子。", "error_description": "错误：“还没”否定尚未发生的动作，后面不能再加“了”，应为“法院还没裁决这个案子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2894a9b7-ac26-448a-93eb-7e862341a584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
