INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95624, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "利用职务之便非法占有公共财物。", "primary_collocate": null, "pronunciation": "tān wū", "ipa": "tʰan˥ u˥", "syllable_count": 2, "sentences": [{"text": "那个官员利用职务之便贪污了很多公款。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位局长因为贪污丢了工作。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他管着学校的建设资金，却贪污了一部分。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院说，这名干部贪污了三百万元。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪污公共财物是犯法的，要受到处罚。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长利用手里的权力贪污了修路的钱。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老干部从来没有贪污过一分钱。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位市长贪污了很多年，最后进了监狱。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，有个官员贪污救灾物资。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在认真调查他贪污的事情。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贪污了", "label": "体标"}, {"form": "贪污过", "label": "体标"}, {"form": "贪污犯", "label": "复合"}, {"form": "贪污罪", "label": "复合"}, {"form": "貪污", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "官员或管理者利用职权非法占有公共财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贪污", "is_correct": true, "explanation": "正确。“利用职务之便”后接“贪污公款”，指非法占有公家的钱，与句意一致。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把坏了的东西修好，与“很多公款”搭配不通，句意荒谬。"}, {"text": "发起", "is_correct": false, "explanation": "搭配：“发起”接活动或行动，不能接“公款”作宾语。"}, {"text": "栽种", "is_correct": false, "explanation": "语义：“栽种”指种植植物，与“公款”搭配不通，句意荒谬。"}], "explanations": {"贪污": "正确。“利用职务之便”后接“贪污公款”，指非法占有公家的钱，与句意一致。", "修理": "语义：“修理”指把坏了的东西修好，与“很多公款”搭配不通，句意荒谬。", "发起": "搭配：“发起”接活动或行动，不能接“公款”作宾语。", "栽种": "语义：“栽种”指种植植物，与“公款”搭配不通，句意荒谬。"}, "sentence_index": 0, "correct_answer": "贪污"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他贪污了朋友的三百万元存款。", "explanation": "这里应该用〈侵占〉。贪污只用于公家的财物，朋友的存款属于个人，应该说〈侵占〉。"}, {"text": "他贪污了邻居的自行车。", "explanation": "这里应该用〈偷〉。贪污只用于公家的财物，邻居的自行车属于个人，拿别人的东西应说〈偷〉。"}, {"text": "这家工厂贪污了工人的工资。", "explanation": "这里应该用〈克扣〉。贪污指公职人员非法占有公款，工厂扣下工人的工资应说〈克扣〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贪污", "is_correct": true, "explanation": "正确。“从来没有……过一分钱”说的是没有非法占有公款，只有“贪污”符合句意。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”接的是植物或田地，不能接“一分钱”作宾语，句子不成立。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”接的是树木或物体，不能接“一分钱”作宾语，句子不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能接“一分钱”作宾语，句子不成立。"}], "explanations": {"贪污": "正确。“从来没有……过一分钱”说的是没有非法占有公款，只有“贪污”符合句意。", "浇灌": "搭配：“浇灌”接的是植物或田地，不能接“一分钱”作宾语，句子不成立。", "砍": "搭配：“砍”接的是树木或物体，不能接“一分钱”作宾语，句子不成立。", "唱": "搭配：“唱”不能接“一分钱”作宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "贪污"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他贪污了老人的积蓄。", "explanation": "这里应该用〈侵占〉。贪污只用于公家的钱，老人的积蓄属于个人，非法据为己有应说〈侵占〉。"}, {"text": "强盗贪污了路人的钱。", "explanation": "这里应该用〈抢劫〉。贪污的人要有职务，钱要是公家的；强盗抢路人的钱应说〈抢劫〉。"}, {"text": "他贪污了老板的好处。", "explanation": "这里应该用〈收受〉。贪污针对公家的财物，老板给的好处是私人馈赠，接受好处应说〈收受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个官员贪污很厉害，后来被抓了。", "corrected_sentence": "这个官员贪污得很厉害，后来被抓了。", "error_description": "错误：“贪污很厉害”。正确：“贪污得很厉害”。动词后接程度补语时，要用“得”把动词和补语连起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把公款都贪污。", "corrected_sentence": "他把公款都贪污了。", "error_description": "错误：“他把公款都贪污”。正确：“他把公款都贪污了”。“把”字句中动词后面要有“了”等成分，句子才完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
