INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始说话；也指向人提出请求。", "primary_collocate": null, "pronunciation": "kāi kǒu", "ipa": "kʰaɪ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我不好意思开口向他借钱。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题就开口问老师。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不开口求人。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你需要帮忙就开口，我一定来。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开口要了一个很高的价钱。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，经理先开口说了几句。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎么开口跟她说这件事。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱面子，有困难也不开口。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚上学，不敢开口回答问题。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开口就要我帮他写作业。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了口", "label": "体标（了）"}, {"form": "开过口", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "开始说话或向人提出请求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“借钱”的请求意思相反，句子不通。"}, {"text": "开口", "is_correct": true, "explanation": "开口：开口提出请求，与“向他借钱”的语境相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”不能作为借钱前的动作，句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语，“不好意思送向他借钱”不成句。"}], "explanations": {"拒绝": "语义：“拒绝”与“借钱”的请求意思相反，句子不通。", "开口": "开口：开口提出请求，与“向他借钱”的语境相合。", "感谢": "语义：“感谢”不能作为借钱前的动作，句意不通。", "送": "配价：“送”需要宾语，“不好意思送向他借钱”不成句。"}, "sentence_index": 0, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子一开口笑，大家都跟着笑了。", "explanation": "这里的“开口笑”指“笑起来”，与“开口提出请求”无关。"}, {"text": "这篇文章的开口很精彩，读者一下子就被吸引了。", "explanation": "这里的“开口”指文章的开头，与“开始说话或提出请求”无关。"}, {"text": "“啊”是开口音，发音时嘴张得比较大。", "explanation": "这里的“开口”是语音学术语，指发音时口腔张开度较大，与“张嘴说话”和“提出请求”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭嘴", "is_correct": false, "explanation": "语义：“闭嘴”与“跟她说这件事”的意思矛盾，句子不通。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”要带宾语，“怎么拿跟她说”不成句。"}, {"text": "开口", "is_correct": true, "explanation": "开口：开口说话，与“跟她说这件事”相合。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”与“跟她说这件事”的语境不合，句子要说的是怎样讲出这件事。"}], "explanations": {"闭嘴": "语义：“闭嘴”与“跟她说这件事”的意思矛盾，句子不通。", "拿": "配价：“拿”要带宾语，“怎么拿跟她说”不成句。", "开口": "开口：开口说话，与“跟她说这件事”相合。", "笑": "语义：“笑”与“跟她说这件事”的语境不合，句子要说的是怎样讲出这件事。"}, "sentence_index": 6, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开口吃了一大口面条。", "explanation": "这里应该用〈张口〉。“开口”表示说话或提出请求，吃东西要用“张口”。"}, {"text": "这只碗的开口很宽，适合盛汤。", "explanation": "这里的“开口”指碗口，是名词，与“开口说话或提出请求”无关。"}, {"text": "铁皮上的开口太小，装不进管道。", "explanation": "这里的“开口”是名词，指孔洞、缺口，与“开始说话或提出请求”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很要面子，从不开了口求人。", "corrected_sentence": "他很要面子，从不开口求人。", "error_description": "错误：“从不”后的“开口”之间多了“了”；正确：“从不开口求人”。“从不”表示习惯性否定，不能与完成体“了”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开口过，我就答应了他。", "corrected_sentence": "他一开口，我就答应了他。", "error_description": "错误：“一……就……”句表示紧接着发生的动作，“开口”后加“过”（经历体）不合此语境；应说“他一开口，我就答应了他。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指这一期之后的一期。"}, {"text": "冠军", "is_correct": false, "explanation": "冠军是名次，与“上期”没有反义关系。"}, {"text": "节目", "is_correct": false, "explanation": "节目指表演的内容，与“上期”没有反义关系。"}, {"text": "书架", "is_correct": false, "explanation": "书架是家具，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指这一期之后的一期。", "冠军": "冠军是名次，与“上期”没有反义关系。", "节目": "节目指表演的内容，与“上期”没有反义关系。", "书架": "书架是家具，与“上期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指这一期之后的一期。"}, {"text": "课本", "is_correct": false, "explanation": "课本是教材，与“上期”没有反义关系。"}, {"text": "旅馆", "is_correct": false, "explanation": "旅馆是住宿场所，与“上期”没有反义关系。"}, {"text": "黑板", "is_correct": false, "explanation": "黑板是教学用具，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指这一期之后的一期。", "课本": "课本是教材，与“上期”没有反义关系。", "旅馆": "旅馆是住宿场所，与“上期”没有反义关系。", "黑板": "黑板是教学用具，与“上期”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一次的前面一次。", "primary_collocate": null, "pronunciation": "shàng qī", "ipa": "ʂɑŋ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "上期的节目我没看，这期很好看。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本杂志比上期厚了很多。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期杂志讲了第五课的语法，这期讲第六课。", "target_word": "上期", "complexity_tier": "T3", "furigana": "shàng qī zá zhì jiǎng le dì wǔ kè de yǔ fǎ, zhè qī jiǎng dì liù kè.", "sentence_source": "generated"}, {"text": "上期的杂志他还没看完，这期又出版了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还留着上期的画报。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上期没卖完的杂志，这期打五折。", "target_word": "上期", "complexity_tier": "T3", "furigana": "shàng qī méi mài wán de zá zhì, zhè qī dǎ wǔ zhé.", "sentence_source": "generated"}, {"text": "请看上期的故事，再看这期的结局。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把上期的杂志借给朋友了。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上期的问题，这期老师来回答。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期的封面和上期完全不一样。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "杂志、节目、课程等这一期之前的那一期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指杂志等这一期之前的一期。"}, {"text": "上机", "is_correct": false, "explanation": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。"}, {"text": "上衣", "is_correct": false, "explanation": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。"}, {"text": "上司", "is_correct": false, "explanation": "s 与 q 声母不同，上司意思是上级、领导。"}, {"text": "上气", "is_correct": false, "explanation": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}], "explanations": {"上期": "正确：上期指杂志等这一期之前的一期。", "上机": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。", "上衣": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。", "上司": "s 与 q 声母不同，上司意思是上级、领导。", "上气": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "上期"}, "level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指上一期节目，与后文的“这期”相对。"}, {"text": "本期", "is_correct": false, "explanation": "语义：“本期”与后文的“这期”指同一期，前后自相重复，句意矛盾。"}, {"text": "上册", "is_correct": false, "explanation": "语义：“上册”指书籍的前一册，不用于按期播出的节目，与“节目”不搭配。"}, {"text": "上篇", "is_correct": false, "explanation": "搭配：“篇”用于文章、书籍，不用于按期播出的节目。"}], "explanations": {"上期": "正确：上期指上一期节目，与后文的“这期”相对。", "本期": "语义：“本期”与后文的“这期”指同一期，前后自相重复，句意矛盾。", "上册": "语义：“上册”指书籍的前一册，不用于按期播出的节目，与“节目”不搭配。", "上篇": "搭配：“篇”用于文章、书籍，不用于按期播出的节目。"}, "sentence_index": 0, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们上期见面是在去年。", "explanation": "这里应该用〈上次〉。“上期”只用于杂志等按期出版的前一期，一次性的见面要说“上次”。"}, {"text": "上期的地震很严重。", "explanation": "这里应该用〈那次〉。“上期”用于杂志、节目等按期出版或播出的前一期，地震是一次性的自然灾害，应说“那次”。"}, {"text": "上期的婚礼很热闹。", "explanation": "这里应该用〈上回〉。婚礼是一次性的事，不属于按期出版的东西，不能说“上期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指前一期，与后文的“这期的结局”依次对应。"}, {"text": "末期", "is_correct": false, "explanation": "语义：末期指最后阶段，不是可以阅读的一期，与“再看这期的结局”的先后顺序矛盾。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是一次性的演出，没有按期连载的“这期”，与“再看这期的结局”的语境不符。"}, {"text": "年终", "is_correct": false, "explanation": "语义：“年终”是年末这一时间点，不是按期出版的一期，与“这期”的语境不符。"}], "explanations": {"上期": "正确：上期指前一期，与后文的“这期的结局”依次对应。", "末期": "语义：末期指最后阶段，不是可以阅读的一期，与“再看这期的结局”的先后顺序矛盾。", "演唱会": "语义：演唱会是一次性的演出，没有按期连载的“这期”，与“再看这期的结局”的语境不符。", "年终": "语义：“年终”是年末这一时间点，不是按期出版的一期，与“这期”的语境不符。"}, "sentence_index": 6, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上期搬家花了很多时间。", "explanation": "这里应该用〈前一次〉。“上期”只用于按期出版或计算的事物，搬家是一次性的事。"}, {"text": "上期我去过上海。", "explanation": "这里应该用〈以前〉。“上期”不用于个人经历中的过去，只指前一期。"}, {"text": "上期事故的原因还没查清。", "explanation": "这里应该用〈那次〉。“上期”只指按期的前一期，单次事故要说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没看上期个杂志。", "corrected_sentence": "我还没看上期的杂志。", "error_description": "量词误用：“上期”作定语修饰“杂志”，中间应用结构助词“的”，不能用量词“个”。应说“上期的杂志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我借了上期地杂志。", "corrected_sentence": "我借了上期的杂志。", "error_description": "结构助词错误：“上期”修饰“杂志”，应用“的”，不能用“地”。“地”用于修饰动词、形容词，不用于名词前的定语。应说“上期的杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指后一个统计期。"}, {"text": "房东", "is_correct": false, "explanation": "房东是出租房屋的人，与“上期”没有反义关系。"}, {"text": "押金", "is_correct": false, "explanation": "押金是租房时交的款项，与“上期”没有反义关系。"}, {"text": "水电费", "is_correct": false, "explanation": "水电费是费用名称，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指后一个统计期。", "房东": "房东是出租房屋的人，与“上期”没有反义关系。", "押金": "押金是租房时交的款项，与“上期”没有反义关系。", "水电费": "水电费是费用名称，与“上期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指后一个统计期。"}, {"text": "合同", "is_correct": false, "explanation": "合同是双方约定的文书，与“上期”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指大气状况，与“上期”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是种植花草的地方，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指后一个统计期。", "合同": "合同是双方约定的文书，与“上期”没有反义关系。", "天气": "天气指大气状况，与“上期”没有反义关系。", "花园": "花园是种植花草的地方，与“上期”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上一期；前一个时期。", "primary_collocate": null, "pronunciation": "shàng qī", "ipa": "ʂɑŋ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这个月的销售额比上期多了一成。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的成绩不好，这学期他很努力。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司上期赚了不少钱。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的利润是五十万，这期是八十万。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "与上期相比，今年的用水量少了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的业绩还没统计完，这期的数字又出来了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上期的考试成绩比这次好。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看一下上期的账目。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期的支出比上期少得多。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的房租已经交了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "账目、成绩、业绩等按期计算时，前一个时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指账目、成绩等按期计算的前一个时期。"}, {"text": "上机", "is_correct": false, "explanation": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。"}, {"text": "上衣", "is_correct": false, "explanation": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。"}, {"text": "上司", "is_correct": false, "explanation": "s 与 q 声母不同，上司意思是上级、领导。"}, {"text": "上气", "is_correct": false, "explanation": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}], "explanations": {"上期": "正确：上期指账目、成绩等按期计算的前一个时期。", "上机": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。", "上衣": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。", "上司": "s 与 q 声母不同，上司意思是上级、领导。", "上气": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "上期"}, "level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指上一个统计期，与“这个月”相对。"}, {"text": "本期", "is_correct": false, "explanation": "语义：“本期”就是“这个月”所在的时期，拿销售额与自身比较，不成立。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：下个月尚未发生，不能与已经发生的销售额作比较。"}, {"text": "书店", "is_correct": false, "explanation": "配价：“比”的对象应是同类的时段或数量，书店不能与销售额相比。"}], "explanations": {"上期": "正确：上期指上一个统计期，与“这个月”相对。", "本期": "语义：“本期”就是“这个月”所在的时期，拿销售额与自身比较，不成立。", "下个月": "语义：下个月尚未发生，不能与已经发生的销售额作比较。", "书店": "配价：“比”的对象应是同类的时段或数量，书店不能与销售额相比。"}, "sentence_index": 0, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上期的合同已经签了。", "explanation": "这里应该用〈上次〉。“上期”用于账目等按期计算的时期，合同是一次性的事，应说“上次”。"}, {"text": "上期的毕业典礼很隆重。", "explanation": "这里应该用〈上一届〉。“上期”用于账目等按期计算的时期，毕业典礼是一次性的事，应说“上一届”。"}, {"text": "上期出差我去了三个城市。", "explanation": "这里应该用〈那次〉。“上期”用于按期计算的时期，一次出差要说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指前一个考核时期，与“这次”相对。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“演唱会”不能作“考试成绩”的时段限定。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂不是考核时段，与“考试成绩”不相容。"}, {"text": "考场", "is_correct": false, "explanation": "搭配：考场是考试地点，不能用来限定“成绩”的时段。"}], "explanations": {"上期": "正确：上期指前一个考核时期，与“这次”相对。", "演唱会": "搭配：“演唱会”不能作“考试成绩”的时段限定。", "食堂": "语义：食堂不是考核时段，与“考试成绩”不相容。", "考场": "搭配：考场是考试地点，不能用来限定“成绩”的时段。"}, "sentence_index": 6, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上期买房的时候我还在上学。", "explanation": "这里应该用〈当时〉。“上期”用于账目等按期计算的时期，买房是一次性的事。"}, {"text": "上期手术很成功。", "explanation": "这里应该用〈前一次〉。手术是一次性的事，不能用“上期”。"}, {"text": "上期的洪水淹了很多房子。", "explanation": "这里应该用〈那次〉。“上期”用于按期计算或出版的时期，洪水是一次性的自然灾害，应说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司还没结算上期地账目。", "corrected_sentence": "公司还没结算上期的账目。", "error_description": "结构助词错误：“上期”修饰“账目”，应用结构助词“的”，不能用“地”。应说“上期的账目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个上期的收入比这期高。", "corrected_sentence": "上期的收入比这期高。", "error_description": "指示词错误：“上期”本身已指前一个统计期，不能再用“这个”限定，应去掉“这个”，说“上期的收入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
