INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95641, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在全世界里排第一，比所有人都好。", "primary_collocate": null, "pronunciation": "shì jiè dì yī", "ipa": "ʂɻ̩˥˩ tɕje˥˩ ti˥˩ i˥", "syllable_count": 4, "sentences": [{"text": "他跳高跳得很好，是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师说自己做的菜世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的面条在我心里是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她游泳游得快极了，简直世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总说他的足球踢得世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩画画画得世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打乒乓球的水平是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得我们的队长跑步世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想成为唱歌世界第一的人。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他下棋下得世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "某人的技能或水平比世界上所有人都好（夸赞或自夸）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界第一", "is_correct": true, "explanation": "正确：“跳高跳得很好，是世界第一”，表示跳高水平比所有人都好，与句意相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容性情或环境，与跳高的水平无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述身材，不用来评价跳高技能。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境或天气，不能评价跳高的水平。"}], "explanations": {"世界第一": "正确：“跳高跳得很好，是世界第一”，表示跳高水平比所有人都好，与句意相符。", "安静": "语义：“安静”形容性情或环境，与跳高的水平无关。", "高大": "体貌：“高大”描述身材，不用来评价跳高技能。", "潮湿": "语义：“潮湿”形容环境或天气，不能评价跳高的水平。"}, "sentence_index": 0, "correct_answer": "世界第一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在小区的围棋比赛中下得世界第一。", "explanation": "这里应该用〈小区第一〉。“世界第一”的范围是全世界，用在小区的比赛中前后矛盾，应说“小区第一”。"}, {"text": "她游出了世界第一。", "explanation": "这里应该用〈世界纪录〉。游出的是成绩或纪录，“世界第一”表示排名，不能说游出排名。"}, {"text": "她的书法在班里世界第一。", "explanation": "这里应该用〈班里第一〉。“世界第一”的范围是全世界，用在班里前后矛盾，应说“班里第一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界第一", "is_correct": true, "explanation": "正确：“水平是世界第一”，表示打乒乓球的水平比所有人都好，与句意相符。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”是颜色，不能用来描述水平。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，不能用来评价打球的水平。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”形容温度，不能用来评价打球的水平。"}], "explanations": {"世界第一": "正确：“水平是世界第一”，表示打乒乓球的水平比所有人都好，与句意相符。", "红色": "语义：“红色”是颜色，不能用来描述水平。", "沙哑": "语义：“沙哑”形容嗓音，不能用来评价打球的水平。", "冷": "语义：“冷”形容温度，不能用来评价打球的水平。"}, "sentence_index": 6, "correct_answer": "世界第一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在全校围棋比赛中下得世界第一。", "explanation": "这里应该用〈全校第一〉。“世界第一”的范围是全世界，用在全校范围内前后矛盾，应说“全校第一”。"}, {"text": "他在本市的比赛中跑得世界第一。", "explanation": "这里应该用〈本市第一〉。“世界第一”的范围是全世界，用在本市的比赛中前后矛盾，应说“本市第一”。"}, {"text": "她在寝室的歌唱比赛中唱得世界第一。", "explanation": "这里应该用〈寝室第一〉。“世界第一”的范围是全世界，用在寝室的比赛中前后矛盾，应说“寝室第一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大叔修车修得很世界第一。", "corrected_sentence": "这位大叔修车修得世界第一。", "error_description": "错误形式：“很世界第一”；正确形式：“世界第一”。“世界第一”本身已经表示最高水平，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跳舞跳得最世界第一。", "corrected_sentence": "他跳舞跳得世界第一。", "error_description": "多加了“最”：“世界第一”本身已经表示最高水平，前面不能再加“最”。正确为「他跳舞跳得世界第一。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
