INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在全世界范围内排名首位。", "primary_collocate": null, "pronunciation": "shì jiè dì yī", "ipa": "ʂɻ̩˥˩ tɕje˥˩ ti˥˩ i˥", "syllable_count": 4, "sentences": [{"text": "这个国家的大米产量是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的高铁里程世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的手机销量曾经是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的茶叶出口量排世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的长度是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的图书馆藏书量世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口的货物量排在世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种汽车的销量去年是世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的网购人数世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水量排世界第一。", "target_word": "世界第一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "在全世界的排名中位于首位（产量、销量、长度等数据）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界第一", "is_correct": true, "explanation": "正确：“产量排名全世界第一”，与句意相符。"}, {"text": "大米", "is_correct": false, "explanation": "语义：产量是数量或排名，大米是一种谷物，不能充当产量的值。"}, {"text": "亚洲", "is_correct": false, "explanation": "搭配：“产量是”后不能接洲名，不能表示排名。"}, {"text": "学生", "is_correct": false, "explanation": "语义：产量是数量或排名，学生不能作为产量的值。"}], "explanations": {"世界第一": "正确：“产量排名全世界第一”，与句意相符。", "大米": "语义：产量是数量或排名，大米是一种谷物，不能充当产量的值。", "亚洲": "搭配：“产量是”后不能接洲名，不能表示排名。", "学生": "语义：产量是数量或排名，学生不能作为产量的值。"}, "sentence_index": 0, "correct_answer": "世界第一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位运动员刷新了世界第一。", "explanation": "这里应该用〈世界纪录〉。刷新的对象是具体的成绩或纪录，“世界第一”表示排名首位，不能说刷新排名。"}, {"text": "她在学校的歌唱比赛中世界第一。", "explanation": "这里应该用〈学校第一〉。“世界第一”的范围是全世界，用在学校的比赛中前后矛盾，应说“学校第一”。"}, {"text": "我们班的同学在本市比赛中世界第一。", "explanation": "这里应该用〈本市第一〉。“世界第一”的范围是全世界，用在本市的比赛中前后矛盾，应说“本市第一”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界第一", "is_correct": true, "explanation": "正确：“排在世界第一”，表示货物量排名全世界首位，与句意相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：货物量的排名不能排在一座建筑物之后，图书馆不能作为排名位置。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“排在”要接名次或位置，学校不是可以排列的位次。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”不能用来表示排名，与货物量的排位无关。"}], "explanations": {"世界第一": "正确：“排在世界第一”，表示货物量排名全世界首位，与句意相符。", "图书馆": "语义：货物量的排名不能排在一座建筑物之后，图书馆不能作为排名位置。", "学校": "语义：“排在”要接名次或位置，学校不是可以排列的位次。", "安静": "语义：“安静”不能用来表示排名，与货物量的排位无关。"}, "sentence_index": 6, "correct_answer": "世界第一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试在班里世界第一。", "explanation": "这里应该用〈班里第一〉。“世界第一”的范围是全世界，用在班级范围内前后矛盾，应说“班里第一”。"}, {"text": "他在全国的排名中世界第一。", "explanation": "这里应该用〈全国第一〉。“世界第一”的范围是全世界，用在全国的排名中前后矛盾，应说“全国第一”。"}, {"text": "我的生日世界第一。", "explanation": "这里应该用〈最特别〉。“世界第一”用于可以比较排名的数据，生日不能排名，只能说“最特别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座新大桥的跨度是很世界第一。", "corrected_sentence": "这座新大桥的跨度是世界第一。", "error_description": "多加了“很”：“世界第一”本身已经表示排名全世界首位，前面不能再加程度副词“很”。正确为「这座新大桥的跨度是世界第一。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们公司去年的销量已经世界第一着。", "corrected_sentence": "他们公司去年的销量已经世界第一了。", "error_description": "错误形式：“世界第一着”；正确形式：“世界第一了”。“着”表示持续的状态，这里说的是已经达到的变化，应用表示完成变化的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "正确：“减小”与“增大”互为反义，表示变小，与“难度加大”相对。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”表示维持原样，与“增大”不构成反义关系。"}, {"text": "移动", "is_correct": false, "explanation": "“移动”指位置变化，与表示程度变大的“增大”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指看和察看，与“增大”无反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "正确：“减小”与“增大”互为反义，表示变小，与“难度加大”相对。", "保持": "“保持”表示维持原样，与“增大”不构成反义关系。", "移动": "“移动”指位置变化，与表示程度变大的“增大”没有反义关系。", "观察": "“观察”指看和察看，与“增大”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
