INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增大；扩大。", "primary_collocate": null, "pronunciation": "jiā dà", "ipa": "tɕja˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "请把电视的声音加大一点。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小，要加大一号。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上的危险加大了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的难度今年加大了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穷人和富人的差距在加大。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想把店面加大一些。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风加大了，我们回家吧。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机加大油门，车开得更快了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的面积加大了一倍。", "target_word": "加大", "complexity_tier": "T3", "furigana": "jiā dà", "sentence_source": "generated"}, {"text": "工作压力加大了，他睡得不好。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加大了", "label": "完成体"}, {"form": "加大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "尺寸、程度、声音、难度等变大或被扩大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“请把电视的声音加大一点”，表示声音变大，与句意相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“声音”不能被“擦”，两者不搭配。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“声音”不能被“穿”，两者不搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“声音”不能被“吃”，句子语义不通。"}], "explanations": {"加大": "正确：“请把电视的声音加大一点”，表示声音变大，与句意相符。", "擦": "搭配：“声音”不能被“擦”，两者不搭配。", "穿": "搭配：“声音”不能被“穿”，两者不搭配。", "吃": "语义：“声音”不能被“吃”，句子语义不通。"}, "sentence_index": 0, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的英语水平加大了。", "explanation": "这里应该用〈提升〉。能力、水平的提高要说“提升”，“加大”表示尺寸、程度的变大，不说水平加大。"}, {"text": "这座楼的高度加大了。", "explanation": "这里应该用〈加高〉。建筑的增高说“加高”，“加大”指扩大尺寸或范围，不用于高度的增加。"}, {"text": "这株树加大了。", "explanation": "这里应该用〈长高〉。树木的生长要说“长高”或“长大”，“加大”不用于树木长高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“风加大了，我们回家吧”，表示风力变大，与句意相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“风”不能“写”，句子语义不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“风”不能被“洗”，两者不搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“风”不能“咬”，句子语义不通。"}], "explanations": {"加大": "正确：“风加大了，我们回家吧”，表示风力变大，与句意相符。", "写": "语义：“风”不能“写”，句子语义不通。", "洗": "搭配：“风”不能被“洗”，两者不搭配。", "咬": "语义：“风”不能“咬”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体质加大了。", "explanation": "这里应该用〈增强〉。体质、抵抗力的提升用“增强”，“加大”表示尺寸、程度的变大，不说体质加大。"}, {"text": "这件衣服洗过以后，颜色加大了。", "explanation": "这里应该用〈加深〉。颜色变深要说“加深”，“加大”用于尺寸、程度、声音、难度等的扩大，不用于颜色。"}, {"text": "他的成绩加大了。", "explanation": "这里应该用〈提高〉。成绩的提升要说“提高”，“加大”不用于成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年这条路的宽度将加大了一倍。", "corrected_sentence": "明年这条路的宽度将加大一倍。", "error_description": "错误形式：“将加大了一倍”；正确形式：“将加大一倍”。“将”表示将来，动作尚未发生，不能与表示完成的“了”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午风势加大很厉害。", "corrected_sentence": "下午风势加大得很厉害。", "error_description": "错误形式：“加大很厉害”；正确形式：“加大得很厉害”。表示程度的补语要用“得”接在动词之后，漏掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”指社会向前发展，与“反动”阻碍社会前进的意思相反。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容好看，与“反动”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或人开朗，与“反动”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事情繁多、不简单，与“反动”没有反义关系。"}], "correct_answer": "进步", "explanations": {"进步": "正确。“进步”指社会向前发展，与“反动”阻碍社会前进的意思相反。", "美丽": "“美丽”形容好看，与“反动”没有反义关系。", "明亮": "“明亮”形容光线充足或人开朗，与“反动”没有反义关系。", "复杂": "“复杂”形容事情繁多、不简单，与“反动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”指社会向前发展，与“反动”阻碍社会进步的意思相反。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容气温或感情，与“反动”没有反义关系。"}, {"text": "轻巧", "is_correct": false, "explanation": "“轻巧”形容分量轻、灵便，与“反动”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧哗、人多，与“反动”没有反义关系。"}], "correct_answer": "进步", "explanations": {"进步": "正确。“进步”指社会向前发展，与“反动”阻碍社会进步的意思相反。", "温暖": "“温暖”形容气温或感情，与“反动”没有反义关系。", "轻巧": "“轻巧”形容分量轻、灵便，与“反动”没有反义关系。", "热闹": "“热闹”形容场面喧哗、人多，与“反动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不让社会向前走，往后拖的。", "primary_collocate": null, "pronunciation": "fǎn dòng", "ipa": "fan˨˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种做法很反动，会让社会变得落后。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个反动的政府不让人民过好日子。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的政策太反动，只想把国家往后拖。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，反动的人总是挡着社会前进。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些反动的规定让大家没法往前走。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反动的力量阻挡不了时代前进。", "target_word": "反动", "complexity_tier": "T3", "furigana": "fǎn dòng", "sentence_source": "generated"}, {"text": "他写的文章很反动，想让社会回到过去。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些反动的人不愿看到社会进步。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个时代，反动的统治者拖住了国家的发展。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划让社会倒退，真是太反动了。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反动派", "label": "复合"}, {"form": "反动分子", "label": "复合"}, {"form": "反動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "阻碍社会前进、把社会往后拖的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“很反动”形容做法阻碍社会进步，与后半句“让社会变得落后”一致。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容态度主动亲切，与“让社会变得落后”的后果相矛盾，句意不通。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”指好看，与“让社会变得落后”的意思相反。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来修饰“做法”。"}], "explanations": {"反动": "正确。“很反动”形容做法阻碍社会进步，与后半句“让社会变得落后”一致。", "热情": "语义：“热情”形容态度主动亲切，与“让社会变得落后”的后果相矛盾，句意不通。", "美丽": "语义：“美丽”指好看，与“让社会变得落后”的意思相反。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来修饰“做法”。"}, "sentence_index": 0, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很反动，从来不冒险。", "explanation": "这里应该用〈保守〉。反动指阻碍社会前进的，只是做事谨慎，应该说〈保守〉。"}, {"text": "这个地区的交通很反动，需要修路。", "explanation": "这里应该用〈落后〉。反动说的是阻碍社会前进的人或事，交通条件差应说〈落后〉。"}, {"text": "这盏灯很反动，夜里特别亮。", "explanation": "这里应该用〈明亮〉。反动指阻碍社会进步的人或事，灯亮应说〈明亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“想让社会回到过去”说明文章是阻碍社会进步的，只有“反动”符合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或形象，不能用来形容“文章”，句意荒谬。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度低，不能用来形容“文章”，句意荒谬。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容“文章”，句意荒谬。"}], "explanations": {"反动": "正确。“想让社会回到过去”说明文章是阻碍社会进步的，只有“反动”符合。", "高大": "搭配：“高大”形容体型或形象，不能用来形容“文章”，句意荒谬。", "冰凉": "语义：“冰凉”形容温度低，不能用来形容“文章”，句意荒谬。", "咸": "语义：“咸”形容味道，不能用来形容“文章”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的秩序很反动，需要整顿。", "explanation": "这里应该用〈混乱〉。反动说的是阻碍社会进步的人或事，秩序乱应说〈混乱〉。"}, {"text": "这些设备很反动，该换新的了。", "explanation": "这里应该用〈陈旧〉。反动指阻碍社会前进的，设备旧应说〈陈旧〉。"}, {"text": "这个孩子很反动，喜欢捣乱。", "explanation": "这里应该用〈顽皮〉。反动用于阻碍社会进步的人或事，孩子爱玩闹应说〈顽皮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个政府是反动，阻碍了国家的发展。", "corrected_sentence": "那个政府是反动的，阻碍了国家的发展。", "error_description": "错误：“是反动”。正确：“是反动的”。“反动”是形容词，作谓语时后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个做法真是太反动着。", "corrected_sentence": "这个做法真是太反动了。", "error_description": "错误：“太反动着”。正确：“太反动了”。“着”表示持续的状态，这里说的是已经形成的判断，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”指思想或社会向前发展，与“反动”反对进步的意思相反。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容好看，与“反动”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或人开朗，与“反动”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容态度亲切、积极，与“反动”没有反义关系。"}], "correct_answer": "进步", "explanations": {"进步": "正确。“进步”指思想或社会向前发展，与“反动”反对进步的意思相反。", "美丽": "“美丽”形容好看，与“反动”没有反义关系。", "明亮": "“明亮”形容光线充足或人开朗，与“反动”没有反义关系。", "热情": "“热情”形容态度亲切、积极，与“反动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进步", "is_correct": true, "explanation": "正确。“进步”指社会向前发展，与“反动”反对进步的意思相反。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容气温或感情，与“反动”没有反义关系。"}, {"text": "轻巧", "is_correct": false, "explanation": "“轻巧”形容分量轻、灵便，与“反动”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事情繁多、不简单，与“反动”没有反义关系。"}], "correct_answer": "进步", "explanations": {"进步": "正确。“进步”指社会向前发展，与“反动”反对进步的意思相反。", "温暖": "“温暖”形容气温或感情，与“反动”没有反义关系。", "轻巧": "“轻巧”形容分量轻、灵便，与“反动”没有反义关系。", "复杂": "“复杂”形容事情繁多、不简单，与“反动”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "思想、行为上维护落后、反对进步的。", "primary_collocate": null, "pronunciation": "fǎn dòng", "ipa": "fan˨˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的思想很反动，反对一切新东西。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反动的观点只想维护落后的旧习惯。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的行为很反动，总是反对改革。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的想法太反动，不让工人学新技术。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话很反动，大家都不同意。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反对女孩上学，这种思想非常反动。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在会上，他提出了一个反动的看法。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对新办法，只想守着旧规矩，这很反动。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的做法很反动，总是压着新想法。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容反动，因为它反对一切进步。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反动派", "label": "复合"}, {"form": "反动分子", "label": "复合"}, {"form": "反動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "思想行为上守旧落后、反对进步的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“思想很反动”指思想守旧、反对进步，与“反对一切新东西”一致。"}, {"text": "先进", "is_correct": false, "explanation": "语义：“先进”指思想超前，与“反对一切新东西”的意思矛盾。"}, {"text": "灵活", "is_correct": false, "explanation": "语义：“灵活”指善于变通，与“反对一切新东西”的意思矛盾。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容好看，与“反对一切新东西”的守旧态度矛盾。"}], "explanations": {"反动": "正确。“思想很反动”指思想守旧、反对进步，与“反对一切新东西”一致。", "先进": "语义：“先进”指思想超前，与“反对一切新东西”的意思矛盾。", "灵活": "语义：“灵活”指善于变通，与“反对一切新东西”的意思矛盾。", "美丽": "语义：“美丽”形容好看，与“反对一切新东西”的守旧态度矛盾。"}, "sentence_index": 0, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很反动，每天都按时上班。", "explanation": "这里应该用〈认真〉。反动指思想行为维护落后、反对进步，按时上班应说〈认真〉。"}, {"text": "他对同事很反动，从不关心别人。", "explanation": "这里应该用〈冷漠〉。反动指维护落后、反对进步，对同事漠不关心应说〈冷漠〉。"}, {"text": "他作风很反动，喜欢独断。", "explanation": "这里应该用〈专横〉。反动是对进步事物的态度，作风霸道应说〈专横〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“反动的看法”指守旧、反对进步的观点，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体含水多，不能用来修饰“看法”，句意荒谬。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或形象，不能用来修饰“看法”。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容人的品性，与“看法”的内容无关，句意不通。"}], "explanations": {"反动": "正确。“反动的看法”指守旧、反对进步的观点，符合句意。", "潮湿": "搭配：“潮湿”形容空气或物体含水多，不能用来修饰“看法”，句意荒谬。", "高大": "搭配：“高大”形容体型或形象，不能用来修饰“看法”。", "善良": "语义：“善良”形容人的品性，与“看法”的内容无关，句意不通。"}, "sentence_index": 6, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格很反动，从不认输。", "explanation": "这里应该用〈倔强〉。反动说的是思想上反对进步，性格硬、不服输应说〈倔强〉。"}, {"text": "他说话的语气很反动，动不动就发火。", "explanation": "这里应该用〈暴躁〉。反动说的是思想、行为维护落后，说话语气急躁应说〈暴躁〉。"}, {"text": "这种款式已经反动了，没人穿了。", "explanation": "这里应该用〈过时〉。反动指阻碍进步的思想或行为，款式旧了应说〈过时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的想法变很反动，总是拒绝新事物。", "corrected_sentence": "他的想法变得很反动，总是拒绝新事物。", "error_description": "错误：“变很反动”。正确：“变得很反动”。“变”后面接形容词作补语时，中间要加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个观点让他变反动着，真可惜。", "corrected_sentence": "这个观点让他变反动了，真可惜。", "error_description": "错误：“变反动着”。正确：“变反动了”。“着”表示持续的状态，这里说的是已经发生的变化，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
