INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物质中所含某成分的量。", "primary_collocate": null, "pronunciation": "hán liàng", "ipa": "xan˧˥ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "空气中二氧化碳的含量在增加。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结果显示，土壤中铁的含量很低。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水中盐的含量约为百分之三点五。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种矿石中金的含量很高。", "target_word": "含量", "complexity_tier": "T3", "furigana": "zhè zhǒng kuàng shí zhōng jīn de hán liàng hěn gāo.", "sentence_source": "generated"}, {"text": "老师让我们测量溶液中酒精的含量。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查发现，他血液中的铁含量不够。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上空气中的氧气含量比城市低。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出的水里，铅含量超过了标准。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用仪器检测牛奶中蛋白质的含量。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着高度增加，空气中氧气的含量会减少。", "target_word": "含量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "科学检测中物质所含成分的量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含量", "is_correct": true, "explanation": "正确：“含量”指成分的量，“二氧化碳的含量在增加”说得通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的外形，二氧化碳没有身材，“身材在增加”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：二氧化碳没有年龄，“年龄在增加”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：二氧化碳没有名字，“名字在增加”说不通。"}], "explanations": {"含量": "正确：“含量”指成分的量，“二氧化碳的含量在增加”说得通。", "身材": "体貌：“身材”指人的外形，二氧化碳没有身材，“身材在增加”说不通。", "年龄": "语义：二氧化碳没有年龄，“年龄在增加”说不通。", "名字": "语义：二氧化碳没有名字，“名字在增加”说不通。"}, "sentence_index": 0, "correct_answer": "含量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种矿石的主要含量是石英。", "explanation": "这里应该用〈成分〉。含量是某种成分的量，矿石的组成成分要说“成分”，不能说“含量”。"}, {"text": "这块矿石的含量有两公斤。", "explanation": "这里应该用〈重量〉。含量指某种成分的量，整块矿石的重量要说“重量”。"}, {"text": "这次实验的成功含量很高。", "explanation": "这里应该用〈比率〉。含量指成分的多少，成功的比率高低要说“比率”，不能说“成功含量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含量", "is_correct": true, "explanation": "正确：“含量”指氧气的量，“氧气含量比城市低”说得通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人身体的高矮，氧气没有身高，“氧气身高比城市低”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：氧气没有脾气，“氧气脾气比城市低”说不通。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：“颜值”是网络口语，与科普语境不合，而且氧气不能说有颜值。"}], "explanations": {"含量": "正确：“含量”指氧气的量，“氧气含量比城市低”说得通。", "身高": "体貌：“身高”指人身体的高矮，氧气没有身高，“氧气身高比城市低”说不通。", "脾气": "语义：氧气没有脾气，“氧气脾气比城市低”说不通。", "颜值": "语域：“颜值”是网络口语，与科普语境不合，而且氧气不能说有颜值。"}, "sentence_index": 6, "correct_answer": "含量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "随着高度增加，高山上的游客含量会减少。", "explanation": "这里应该用〈数量〉。含量只用于物质中的成分，游客的多少要说“数量”。"}, {"text": "这个班的女生含量逐年上升。", "explanation": "这里应该用〈比例〉。含量指某种成分在物质中的量，班级中女生的占比要说“比例”。"}, {"text": "工业在经济中的含量越来越大。", "explanation": "这里应该用〈比重〉。含量指成分的多少，行业在经济中所占的份额要说“比重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种土壤中钙的含量高很。", "corrected_sentence": "这种土壤中钙的含量很高。", "error_description": "形容词谓语前的副词“很”应放在前面，说“很高”，不能说“高很”；错误出在“含量”之后的谓语上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告显示，海水中盐的含量很较高。", "corrected_sentence": "这份报告显示，海水中盐的含量较高。", "error_description": "程度副词叠用：“较”与“很”不能同时修饰“高”，应只用“较”，说“含量较高”。错误出在“较高”前多加的“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
