INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爷爷奶奶把爸爸的男孩叫作孙子。", "primary_collocate": null, "pronunciation": "sūn zi", "ipa": "sun˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "奶奶笑着说：“我的孙子最聪明！”", "target_word": "孙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷抱着刚出生的孙子，高兴极了。", "target_word": "孙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是爷爷的孙子，我姓王。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷奶奶最疼爱他们的孙子。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个男孩是爷爷的孙子。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷说，孙子长得像他爸爸。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶做了孙子最爱吃的红烧肉。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年时，爷爷给孙子一个红包。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是我们家第一个孙子。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末，爷爷带孙子去钓鱼。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "孙子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "从爷爷奶奶角度称呼儿子的男孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：sūn zi 指爷爷奶奶称呼儿子的男孩，即孙子。"}, {"text": "松子", "is_correct": false, "explanation": "sōng 与 sūn 韵尾不同（ng 与 n），意思是松子，即松树的种子。"}, {"text": "村子", "is_correct": false, "explanation": "cūn 与 sūn 声母不同（c 与 s），意思是村庄。"}, {"text": "轮子", "is_correct": false, "explanation": "lún 与 sūn 声母不同（l 与 s）且声调不同，意思是车轮。"}, {"text": "笋子", "is_correct": false, "explanation": "sǔn 与 sūn 声调不同（第三声），意思是竹笋，口语中较少用。"}], "explanations": {"孙子": "正确：sūn zi 指爷爷奶奶称呼儿子的男孩，即孙子。", "松子": "sōng 与 sūn 韵尾不同（ng 与 n），意思是松子，即松树的种子。", "村子": "cūn 与 sūn 声母不同（c 与 s），意思是村庄。", "轮子": "lún 与 sūn 声母不同（l 与 s）且声调不同，意思是车轮。", "笋子": "sǔn 与 sūn 声调不同（第三声），意思是竹笋，口语中较少用。"}, "sentence_index": null, "correct_answer": "孙子"}, "level_3": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：“我的孙子”指奶奶的孙子，符合“最聪明”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会“聪明”，“我的桌子最聪明”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“聪明”不修饰“脾气”，不能说“脾气最聪明”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，与“聪明”无关，句子说不通。"}], "explanations": {"孙子": "正确：“我的孙子”指奶奶的孙子，符合“最聪明”的语境。", "桌子": "语义：桌子不会“聪明”，“我的桌子最聪明”说不通。", "脾气": "搭配：“聪明”不修饰“脾气”，不能说“脾气最聪明”。", "身材": "体貌：“身材”指外形，与“聪明”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "孙子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我女儿的儿子，正是我的孙子。", "explanation": "这里应该用〈外孙〉。女儿的儿子是外孙，孙子指儿子的儿子。"}, {"text": "我姐姐的儿子，是我的孙子。", "explanation": "这里应该用〈外甥〉。姐姐的儿子是外甥，孙子指儿子的儿子。"}, {"text": "奶奶的孙子，就是奶奶的儿子。", "explanation": "这里应该用〈儿子〉。奶奶的儿子是爸爸，孙子是爸爸的儿子，两者不能等同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：“孙子最爱吃的红烧肉”符合语境，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会吃东西，“奶奶做了房子最爱吃的红烧肉”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，与吃饭无关，句子说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不会吃东西，“名字最爱吃的红烧肉”说不通。"}], "explanations": {"孙子": "正确：“孙子最爱吃的红烧肉”符合语境，句意通顺。", "房子": "语义：房子不会吃东西，“奶奶做了房子最爱吃的红烧肉”说不通。", "身高": "体貌：“身高”指身体的高矮，与吃饭无关，句子说不通。", "名字": "语义：名字不会吃东西，“名字最爱吃的红烧肉”说不通。"}, "sentence_index": 6, "correct_answer": "孙子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的孙子就是我的重孙。", "explanation": "这里应该用〈重孙〉。孙子是儿子的儿子，重孙是孙子的儿子，两者不是同一代，孙子不能等同重孙。"}, {"text": "我哥哥的儿子是我的孙子，他很会钓鱼。", "explanation": "这里应该用〈侄子〉。哥哥的儿子对我来说是侄子，孙子指儿子的儿子。"}, {"text": "我的孙子今年五岁，是个漂亮的女孩。", "explanation": "这里应该用〈孙女〉。孙子指男孩，与“女孩”的语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有两个孙子们。", "corrected_sentence": "我家有两个孙子。", "error_description": "“孙子们”是复数形式，前面有“两个”这样的数词时不再加“们”，应说“两个孙子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷家又添了一只孙子。", "corrected_sentence": "爷爷家又添了一个孙子。", "error_description": "“孙子”指人，量词应用“个”，用动物量词“只”是错误的，应说“一个孙子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
