INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "儿子的儿子。", "primary_collocate": null, "pronunciation": "sūn zi", "ipa": "sun˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "我爷爷有三个孙子。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的孙子今年五岁了。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每天都接孙子放学。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老王的孙子在北京工作。", "target_word": "孙子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷给孙子买了一个新书包。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的儿子生了个男孩，这个男孩就是他的孙子。", "target_word": "孙子", "complexity_tier": "T3", "furigana": "tā de ér zi shēng le ge nán hái, zhè ge nán hái jiù shì tā de sūn zi.", "sentence_source": "generated"}, {"text": "她有两个孙子，还有一个孙女。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人常常带着孙子去公园。", "target_word": "孙子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙子喜欢听爷爷讲故事。", "target_word": "孙子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李的儿子结婚了，他很快就有孙子了。", "target_word": "孙子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孙子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "儿子的儿子，亲属称谓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95682, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：sūn zi 指儿子的儿子，即孙子。"}, {"text": "松子", "is_correct": false, "explanation": "sōng 与 sūn 韵尾不同（ng 与 n），意思是松子，即松树的种子。"}, {"text": "村子", "is_correct": false, "explanation": "cūn 与 sūn 声母不同（c 与 s），意思是村庄。"}, {"text": "轮子", "is_correct": false, "explanation": "lún 与 sūn 声母不同（l 与 s）且声调不同，意思是车轮。"}, {"text": "笋子", "is_correct": false, "explanation": "sǔn 与 sūn 声调不同（第三声），意思是竹笋，口语中较少用。"}], "explanations": {"孙子": "正确：sūn zi 指儿子的儿子，即孙子。", "松子": "sōng 与 sūn 韵尾不同（ng 与 n），意思是松子，即松树的种子。", "村子": "cūn 与 sūn 声母不同（c 与 s），意思是村庄。", "轮子": "lún 与 sūn 声母不同（l 与 s）且声调不同，意思是车轮。", "笋子": "sǔn 与 sūn 声调不同（第三声），意思是竹笋，口语中较少用。"}, "sentence_index": null, "correct_answer": "孙子"}, "level_3": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：孙子指儿子的儿子，爷爷的孙子可以有三个。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“猫”用“只”计量，不说“三个猫”。"}, {"text": "爸爸", "is_correct": false, "explanation": "语义：爷爷不可能有三个爸爸，与家庭关系矛盾。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：爷爷不可能有三个妈妈，与家庭关系矛盾。"}], "explanations": {"孙子": "正确：孙子指儿子的儿子，爷爷的孙子可以有三个。", "猫": "搭配：“猫”用“只”计量，不说“三个猫”。", "爸爸": "语义：爷爷不可能有三个爸爸，与家庭关系矛盾。", "妈妈": "语义：爷爷不可能有三个妈妈，与家庭关系矛盾。"}, "sentence_index": 0, "correct_answer": "孙子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我女儿的儿子，就是我的孙子。", "explanation": "这里应该用〈外孙〉。孙子指儿子的儿子，女儿的儿子要说“外孙”。"}, {"text": "我哥哥的儿子，是我的孙子。", "explanation": "这里应该用〈侄子〉。哥哥的儿子对我来说是侄子，孙子指儿子的儿子。"}, {"text": "我父亲的孙子是我哥哥。", "explanation": "这里应该用〈儿子〉。哥哥是父亲的儿子，孙子指儿子的儿子，不能用来指父亲自己的子女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孙子", "is_correct": true, "explanation": "正确：“她有两个孙子”与后文“还有一个孙女”相对应，句意通顺。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“狗”用“只”计量，不说“两个狗”。"}, {"text": "爸爸", "is_correct": false, "explanation": "语义：一个人不会有两个爸爸，“她有两个爸爸”说不通。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：她不能有两个爷爷，与后文“孙女”的家庭称谓矛盾。"}], "explanations": {"孙子": "正确：“她有两个孙子”与后文“还有一个孙女”相对应，句意通顺。", "狗": "搭配：“狗”用“只”计量，不说“两个狗”。", "爸爸": "语义：一个人不会有两个爸爸，“她有两个爸爸”说不通。", "爷爷": "语义：她不能有两个爷爷，与后文“孙女”的家庭称谓矛盾。"}, "sentence_index": 6, "correct_answer": "孙子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我舅舅的儿子，是我的孙子。", "explanation": "这里应该用〈表兄弟〉。舅舅的儿子与我是表亲关系，应说“表兄弟”；孙子指儿子的儿子，不能用来指表亲。"}, {"text": "我姐姐的儿子，是我的孙子。", "explanation": "这里应该用〈外甥〉。姐姐的儿子是外甥，孙子指儿子的儿子。"}, {"text": "我的孙子今年五岁，是个漂亮的女孩。", "explanation": "这里应该用〈孙女〉。孙子指男孩，与“女孩”的语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有三个孙子们。", "corrected_sentence": "我有三个孙子。", "error_description": "“孙子们”是复数形式，前面有“三个”这样的数词时不再加“们”，应说“三个孙子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末，奶奶带三只孙子去公园。", "corrected_sentence": "周末，奶奶带三个孙子去公园。", "error_description": "量词错误：“孙子”指人，应用人的量词“个”，说“三个孙子”，不能用动物量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
