INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "比较两件事，觉得这一件更好，宁可选它。", "primary_collocate": null, "pronunciation": "nìng yuàn", "ipa": "niŋ˥˩ yɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我宁愿走路，也不坐那么挤的车。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁愿在家看书，也不想出去玩。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈宁愿自己累一点，也不让孩子难过。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿喝白水，也不喝这种甜饮料。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟宁愿吃面条，也不吃米饭。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她宁愿一个人住，也不和别人一起住。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿早点起床，也不想迟到。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王宁愿坐火车，也不坐飞机。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿看电影，也不去逛商店。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明宁愿晚点睡，也不想把作业留到明天。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "宁愿：比较两件事后选择更好的一件，常用“宁愿A，也不B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宁愿", "is_correct": true, "explanation": "正确：“宁愿”表示经过比较后情愿选前者，与后面的“也不坐那么挤的车”相呼应。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示所幸避免了不利结果，句中并没有这样的前提，说不通。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“也不坐那么挤的车”这种有意的选择相矛盾。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面承认用语，与口语化的叙述不搭，且后面通常要接转折。"}], "explanations": {"宁愿": "正确：“宁愿”表示经过比较后情愿选前者，与后面的“也不坐那么挤的车”相呼应。", "幸亏": "语义：“幸亏”表示所幸避免了不利结果，句中并没有这样的前提，说不通。", "恰好": "语义：“恰好”表示碰巧，与“也不坐那么挤的车”这种有意的选择相矛盾。", "诚然": "语域：“诚然”是书面承认用语，与口语化的叙述不搭，且后面通常要接转折。"}, "sentence_index": 0, "correct_answer": "宁愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他宁愿生病，今天还是来上班了。", "explanation": "这里应该用〈虽然〉。这句是让步关系（“还是来上班”），而〈宁愿〉表示比较两种做法后情愿选其一，与让步的意思不符。"}, {"text": "你宁愿快点走，不然赶不上车。", "explanation": "这里应该用〈最好〉。〈宁愿〉表示情愿选某种做法，不用于提醒或劝告别人。"}, {"text": "他宁愿吃饭，也不吃饭。", "explanation": "这里应该用〈干脆〉，并去掉“也不吃饭”。两个分句说的是同一件事，没有可以比较的两个选择，〈宁愿〉不能这样用；〈干脆〉表示直接做某事，改为“他干脆吃饭。”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，句中没有前面的预测，说不通。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或劝阻，如“千万别迟到”，不直接修饰“早点起床”这样的陈述。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，句中没有可以相对的预期，说不通。"}, {"text": "宁愿", "is_correct": true, "explanation": "正确：“宁愿”表示情愿选早起，与后面的“也不想迟到”相呼应。"}], "explanations": {"果然": "语义：“果然”表示与预料相符，句中没有前面的预测，说不通。", "千万": "搭配：“千万”多用于叮嘱或劝阻，如“千万别迟到”，不直接修饰“早点起床”这样的陈述。", "反而": "语义：“反而”表示与预期相反，句中没有可以相对的预期，说不通。", "宁愿": "正确：“宁愿”表示情愿选早起，与后面的“也不想迟到”相呼应。"}, "sentence_index": 6, "correct_answer": "宁愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只要你同意，我宁愿去。", "explanation": "这里应该用〈就〉。“只要……就……”是条件关系；〈宁愿〉要比较两种选择，句中只有“去”，没有可比较的另一项，与条件句不搭。"}, {"text": "他宁愿，今天就回家了。", "explanation": "这里应该用〈只好〉。〈宁愿〉需要比较两项，句中只有一项；表示不得已而回家，应用〈只好〉。"}, {"text": "他没有帮忙，宁愿添了乱。", "explanation": "这里应该用〈反而〉。〈宁愿〉表示有意选择，而“没有帮忙却添乱”是与预期相反的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我宁愿晚点回家，也想挤地铁。", "corrected_sentence": "我宁愿晚点回家，也不想挤地铁。", "error_description": "“宁愿……”后面要用“也不……”与之呼应，表示比较后的取舍；这里漏掉了“不”，说成“也想挤地铁”，与“宁愿”的意思矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我宁愿吃冷饭，所以不想现在去买菜。", "corrected_sentence": "我宁愿吃冷饭，也不想现在去买菜。", "error_description": "“宁愿……”后面要用“也不……”与之呼应，表示比较后的取舍；“所以”表示因果，与比较选择不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只差一点就发生了，但是没有发生。", "primary_collocate": null, "pronunciation": "chà diǎn", "ipa": "ʈʂʰa˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "车来得太快，他差点就撞到了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我差点就赶上最后一班车。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子差点掉到地上。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她差点说出了那个秘密。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他差点就把电脑摔了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗差点跑到马路上去。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他差点就当上了经理。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后，我们差点赢了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我差点睡过头。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门一开，猫差点跑出去了。", "target_word": "差点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差点儿", "label": "儿化"}, {"form": "差點", "label": "繁体"}], "register": "口语", "sense_fingerprint": "只差一点就发生，但事情没有发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55addd89-518c-40da-814b-2ea91ff12618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "差点", "is_correct": true, "explanation": "正确。差点（chà diǎn）表示只差一点就发生了但没有发生，就是本题要的词。"}, {"text": "茶点", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，茶点指点心，与“差一点就发生”无关。"}, {"text": "查点", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，查点指核对、清点数目，意思不同。"}, {"text": "插电", "is_correct": false, "explanation": "chā（第一声）与 chà（第四声）声调不同，diàn（第四声）与 diǎn（第三声）也不同，插电指接通电源。"}, {"text": "茶店", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）、diàn（第四声）与 diǎn（第三声）声调都不同，茶店指卖茶的小店。"}], "explanations": {"差点": "正确。差点（chà diǎn）表示只差一点就发生了但没有发生，就是本题要的词。", "茶点": "chá（第二声）与 chà（第四声）声调不同，茶点指点心，与“差一点就发生”无关。", "查点": "chá（第二声）与 chà（第四声）声调不同，查点指核对、清点数目，意思不同。", "插电": "chā（第一声）与 chà（第四声）声调不同，diàn（第四声）与 diǎn（第三声）也不同，插电指接通电源。", "茶店": "chá（第二声）与 chà（第四声）、diàn（第四声）与 diǎn（第三声）声调都不同，茶店指卖茶的小店。"}, "sentence_index": null, "correct_answer": "差点"}, "level_3": {"options": [{"text": "差点", "is_correct": true, "explanation": "正确。差点表示车险些撞上但实际没有撞上；“差点就撞到了”是常见的固定说法。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与已经发生的“撞到了”矛盾。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”表示将要发生，与已经发生的“撞到了”冲突。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理状态，不能直接修饰“撞到”这类动作。"}], "explanations": {"差点": "正确。差点表示车险些撞上但实际没有撞上；“差点就撞到了”是常见的固定说法。", "正在": "体貌：“正在”表示动作正在进行，与已经发生的“撞到了”矛盾。", "将": "体貌：“将”表示将要发生，与已经发生的“撞到了”冲突。", "很": "搭配：“很”修饰形容词或心理状态，不能直接修饰“撞到”这类动作。"}, "sentence_index": 0, "correct_answer": "差点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他差点把这张桌子搬走了，结果桌子真的被搬走了。", "explanation": "“差点”表示险些搬走却没有搬走，后面“真的被搬走了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "我差点说出了那件事，最后真的说出来了。", "explanation": "“差点”表示险些说出却没有说出，后面“真的说出来了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "他差点把窗户关上了，但窗户已经关上了。", "explanation": "“差点”表示险些关上却没有关上，后面“已经关上了”说明已经发生，前后矛盾；应改用〈早已〉表示已经发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差点", "is_correct": true, "explanation": "正确。差点表示只差一点就当上了经理但没有当上，符合语境。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或劝阻，不能用在已经发生的“当上经理”前面。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示确定会发生，与“差点就当上”所表达的未成功之意相反。"}, {"text": "依然", "is_correct": false, "explanation": "语义：“依然”表示状态延续，与“当上经理”这种一次性的变化不合。"}], "explanations": {"差点": "正确。差点表示只差一点就当上了经理但没有当上，符合语境。", "千万": "搭配：“千万”多用于叮嘱或劝阻，不能用在已经发生的“当上经理”前面。", "一定": "语义：“一定”表示确定会发生，与“差点就当上”所表达的未成功之意相反。", "依然": "语义：“依然”表示状态延续，与“当上经理”这种一次性的变化不合。"}, "sentence_index": 6, "correct_answer": "差点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们差点解散了这支队伍，结果队伍真的解散了。", "explanation": "“差点”表示险些解散却没有解散，后面“真的解散了”说明已经发生，两者矛盾；表示已经发生应改用〈终于〉。"}, {"text": "门一开，猫差点跑出去了，结果它真的跑出去了。", "explanation": "“差点”表示险些跑出去却没有跑，后面“真的跑出去了”说明已经发生，两者矛盾；表示已经发生应改用〈早已〉。"}, {"text": "我差点把成绩单交上去了，结果成绩单已经交上去了。", "explanation": "“差点”表示险些交上却没有交，后面“已经交上去了”说明已经发生，前后矛盾；应改用〈早已〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我差点了赶不上末班车。", "corrected_sentence": "我差点赶不上末班车。", "error_description": "错误形式是“差点了赶不上”，正确形式是“差点赶不上”。“差点”表示事情没有发生，后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她差点差点拿到那份工作，最后却落选了。", "corrected_sentence": "她差点拿到那份工作，最后却落选了。", "error_description": "错误形式是“差点差点拿到”，正确形式是“差点拿到”。“差点”只能出现一次，重复使用不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5ac0ca0-d16b-45be-ac1e-5dbb03f8730c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
