INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把对手打到地上，让他起不来。", "primary_collocate": null, "pronunciation": "dǎ dǎo", "ipa": "ta˨˩˦ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他一拳把对手打倒了。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李打倒了比他高的男孩。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳手把对方打倒在地上。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没能打倒那个大个子。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想打倒我，可是我没有倒下。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟一下子就把哥哥打倒了。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛里，他两次把对手打倒。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人很能打，三个人都没打倒他。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个醉汉想闹事，被他一拳打倒了。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力一拳，就把那个坏人打倒了。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打倒了", "label": "完成体"}, {"form": "打倒过", "label": "经历体"}, {"form": "打不倒", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "打倒：用拳头、力气把人打到地上，使其倒下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”指把对手打到地上，使其倒下。"}, {"text": "打到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“使人倒下”。"}, {"text": "达到", "is_correct": false, "explanation": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。"}, {"text": "打好", "is_correct": false, "explanation": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}], "explanations": {"打倒": "正确：“打倒”指把对手打到地上，使其倒下。", "打到": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“使人倒下”。", "达到": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。", "大道": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。", "打好": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}, "sentence_index": null, "correct_answer": "打倒"}, "level_3": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”指用拳击使人倒地，与“一拳”的动作相呼应。"}, {"text": "打开", "is_correct": false, "explanation": "语义：“打开”表示使闭合的东西张开，用在对手身上说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象多是器物或“希望”“计划”，不说“打碎对手”。"}, {"text": "打湿", "is_correct": false, "explanation": "语义：“打湿”表示使物体沾水，与“一拳”的击打动作无关，说不通。"}], "explanations": {"打倒": "正确：“打倒”指用拳击使人倒地，与“一拳”的动作相呼应。", "打开": "语义：“打开”表示使闭合的东西张开，用在对手身上说不通。", "打碎": "搭配：“打碎”的对象多是器物或“希望”“计划”，不说“打碎对手”。", "打湿": "语义：“打湿”表示使物体沾水，与“一拳”的击打动作无关，说不通。"}, "sentence_index": 0, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一拳把那杯水打倒了。", "explanation": "这里应该用〈打翻〉。〈打倒〉的宾语是人或能倒下的东西，液体不会“倒下”，要说“打翻”。"}, {"text": "他一拳把玻璃打倒了。", "explanation": "这里应该用〈打碎〉。玻璃被击打后会碎裂，不会整体倒下，〈打倒〉的宾语多指人。"}, {"text": "他一拳把对手的鼻子打倒了。", "explanation": "这里应该用〈打伤〉。〈打倒〉的宾语是人，不说把身体的某个部位“打倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文字印在纸上，用于对手说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或房间，不用于人。"}, {"text": "打招呼", "is_correct": false, "explanation": "配价：“打招呼”是离合词，不能直接带“把对手”这样的宾语。"}, {"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”指把对手打到地上，与“两次把对手”的动作相符。"}], "explanations": {"打印": "语义：“打印”指把文字印在纸上，用于对手说不通。", "打扫": "搭配：“打扫”的对象是场地或房间，不用于人。", "打招呼": "配价：“打招呼”是离合词，不能直接带“把对手”这样的宾语。", "打倒": "正确：“打倒”指把对手打到地上，与“两次把对手”的动作相符。"}, "sentence_index": 6, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一脚把足球打倒了。", "explanation": "这里应该用〈踢中〉。〈打倒〉的宾语多是人或能倒下的东西，足球被踢只能说“踢中”或“踢飞”，不说“打倒”。"}, {"text": "他们终于打倒了关系。", "explanation": "这里应该用〈打通〉。关系可以打通，不能说打倒关系。"}, {"text": "他终于打倒了这个纪录。", "explanation": "这里应该用〈打破〉。纪录要用“打破”，不能说“打倒纪录”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一拳就把那个小伙子打倒地上。", "corrected_sentence": "他一拳就把那个小伙子打倒在地上。", "error_description": "「打倒」后面的处所要用「打倒在地上」，这里漏掉了「在」，说「打倒地上」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一拳就那个新人打倒了。", "corrected_sentence": "他一拳就把那个新人打倒了。", "error_description": "处置式要用“把”引出宾语，应说“把那个新人打倒了”；这里漏掉了“把”，直接说“那个新人打倒了”，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
