INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "击败；使倒下。", "primary_collocate": null, "pronunciation": "dǎ dǎo", "ipa": "ta˨˩˦ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们队终于打倒了最强的对手。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想打倒所有的对手，拿第一名。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，小王打倒了去年的冠军。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "困难没能打倒他，他还是笑着生活。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要打倒这个队，我们得多练习。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的队打倒过很多有名的队。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只用三局就打倒了对手。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小公司想打倒大公司，不太容易。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病不会打倒他的，他很有信心。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要打倒他，拿回我的第一名。", "target_word": "打倒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打倒了", "label": "完成体"}, {"form": "打倒过", "label": "经历体"}, {"form": "打不倒", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "打倒：在比赛、竞争或困境中击败对方，使其失败", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3d50c0-7076-42e3-ba24-63a14507b06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”在比赛或竞争中指击败对方。"}, {"text": "打到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“击败对方”。"}, {"text": "达到", "is_correct": false, "explanation": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。"}, {"text": "打好", "is_correct": false, "explanation": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}], "explanations": {"打倒": "正确：“打倒”在比赛或竞争中指击败对方。", "打到": "dào（第四声）与 dǎo（第三声）声调不同，意思是“打中、击到某处”，不是“击败对方”。", "达到": "dá（第二声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“达到某个标准或地点”。", "大道": "dà（第四声）与 dǎ（第三声）、dào（第四声）与 dǎo（第三声）声调都不同，意思是“宽阔的道路”。", "打好": "hǎo 与 dǎo 的声母不同（h 与 d），意思是“做得好、练好”。"}, "sentence_index": null, "correct_answer": "打倒"}, "level_3": {"options": [{"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”在这里指击败对方，与“终于”和“最强的对手”相呼应。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文字印在纸上，用于对手说不通。"}, {"text": "打湿", "is_correct": false, "explanation": "语义：“打湿”表示使物体沾水，与“最强的对手”不相干，说不通。"}, {"text": "打招呼", "is_correct": false, "explanation": "配价：“打招呼”是离合词，不能直接带“最强的对手”作宾语。"}], "explanations": {"打倒": "正确：“打倒”在这里指击败对方，与“终于”和“最强的对手”相呼应。", "打印": "语义：“打印”指把文字印在纸上，用于对手说不通。", "打湿": "语义：“打湿”表示使物体沾水，与“最强的对手”不相干，说不通。", "打招呼": "配价：“打招呼”是离合词，不能直接带“最强的对手”作宾语。"}, "sentence_index": 0, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自己不小心打倒了。", "explanation": "这里应该用〈摔倒〉。〈打倒〉需要有施事把别人击倒，不能用于自己跌倒。"}, {"text": "他想办法打倒了局面。", "explanation": "这里应该用〈打开〉。局面可以打开、打破，不能说打倒局面。"}, {"text": "他一拳打倒了对方的下巴。", "explanation": "这里应该用〈击中〉。〈打倒〉的宾语是人或困难，不能说打倒身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打开", "is_correct": false, "explanation": "语义：“打开”表示使闭合的东西张开，用于对手说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”多接“希望”“计划”“纪录”等，直接接“对手”不通。"}, {"text": "打盹", "is_correct": false, "explanation": "配价：“打盹”是不及物动词，不能带“对手”作宾语。"}, {"text": "打倒", "is_correct": true, "explanation": "正确：“打倒”在比赛中指击败对方，与“只用三局”的胜负结果相符。"}], "explanations": {"打开": "语义：“打开”表示使闭合的东西张开，用于对手说不通。", "打碎": "搭配：“打碎”多接“希望”“计划”“纪录”等，直接接“对手”不通。", "打盹": "配价：“打盹”是不及物动词，不能带“对手”作宾语。", "打倒": "正确：“打倒”在比赛中指击败对方，与“只用三局”的胜负结果相符。"}, "sentence_index": 6, "correct_answer": "打倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一拳把那只气球打倒了。", "explanation": "这里应该用〈打爆〉。气球被击打会爆裂，不会倒下；〈打倒〉的宾语应是人或困难。"}, {"text": "大家终于打倒了沉默。", "explanation": "这里应该用〈打破〉。沉默可以打破，不能说打倒沉默。"}, {"text": "他一侧身躲开了这一拳，然后打倒了这一拳。", "explanation": "这里应该用〈挡开〉。〈打倒〉的宾语是人或困难，不能指“一拳”这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点困难打不倒了他，他还是很乐观。", "corrected_sentence": "这点困难打不倒他，他还是很乐观。", "error_description": "可能补语「打不倒」已表示无法击倒，后面不能再加表示完成的「了」，说「打不倒了他」自相矛盾，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她只用三局就那位选手打倒了。", "corrected_sentence": "她只用三局就把那位选手打倒了。", "error_description": "“把”字句要用“把”引出宾语，应说“把那位选手打倒了”；这里漏掉了“把”，“那位选手”直接放在动词前，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da9a4a8f-2144-400a-ab0c-e78d3e6ac6ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
