INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有客人来了，招呼他、照顾他。", "primary_collocate": null, "pronunciation": "jiē dài", "ipa": "tɕje˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "周末有客人来，我在家接待他们。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈忙着做饭，爸爸来接待客人。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友第一次来我家，我热情地接待了他。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶很会接待客人，总是准备很多水果。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，你去接待一下，我马上就来。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天要在家接待几位老同学。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太会接待客人，有点儿紧张。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师来家访，妈妈热情接待了他。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐结婚那天，我们一家人一起接待亲戚。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们接待过很多远方来的朋友。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接待了", "label": "体标"}, {"form": "接待过", "label": "体标"}, {"form": "接待员", "label": "复合"}, {"form": "接待室", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：在家里招呼、照顾来访的客人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢送", "is_correct": false, "explanation": "语义：“欢送”是送别，与客人刚到、我在家招待的语境相反。"}, {"text": "接待", "is_correct": true, "explanation": "正确：“接待”指招呼、照顾来客，与句意相符。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”是到别人家去，与“我在家”的语境矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能说打扫他们。"}], "explanations": {"欢送": "语义：“欢送”是送别，与客人刚到、我在家招待的语境相反。", "接待": "正确：“接待”指招呼、照顾来客，与句意相符。", "拜访": "语义：“拜访”是到别人家去，与“我在家”的语境矛盾。", "打扫": "搭配：“打扫”的对象是场所或物品，不能说打扫他们。"}, "sentence_index": 0, "correct_answer": "接待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他接待了老师的批评，很不好意思。", "explanation": "这里应该用〈接受〉。接待指招待客人，批评要接受，不能说接待。"}, {"text": "妈妈接待了一锅热汤。", "explanation": "这里应该用〈端〉。接待只用于招待客人，热汤要端上来，不能接待。"}, {"text": "我们接待了家里的小猫。", "explanation": "这里应该用〈喂〉。接待的对象是来访的人，家里的小猫要喂，不能说接待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于人，不能说修理客人。"}, {"text": "扣押", "is_correct": false, "explanation": "语义：“扣押”是强行留住，与热情待客的语境相反。"}, {"text": "接待", "is_correct": true, "explanation": "正确：“接待”指招待来客，与“不太会”“紧张”的语境相符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”针对货物，不能说搬运客人。"}], "explanations": {"修理": "搭配：“修理”针对器物，不能用于人，不能说修理客人。", "扣押": "语义：“扣押”是强行留住，与热情待客的语境相反。", "接待": "正确：“接待”指招待来客，与“不太会”“紧张”的语境相符。", "搬运": "搭配：“搬运”针对货物，不能说搬运客人。"}, "sentence_index": 6, "correct_answer": "接待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士接待了一剂疫苗。", "explanation": "这里应该用〈接种〉。接待指招待客人，给人打疫苗要用接种。"}, {"text": "我们接待了这个突发情况。", "explanation": "这里应该用〈应对〉。接待指招待客人，处理突发情况要说应对。"}, {"text": "他接待了飞来的球。", "explanation": "这里应该用〈接住〉。接待指招待客人，接住飞来的球要用接住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把客人接待了好了。", "corrected_sentence": "我们把客人接待好了。", "error_description": "错误：“接待”和“好”之间多了“了”；正确：“接待好了”。结果补语“好”必须紧跟动词“接待”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不太会把接待客人，有点儿紧张。", "corrected_sentence": "我不太会接待客人，有点儿紧张。", "error_description": "错误：“接待”前多加了“把”，“把”字句不能这样用；正确：去掉“把”，说“我不太会接待客人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
