INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迎接并招待客人。", "primary_collocate": null, "pronunciation": "jiē dài", "ipa": "tɕje˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "公司明天要接待一位重要的客户。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店每天接待很多外国游客。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位小姐负责接待来参观的人。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校接待了二十个外国学生。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在前台工作，主要是接待客人。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在办公室接待了来访的朋友。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展会期间，我们接待了上千位客人。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的服务员接待客人很有礼貌。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在会议室接待客户。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司从没接待过这么大的团队。", "target_word": "接待", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接待了", "label": "体标"}, {"form": "接待过", "label": "体标"}, {"form": "接待员", "label": "复合"}, {"form": "接待处", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：单位、酒店等迎接并招待来访的客户", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辞退", "is_correct": false, "explanation": "搭配：“辞退”针对员工，不能用于客户。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”是赶走，与接待重要客户的语境相反。"}, {"text": "接待", "is_correct": true, "explanation": "正确：“接待”指迎接并招待来访的客户，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于人。"}], "explanations": {"辞退": "搭配：“辞退”针对员工，不能用于客户。", "驱逐": "语义：“驱逐”是赶走，与接待重要客户的语境相反。", "接待": "正确：“接待”指迎接并招待来访的客户，与句意相符。", "修理": "搭配：“修理”针对器物，不能用于人。"}, "sentence_index": 0, "correct_answer": "接待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校接待了我们的建议。", "explanation": "这里应该用〈接受〉。接待指招待来访的人，建议要接受，不能说接待。"}, {"text": "学校接待了一场大雨。", "explanation": "这里应该用〈遭遇〉。接待用于招待人，一场大雨要说遭遇。"}, {"text": "学校接待了一批新教科书。", "explanation": "这里应该用〈采购〉。接待的对象是来访的人，教科书要采购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "配价：“参观”的对象是场所，不能带“客人”作宾语。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品或场所，不能用于人。"}, {"text": "接待", "is_correct": true, "explanation": "正确：“接待”指招待来访的客人，与展会期间的语境相符。"}, {"text": "训练", "is_correct": false, "explanation": "语义：“训练”指培养技能，与展会接待的语境无关。"}], "explanations": {"参观": "配价：“参观”的对象是场所，不能带“客人”作宾语。", "装饰": "搭配：“装饰”用于物品或场所，不能用于人。", "接待": "正确：“接待”指招待来访的客人，与展会期间的语境相符。", "训练": "语义：“训练”指培养技能，与展会接待的语境无关。"}, "sentence_index": 6, "correct_answer": "接待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接待了公司的业务。", "explanation": "这里应该用〈接手〉。接待指招待来访的人，公司的业务要接手。"}, {"text": "我们接待了这个包裹。", "explanation": "这里应该用〈接收〉。接待的对象是来访的人，包裹要接收。"}, {"text": "经理接待了一场会议。", "explanation": "这里应该用〈主持〉。接待用于招待客人，会议要主持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司明天要接待过一位重要的客户。", "corrected_sentence": "公司明天要接待一位重要的客户。", "error_description": "错误：“接待”后多加了“过”，“过”表示已有的经历，与将来的“明天”矛盾；正确：去掉“过”，说“公司明天要接待一位重要的客户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司从没接待了这么大的团队。", "corrected_sentence": "我们公司从没接待过这么大的团队。", "error_description": "错误：“从没”之后应用“过”表示未曾有过的经历，此处误用“了”；正确：“我们公司从没接待过这么大的团队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
