INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95709, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "按照规矩来，是对的样子。", "primary_collocate": null, "pronunciation": "zhèng guī", "ipa": "ʈʂɤŋ˥˩ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "他的坐姿很正规。", "target_word": "正规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字写得不正规。", "target_word": "正规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他穿得很正规，像要去开会。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的动作不够正规。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学书法要先从正规的写法学起。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他练了很久，现在握笔的姿势很正规。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你按正规的步骤做，别自己乱改。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛时，运动员的动作必须做得正规。", "target_word": "正规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话的样子很正规，一看就是播音员。", "target_word": "正规", "complexity_tier": "T3", "furigana": "tā shuō huà de yàngzi hěn zhèngguī, yí kàn jiù shì bōyīnyuán.", "sentence_source": "generated"}, {"text": "他按正规的礼仪向大家问好，动作很得体。", "target_word": "正规", "complexity_tier": "T3", "furigana": "tā àn zhèngguī de lǐyí xiàng dàjiā wènhǎo, dòngzuò hěn détǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "正規", "label": "繁体"}, {"form": "正规化", "label": "复合"}], "register": "中性", "sense_fingerprint": "做法、动作、样子合乎规矩、标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正规", "is_correct": true, "explanation": "正规形容坐姿合乎规矩，句意通顺。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指味道，与坐姿的样子无关。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸指味道，不能用来形容坐姿。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容体型，不用来描述坐姿是否合乎规矩。"}], "explanations": {"正规": "正规形容坐姿合乎规矩，句意通顺。", "甜": "语义：甜指味道，与坐姿的样子无关。", "咸": "语义：咸指味道，不能用来形容坐姿。", "瘦": "体貌：瘦形容体型，不用来描述坐姿是否合乎规矩。"}, "sentence_index": 0, "correct_answer": "正规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张发票不正规，不能报销。", "explanation": "这里的正规指票据是否符合规定，是另一个义项；本句说的是票据，不是人的动作和样子。"}, {"text": "他参加了正规军，驻守在边境。", "explanation": "这里的正规是“正规军”的意思，与游击队相对，指军队的编制，与动作是否合乎规矩无关。"}, {"text": "他接受过正规教育，学历很高。", "explanation": "这里的正规指正统、系统的教育，是另一个义项，与人的动作和样子无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正规", "is_correct": true, "explanation": "正规修饰步骤，表示合乎规范、按标准来，句意通顺。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣指味觉，不能用来形容步骤。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：嫩多用于食物或植物，不修饰步骤。"}, {"text": "凉", "is_correct": false, "explanation": "语义：凉指温度的感受，与步骤是否规范无关。"}], "explanations": {"正规": "正规修饰步骤，表示合乎规范、按标准来，句意通顺。", "辣": "语义：辣指味觉，不能用来形容步骤。", "嫩": "搭配：嫩多用于食物或植物，不修饰步骤。", "凉": "语义：凉指温度的感受，与步骤是否规范无关。"}, "sentence_index": 6, "correct_answer": "正规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的玩笑很正规。", "explanation": "这里应该用〈有趣〉。正规指按照规矩、是对的样子，不用来形容玩笑。"}, {"text": "这所正规学校离家很近。", "explanation": "这里的正规指学校合乎办学规定，是另一个义项；本句说的是学校的位置，与人的动作和礼仪无关。"}, {"text": "这家正规药店价格很合理。", "explanation": "这里的正规指药店合乎经营规定，是另一个义项；本句说的是价格，与人的动作和礼仪无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师要求我们按正规地动作做操。", "corrected_sentence": "老师要求我们按正规的动作做操。", "error_description": "错误：修饰名词“动作”时用了“地”。正确：应为“正规的动作”。形容词修饰名词要用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她走路的姿态很的正规。", "corrected_sentence": "她走路的姿态很正规。", "error_description": "错误：程度副词“很”和“正规”之间多加了“的”。正确：应为“很正规”。“很”直接修饰形容词，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
