INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合规定的；合乎标准的。", "primary_collocate": null, "pronunciation": "zhèng guī", "ipa": "ʈʂɤŋ˥˩ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "这家医院很正规。", "target_word": "正规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买药要去正规的药店。", "target_word": "正规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在一家正规公司上班。", "target_word": "正规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张发票不正规，不能报销。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一所正规的学校学画画。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在正规网站买火车票，别上当。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王在正规培训机构学了半年英语。", "target_word": "正规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个市场里的东西都有正规的质量证明。", "target_word": "正规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有正规的工作证，保安不让他进去。", "target_word": "正规", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把正规的手续都办好了，才开始卖东西。", "target_word": "正规", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正規", "label": "繁体"}, {"form": "正规化", "label": "复合"}], "register": "中性", "sense_fingerprint": "符合规定、合乎标准的（机构、渠道、票据等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正规", "is_correct": true, "explanation": "正规修饰医院，表示符合规定、合乎标准，句意通顺。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指食物的味道，不能用来形容医院。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣指刺激味觉的感受，用在医院上不合常理。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：嫩多用于食物、植物或皮肤，不修饰医院。"}], "explanations": {"正规": "正规修饰医院，表示符合规定、合乎标准，句意通顺。", "甜": "语义：甜指食物的味道，不能用来形容医院。", "辣": "语义：辣指刺激味觉的感受，用在医院上不合常理。", "嫩": "搭配：嫩多用于食物、植物或皮肤，不修饰医院。"}, "sentence_index": 0, "correct_answer": "正规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体温很正规，医生说没什么问题。", "explanation": "这里应该用〈正常〉。正规指符合规定、合乎标准，形容体温、身体状况要用正常。"}, {"text": "这台机器的精度很正规，测量结果很准。", "explanation": "这里应该用〈精确〉。正规指符合规定、合乎标准，说精度、测量的准确程度要用精确。"}, {"text": "听到这个消息，她的心情很正规。", "explanation": "这里应该用〈平静〉。正规指符合规定、合乎标准，形容心情要用平静，不能用正规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正规", "is_correct": true, "explanation": "正规修饰培训机构，表示办学合乎规定、手续齐全，句意通顺。"}, {"text": "湿", "is_correct": false, "explanation": "语义：湿指含有水分，与培训机构的性质不符。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或物的体型，不用来修饰机构。"}, {"text": "软", "is_correct": false, "explanation": "搭配：软形容质地或性情，不说软培训机构。"}], "explanations": {"正规": "正规修饰培训机构，表示办学合乎规定、手续齐全，句意通顺。", "湿": "语义：湿指含有水分，与培训机构的性质不符。", "瘦": "体貌：瘦形容人或物的体型，不用来修饰机构。", "软": "搭配：软形容质地或性情，不说软培训机构。"}, "sentence_index": 6, "correct_answer": "正规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正规向大家道歉了。", "explanation": "这里应该用〈正式〉。正规指符合规定、合乎标准，不用来修饰道歉这类行为。"}, {"text": "他的玩笑很正规。", "explanation": "这里应该用〈有趣〉。正规指符合规定、合乎标准，不用来形容玩笑。"}, {"text": "今天的天气很正规，很适合出去玩。", "explanation": "这里应该用〈晴朗〉。正规指符合规定、合乎标准，形容天气要用晴朗之类的词，不能用正规。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在一家正规地诊所拿了药。", "corrected_sentence": "我在一家正规的诊所拿了药。", "error_description": "错误：正规后面用了“地”。正确：应为“正规的诊所”。形容词修饰名词要用“的”，“地”用于修饰动词或形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的手续办地很正规。", "corrected_sentence": "这家公司的手续办得很正规。", "error_description": "错误：补语标记“得”误用为“地”。正确：应为“办得很正规”。“地”用于修饰动词，不能放在动词和补语之间；动词后接补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
