INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彻底去掉；除去。", "primary_collocate": null, "pronunciation": "qīng chú", "ipa": "tɕʰiŋ˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "医生用药清除身体里的病毒。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的病毒已经清除了。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要清除学习中的障碍。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司清除了所有的错误记录。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想清除自己的坏习惯。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察清除了城里的毒品。", "target_word": "清除", "complexity_tier": "T3", "furigana": "jǐng chá qīng chú le chéng lǐ de dú pǐn", "sentence_source": "generated"}, {"text": "他清除了手机里的旧信息。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他清除了电脑里的所有记录。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须清除工作中的安全隐患。", "target_word": "清除", "complexity_tier": "T3", "furigana": "wǒ men bì xū qīng chú gōng zuò zhōng de ān quán yǐn huàn", "sentence_source": "generated"}, {"text": "这种药能清除身体里的毒。", "target_word": "清除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清除了", "label": "体标（了）"}, {"form": "清除过", "label": "体标（过）"}, {"form": "清除掉", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "彻底去掉病毒、错误、障碍等有害或不好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感染", "is_correct": false, "explanation": "语义：“感染”是病原体侵入人体，医生用药不应让病毒感染身体。"}, {"text": "清除", "is_correct": true, "explanation": "正确：“清除”表示彻底去掉身体里的病毒，符合治疗语境。"}, {"text": "扩散", "is_correct": false, "explanation": "语义：“扩散”是病毒自行蔓延，与“医生用药”的治疗语境相反。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能说翻译身体里的病毒。"}], "explanations": {"感染": "语义：“感染”是病原体侵入人体，医生用药不应让病毒感染身体。", "清除": "正确：“清除”表示彻底去掉身体里的病毒，符合治疗语境。", "扩散": "语义：“扩散”是病毒自行蔓延，与“医生用药”的治疗语境相反。", "翻译": "搭配：“翻译”的对象是语言或文字，不能说翻译身体里的病毒。"}, "sentence_index": 0, "correct_answer": "清除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他清除了自己的优点。", "explanation": "这里应该用〈发挥〉。清除指去掉有害或不好的东西，优点是要发挥的，不能清除。"}, {"text": "老师清除了学生的学习兴趣。", "explanation": "这里应该用〈培养〉。清除用于去掉有害的东西，学习兴趣是要培养的。"}, {"text": "身体清除了食物里的营养。", "explanation": "这里应该用〈吸收〉。清除用于去掉有害的东西，营养是身体需要吸收的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于音频或视频，不能说播放手机里的旧信息。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”是修理损坏的设备，与清理旧信息的语境不符。"}, {"text": "清除", "is_correct": true, "explanation": "正确：“清除”表示去掉手机里的旧信息，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是食物，不能说吃掉旧信息。"}], "explanations": {"播放": "搭配：“播放”用于音频或视频，不能说播放手机里的旧信息。", "维修": "语义：“维修”是修理损坏的设备，与清理旧信息的语境不符。", "清除": "正确：“清除”表示去掉手机里的旧信息，符合句意。", "吃掉": "搭配：“吃掉”的宾语应是食物，不能说吃掉旧信息。"}, "sentence_index": 6, "correct_answer": "清除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们清除了美好的周末。", "explanation": "这里应该用〈度过〉。清除指去掉有害的东西，美好的周末应当度过，不能清除。"}, {"text": "大家清除了热闹的春节。", "explanation": "这里应该用〈庆祝〉。清除用于去掉有害的东西，春节要庆祝。"}, {"text": "我们清除了一个愉快的假期。", "explanation": "这里应该用〈享受〉。清除用于去掉有害的东西，愉快的假期要享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把身体里的毒素清除了掉。", "corrected_sentence": "他把身体里的毒素清除掉了。", "error_description": "错误：“清除了掉”；正确：“清除掉了”。结果补语“掉”应紧跟在动词“清除”之后，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把清除了手机里的旧信息。", "corrected_sentence": "他清除了手机里的旧信息。", "error_description": "错误：“清除”前多加了“把”，“把”字句要求把宾语提到动词前，此句缺少宾语；正确：去掉“把”，说“他清除了手机里的旧信息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
