INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95721, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "蒙就是用布把东西盖住。东西被盖住，就看不见了。", "primary_collocate": null, "pronunciation": "méng", "ipa": "/mɤŋ˧˥/", "syllable_count": 1, "sentences": [{"text": "妈妈用布把桌子蒙住了。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一块黑布蒙住了眼睛。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕冷，把头蒙在毯子里。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷，他用围巾蒙上了脸。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用手帕蒙着眼睛，不要偷看。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的笼子上蒙着一块布。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，农民用塑料布把菜蒙好。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏开始前，大家要用布蒙眼睛。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头蒙起来，不想看电视。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用报纸把桌子蒙上，免得弄脏。", "target_word": "蒙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒙了", "label": "体标"}, {"form": "蒙着", "label": "体标"}, {"form": "蒙过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用布等东西把物体或眼睛、头等遮盖住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蒙", "is_correct": true, "explanation": "本词 méng（第二声），意思是用布等东西把物体盖住。"}, {"text": "猛", "is_correct": false, "explanation": "měng（第三声）与 méng（第二声）声调不同，意思是凶猛。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 méng（第二声）声调不同，意思是梦境。"}, {"text": "门", "is_correct": false, "explanation": "mén 与 méng 韵尾不同（en/eng），意思是门。"}], "explanations": {"蒙": "本词 méng（第二声），意思是用布等东西把物体盖住。", "猛": "měng（第三声）与 méng（第二声）声调不同，意思是凶猛。", "梦": "mèng（第四声）与 méng（第二声）声调不同，意思是梦境。", "门": "mén 与 méng 韵尾不同（en/eng），意思是门。"}, "sentence_index": null, "correct_answer": "蒙"}, "level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "语义：擦是抹去灰尘或污渍，不是用布遮盖。"}, {"text": "蒙", "is_correct": true, "explanation": "蒙住表示用布遮盖桌子，与句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能与“桌子”搭配。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是把东西分开，与用布遮盖无关。"}], "explanations": {"擦": "语义：擦是抹去灰尘或污渍，不是用布遮盖。", "蒙": "蒙住表示用布遮盖桌子，与句意相符。", "煮": "搭配：“煮”的对象是食物，不能与“桌子”搭配。", "切": "语义：切是把东西分开，与用布遮盖无关。"}, "sentence_index": 0, "correct_answer": "蒙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在合同上蒙了章。", "explanation": "这里应该用〈盖〉。盖章要用“盖”，蒙只表示用布等遮住，不能用于印章。"}, {"text": "他蒙着眼镜走进了教室。", "explanation": "这里应该用〈架〉。戴眼镜要说“架”，蒙指用布等东西遮盖，不能用于眼镜。"}, {"text": "他蒙上了一个好成绩。", "explanation": "这里应该用〈取得〉。取得成绩不能说“蒙”，“蒙”指用东西遮盖物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95721, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蒙", "is_correct": true, "explanation": "本词 méng（第二声），意思是用布等东西把物体盖住。"}, {"text": "忙", "is_correct": false, "explanation": "máng（第二声）与 méng 韵尾不同（eng/ang），意思是忙碌。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 méng 韵母不同（eng/ing），意思是明亮。"}, {"text": "名", "is_correct": false, "explanation": "míng（第二声）与 méng 韵母不同（eng/ing），意思是名字。"}], "explanations": {"蒙": "本词 méng（第二声），意思是用布等东西把物体盖住。", "忙": "máng（第二声）与 méng 韵尾不同（eng/ang），意思是忙碌。", "明": "míng（第二声）与 méng 韵母不同（eng/ing），意思是明亮。", "名": "míng（第二声）与 méng 韵母不同（eng/ing），意思是名字。"}, "sentence_index": null, "correct_answer": "蒙"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：写是书写文字，与“把菜”的处理无关。"}, {"text": "蒙", "is_correct": true, "explanation": "蒙好表示用塑料布把菜遮盖好，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱菜”。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚推击，与用布遮盖菜无关。"}], "explanations": {"写": "语义：写是书写文字，与“把菜”的处理无关。", "蒙": "蒙好表示用塑料布把菜遮盖好，与句意相符。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱菜”。", "踢": "语义：踢是用脚推击，与用布遮盖菜无关。"}, "sentence_index": 6, "correct_answer": "蒙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蒙上了作业，准备交给老师。", "explanation": "这里应该用〈交〉。交作业要用“交”，“蒙”指用东西遮盖物体，作业不能被遮盖。"}, {"text": "他蒙上了领带，准备上班。", "explanation": "这里应该用〈系〉。领带要说“系”，蒙只表示用布等遮盖物体，不能用于领带。"}, {"text": "他在墙上蒙了海报。", "explanation": "这里应该用〈贴〉。贴海报要用“贴”，蒙指用布等遮盖，不能用于海报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户上蒙了着一层灰。", "corrected_sentence": "窗户上蒙着一层灰。", "error_description": "“蒙”后表示状态要用“着”，“了”与“着”不能同时出现在同一动词后。正确为「窗户上蒙着一层灰。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把菜蒙了上，怕苍蝇飞进去。", "corrected_sentence": "妈妈把菜蒙上了，怕苍蝇飞进去。", "error_description": "结果补语“上”应紧跟动词“蒙”，“了”放在补语之后。“蒙了上”说不通，正确为「妈妈把菜蒙上了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
