INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "失火造成的灾害，指火失去控制而烧毁财物、伤害人畜的事故。", "primary_collocate": null, "pronunciation": "huǒ zāi", "ipa": "/xuɔ˨˩˦ tsaɪ˥˥/", "syllable_count": 2, "sentences": [{"text": "森林火灾持续了三天三夜。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾造成了很大的经济损失。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在调查这起火灾的原因。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线老化是引发火灾的常见原因。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买了保险，以防发生火灾。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾没有造成人员伤亡。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾发生后，警察马上封了路。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这座城市发生过几次火灾。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下有人喊着出了火灾，大家都跑了出去。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场里有很多防火设备，以便应对火灾。", "target_word": "火灾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场火灾", "label": "量词"}, {"form": "一起火灾", "label": "量词"}], "register": "中性", "sense_fingerprint": "火失去控制而造成财物损失和人员伤害的灾害事故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火灾", "is_correct": true, "explanation": "正确：森林火灾是火失控造成的灾害，能够“持续三天三夜”，符合句意。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言是语言的变体，不能作为持续的事件主体。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮品，不是会持续的事件，与“持续三天三夜”不合。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：“森林广告”搭配不通，“森林”无法修饰广告。"}], "explanations": {"火灾": "正确：森林火灾是火失控造成的灾害，能够“持续三天三夜”，符合句意。", "方言": "语义：方言是语言的变体，不能作为持续的事件主体。", "果汁": "语义：果汁是饮品，不是会持续的事件，与“持续三天三夜”不合。", "广告": "搭配：“森林广告”搭配不通，“森林”无法修饰广告。"}, "sentence_index": 0, "correct_answer": "火灾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洪水是一种严重的火灾。", "explanation": "这里应该用〈灾害〉。火灾是火失控造成的灾害，洪水不是火，不能称为火灾。"}, {"text": "台风是一场可怕的火灾。", "explanation": "这里应该用〈灾难〉。台风不是火，不能用火灾来指代，应说“灾难”。"}, {"text": "这根蜡烛的火灾很旺，还是别点了。", "explanation": "这里应该用〈火焰〉。火灾指造成损失的灾害，蜡烛燃烧的火焰不是火灾，应说“这根蜡烛的火焰很旺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火灾", "is_correct": true, "explanation": "正确：火灾是可以“发生”的事件，句中说发生后警察封路，符合语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不是会发生的事件，句意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是事件，不能作为“发生”的主语。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“发生”后面接的是事件，“晚饭”不能与“发生”搭配。"}], "explanations": {"火灾": "正确：火灾是可以“发生”的事件，句中说发生后警察封路，符合语境。", "窗户": "语义：窗户是物件，不是会发生的事件，句意不通。", "蛋糕": "语义：蛋糕不是事件，不能作为“发生”的主语。", "晚饭": "搭配：“发生”后面接的是事件，“晚饭”不能与“发生”搭配。"}, "sentence_index": 6, "correct_answer": "火灾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防车停在门口，正在扑灭这条火灾。", "explanation": "量词错误：“条”用于长条形的东西，不能修饰火灾，应说“这场火灾”。"}, {"text": "这个晚上，他们在山谷里点了一场火灾。", "explanation": "这里指山谷里点的火，是另一种意思，并非造成损失的灾害，火灾一词在此不适用。"}, {"text": "这座火灾已经被扑灭了，大家松了一口气。", "explanation": "量词错误：“座”用于楼房、山等，不能修饰火灾，应说“这场火灾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年我们那里发生了一条森林火灾。", "corrected_sentence": "去年我们那里发生了一场森林火灾。", "error_description": "量词错误：森林火灾是事件，量词应用“场”，“条”用于长条形的东西，不能修饰火灾。应改为“一场森林火灾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只火灾造成了三人受伤。", "corrected_sentence": "这场火灾造成了三人受伤。", "error_description": "量词错误：火灾用“场”，“只”用于动物等，不能修饰火灾。应改为“这场火灾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
