INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95725, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人与人之间关系非常亲密，彼此之间没有隔阂。", "primary_collocate": null, "pronunciation": "wú jiàn", "ipa": "u˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他们两人感情无间，像亲兄弟一样。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "我和她从小一起长大，感情无间。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "这对好朋友感情无间，每天都在一起。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "他们俩感情无间，什么话都可以说。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "老同学见面，大家的情谊依然无间。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "姐妹俩感情无间，从来不吵架。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "他和哥哥感情无间，无话不谈。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "两位老人相处无间，一起生活了五十年。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "他们是感情无间的好朋友。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}, {"text": "大家感情无间，好像一家人。", "target_word": "无间", "complexity_tier": "T3", "furigana": "wú jiàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲密无间", "label": "复合"}, {"form": "無間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词：人与人关系极亲密，中间没有隔阂（亲密无间）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95725, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容人与人关系亲密、中间没有隔阂。"}, {"text": "无限", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是关系亲密。"}, {"text": "物件", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是物品，不是关系亲密。"}, {"text": "午间", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。"}, {"text": "舞剑", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容人与人关系亲密、中间没有隔阂。", "无限": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是关系亲密。", "物件": "wù（第四声）与 wú（第二声）声调不同，意思是物品，不是关系亲密。", "午间": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。", "舞剑": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：感情亲密、没有隔阂，与“像亲兄弟一样”相合。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指感情疏远，与后句“像亲兄弟一样”矛盾。"}, {"text": "分明", "is_correct": false, "explanation": "搭配：“感情”不说“分明”，“分明”多用于界限、爱憎。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指不熟悉、不亲近，与“像亲兄弟一样”矛盾。"}], "explanations": {"无间": "正确答案。无间：感情亲密、没有隔阂，与“像亲兄弟一样”相合。", "冷淡": "语义：“冷淡”指感情疏远，与后句“像亲兄弟一样”矛盾。", "分明": "搭配：“感情”不说“分明”，“分明”多用于界限、爱憎。", "生疏": "语义：“生疏”指不熟悉、不亲近，与“像亲兄弟一样”矛盾。"}, "sentence_index": 0, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次聚会上，大家的气氛很无间。", "explanation": "这里应该用〈融洽〉。无间形容人与人之间关系亲密、没有隔阂，不用来形容气氛。"}, {"text": "奶奶对我的态度很无间。", "explanation": "这里应该用〈亲切〉。无间指彼此之间没有隔阂，不用来形容对待别人的态度。"}, {"text": "这次比赛的规则很无间。", "explanation": "这里应该用〈公平〉。无间用于人与人之间的关系，不用来形容规则。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95725, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容人与人关系亲密、中间没有隔阂。"}, {"text": "无线", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与关系亲密无关。"}, {"text": "无价", "is_correct": false, "explanation": "jià 比 jiàn 少了韵尾 n，意思是价值极高，不是关系亲密。"}, {"text": "五件", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容人与人关系亲密、中间没有隔阂。", "无线": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与关系亲密无关。", "无价": "jià 比 jiàn 少了韵尾 n，意思是价值极高，不是关系亲密。", "五件": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：感情亲密、没有隔阂，与“无话不谈”相合。"}, {"text": "淡薄", "is_correct": false, "explanation": "语义：“淡薄”指感情不深，与后句“无话不谈”矛盾。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“感情”不说“清晰”，这里搭配不通。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”指关系不和，与“无话不谈”矛盾。"}], "explanations": {"无间": "正确答案。无间：感情亲密、没有隔阂，与“无话不谈”相合。", "淡薄": "语义：“淡薄”指感情不深，与后句“无话不谈”矛盾。", "清晰": "搭配：“感情”不说“清晰”，这里搭配不通。", "紧张": "语义：“紧张”指关系不和，与“无话不谈”矛盾。"}, "sentence_index": 6, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的服务非常无间。", "explanation": "这里应该用〈周到〉。无间用于人与人之间的关系，不用来形容服务。"}, {"text": "大家的看法很无间。", "explanation": "这里应该用〈一致〉。无间强调人与人之间没有隔阂，不用来形容看法是否相同。"}, {"text": "这次考试的题目很无间。", "explanation": "这里应该用〈难〉。无间用于人与人之间的关系，不用来形容题目的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.