INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她们是感情无间好姐妹。", "corrected_sentence": "她们是感情无间的好姐妹。", "error_description": "“感情无间”修饰名词“好姐妹”时中间要加“的”，应说“感情无间的好姐妹”，不能说“感情无间好姐妹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们是感情无间地朋友。", "corrected_sentence": "他们是感情无间的朋友。", "error_description": "结构助词错误：修饰名词“朋友”应用“的”，不能用“地”（“地”用于修饰动词）。应说“感情无间的朋友”，不说“感情无间地朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
