INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在合作或配合中彼此默契，没有隔阂或脱节。", "primary_collocate": null, "pronunciation": "wú jiàn", "ipa": "u˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "两个公司合作无间，生意越做越好。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们配合无间，很快赢了比赛。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们合作无间，一个星期就做完了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩配合无间，像一个人一样。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和员工合作无间，工作很开心。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的三个人配合无间，菜很快做好了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对搭档合作无间，已经一起工作十年了。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家合作无间，终于完成了任务。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在场上配合无间，大家都夸他们。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国一直合作无间，关系很好。", "target_word": "无间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合作无间", "label": "复合"}, {"form": "配合无间", "label": "复合"}, {"form": "無間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词：合作、配合没有隔阂、毫无间隙（合作无间）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。"}, {"text": "无限", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是配合默契。"}, {"text": "物件", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是物品，与配合无关。"}, {"text": "午间", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。"}, {"text": "舞剑", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。", "无限": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是没有限度，不是配合默契。", "物件": "wù（第四声）与 wú（第二声）声调不同，意思是物品，与配合无关。", "午间": "wǔ（第三声）与 wú（第二声）、jiān（第一声）与 jiàn（第四声）声调都不同，意思是中午前后。", "舞剑": "wǔ（第三声）与 wú（第二声）声调不同，意思是挥舞宝剑。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：合作配合没有隔阂，与“生意越做越好”相合。"}, {"text": "不畅", "is_correct": false, "explanation": "语义：“不畅”指不顺利，与“生意越做越好”矛盾。"}, {"text": "疏远", "is_correct": false, "explanation": "搭配：“合作”不说“疏远”，“疏远”指关系不亲近，与“生意越做越好”的合作前景矛盾。"}, {"text": "敷衍", "is_correct": false, "explanation": "语义：“敷衍”指应付了事，与“生意越做越好”不符。"}], "explanations": {"无间": "正确答案。无间：合作配合没有隔阂，与“生意越做越好”相合。", "不畅": "语义：“不畅”指不顺利，与“生意越做越好”矛盾。", "疏远": "搭配：“合作”不说“疏远”，“疏远”指关系不亲近，与“生意越做越好”的合作前景矛盾。", "敷衍": "语义：“敷衍”指应付了事，与“生意越做越好”不符。"}, "sentence_index": 0, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这台机器很无间。", "explanation": "这里应该用〈熟练〉。无间用于人与人之间的配合或关系，不用来形容对机器的操作。"}, {"text": "这条路的交通很无间。", "explanation": "这里应该用〈顺畅〉。无间不用来形容交通状况，交通应说顺畅。"}, {"text": "这块布料的颜色很无间。", "explanation": "这里应该用〈均匀〉。无间用于人与人之间的配合，不用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。"}, {"text": "无线", "is_correct": false, "explanation": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与配合无关。"}, {"text": "无价", "is_correct": false, "explanation": "jià 比 jiàn 少了韵尾 n，意思是价值极高，与配合无关。"}, {"text": "五件", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}], "explanations": {"无间": "正确答案。无间：wú jiàn，形容配合默契、没有隔阂。", "无线": "xiàn（x 声母）与 jiàn（j 声母）声母不同，意思是不用导线，与配合无关。", "无价": "jià 比 jiàn 少了韵尾 n，意思是价值极高，与配合无关。", "五件": "wǔ（第三声）与 wú（第二声）声调不同，意思是五件东西，是数量短语。"}, "sentence_index": null, "correct_answer": "无间"}, "level_3": {"options": [{"text": "无间", "is_correct": true, "explanation": "正确答案。无间：合作没有隔阂，与“已经一起工作十年了”相合。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指时间不长，与“已经一起工作十年了”矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“合作”不说“粗糙”，“粗糙”形容质地或做事不细致。"}, {"text": "散乱", "is_correct": false, "explanation": "搭配：“合作”不说“散乱”，“散乱”形容东西分散、没有条理。"}], "explanations": {"无间": "正确答案。无间：合作没有隔阂，与“已经一起工作十年了”相合。", "短暂": "语义：“短暂”指时间不长，与“已经一起工作十年了”矛盾。", "粗糙": "搭配：“合作”不说“粗糙”，“粗糙”形容质地或做事不细致。", "散乱": "搭配：“合作”不说“散乱”，“散乱”形容东西分散、没有条理。"}, "sentence_index": 6, "correct_answer": "无间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题解释得很无间。", "explanation": "这里应该用〈清楚〉。无间不用来形容解释是否明白。"}, {"text": "他做作业很无间。", "explanation": "这里应该用〈认真〉。无间用于人与人之间的配合，不用来形容做事的态度。"}, {"text": "房间打扫得很无间。", "explanation": "这里应该用〈整洁〉。无间不用来形容房间干净与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是配合无间好搭档。", "corrected_sentence": "他们是配合无间的好搭档。", "error_description": "“配合无间”修饰名词“搭档”时中间要加“的”，应说“配合无间的好搭档”，不能说“配合无间好搭档”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对配合无间地老同事很有名。", "corrected_sentence": "这对配合无间的老同事很有名。", "error_description": "结构助词错误：修饰名词“老同事”应用“的”，不能用“地”（“地”用于修饰动词）。应说“配合无间的老同事”，不说“配合无间地老同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
