INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牙长在嘴巴里，白白硬硬的。我们用牙咬东西、嚼饭。", "primary_collocate": null, "pronunciation": "yá", "ipa": "ja˧˥", "syllable_count": 1, "sentences": [{"text": "我的牙很疼，想去看医生。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子掉了一颗牙。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完糖要马上漱口，不然牙会坏。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗用牙咬住了球。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的牙不好，只能吃软的饭。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑的时候，露出一口白牙。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉太硬，我的牙咬不动。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我有两颗牙要拔掉。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的牙都掉光了。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家宝宝六个月就长牙了。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "牙齿", "label": "复合"}], "register": "口语", "sense_fingerprint": "人和动物嘴里用来咬东西的牙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。"}, {"text": "压", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“压”意思是用力按下。"}, {"text": "鸭", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“鸭”指一种家禽。"}, {"text": "哑", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。"}, {"text": "雅", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“雅”意思是文雅、高雅。"}], "explanations": {"牙": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。", "压": "yā（第一声）与 yá（第二声）声调不同，“压”意思是用力按下。", "鸭": "yā（第一声）与 yá（第二声）声调不同，“鸭”指一种家禽。", "哑": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。", "雅": "yǎ（第三声）与 yá（第二声）声调不同，“雅”意思是文雅、高雅。"}, "sentence_index": null, "correct_answer": "牙"}, "level_3": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：“牙”指口腔器官，可以感到疼，符合“想去看医生”。"}, {"text": "胡子", "is_correct": false, "explanation": "语义：胡子不会感到疼，与“很疼”矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会感到疼，与“很疼”矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“疼”的主语通常是人或身体部位，不说“窗户很疼”。"}], "explanations": {"牙": "正确答案：“牙”指口腔器官，可以感到疼，符合“想去看医生”。", "胡子": "语义：胡子不会感到疼，与“很疼”矛盾。", "书包": "语义：书包不会感到疼，与“很疼”矛盾。", "窗户": "搭配：“疼”的主语通常是人或身体部位，不说“窗户很疼”。"}, "sentence_index": 0, "correct_answer": "牙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我掉了一只牙，很疼。", "explanation": "量词错误：“牙”应该用量词“颗”，“只”用于动物或成对的东西，这里应说“一颗牙”。"}, {"text": "他用牙看了一眼远处的山。", "explanation": "这里应该用〈眼睛〉。牙是咬嚼的器官，不能用来看东西。"}, {"text": "妈妈用牙摸我的头。", "explanation": "这里应该用〈手〉。牙是咬嚼的器官，不能用来摸东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。"}, {"text": "亚", "is_correct": false, "explanation": "yà（第四声）与 yá（第二声）声调不同，“亚”用于亚洲等词。"}, {"text": "哑", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。"}, {"text": "押", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“押”意思是抵押或押送。"}, {"text": "丫", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“丫”意思是树木分叉或小女孩。"}], "explanations": {"牙": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。", "亚": "yà（第四声）与 yá（第二声）声调不同，“亚”用于亚洲等词。", "哑": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。", "押": "yā（第一声）与 yá（第二声）声调不同，“押”意思是抵押或押送。", "丫": "yā（第一声）与 yá（第二声）声调不同，“丫”意思是树木分叉或小女孩。"}, "sentence_index": null, "correct_answer": "牙"}, "level_3": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：“牙”能咬东西，符合“咬不动”的语境。"}, {"text": "手", "is_correct": false, "explanation": "语义：手不用来咬东西，与“咬不动”不相符。"}, {"text": "腿", "is_correct": false, "explanation": "语义：腿不用来咬东西，与“咬不动”不相符。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“咬”的主语必须是口腔器官，不说“身体咬不动”。"}], "explanations": {"牙": "正确答案：“牙”能咬东西，符合“咬不动”的语境。", "手": "语义：手不用来咬东西，与“咬不动”不相符。", "腿": "语义：腿不用来咬东西，与“咬不动”不相符。", "身体": "搭配：“咬”的主语必须是口腔器官，不说“身体咬不动”。"}, "sentence_index": 6, "correct_answer": "牙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的牙走路很快。", "explanation": "这里应该用〈脚〉。牙是口腔器官，走路要用脚，不能用牙。"}, {"text": "老师的牙正在认真地读书。", "explanation": "这里应该用〈眼睛〉。牙不能用来读书，读书要用眼睛。"}, {"text": "小猫的牙喝了一碗牛奶。", "explanation": "这里应该用〈嘴〉。牙是咬嚼的器官，喝牛奶要用嘴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_