INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长在口腔里，用来咬和嚼食物的坚硬器官。", "primary_collocate": null, "pronunciation": "yá", "ipa": "ja˧˥", "syllable_count": 1, "sentences": [{"text": "牙用来咬东西，也帮我们嚼食物。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时，牙把食物嚼碎。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他牙上有一个小洞，需要补一补。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗牙长歪了，要矫正。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了孩子的每一颗牙。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的牙很整齐，笑起来很好看。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲨鱼的牙又尖又长。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多甜食，牙容易坏。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老马的牙磨平了，吃草很慢。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人一生会长两次牙。", "target_word": "牙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "牙齿", "label": "复合"}], "register": "中性", "sense_fingerprint": "口腔里咬和嚼食物的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c44c436-e2e9-48e7-8596-898e18732794') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。"}, {"text": "亚", "is_correct": false, "explanation": "yà（第四声）与 yá（第二声）声调不同，“亚”用于亚洲等词。"}, {"text": "哑", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。"}, {"text": "押", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“押”意思是抵押或押送。"}, {"text": "丫", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“丫”意思是树木分叉或小女孩。"}], "explanations": {"牙": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。", "亚": "yà（第四声）与 yá（第二声）声调不同，“亚”用于亚洲等词。", "哑": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。", "押": "yā（第一声）与 yá（第二声）声调不同，“押”意思是抵押或押送。", "丫": "yā（第一声）与 yá（第二声）声调不同，“丫”意思是树木分叉或小女孩。"}, "sentence_index": null, "correct_answer": "牙"}, "level_3": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：“牙”是咬嚼食物的器官，符合“用来咬东西，也帮我们嚼食物”。"}, {"text": "手", "is_correct": false, "explanation": "语义：手不用来咬东西，也不能嚼食物。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：筷子夹食物，不能咬东西或嚼食物。"}, {"text": "刀", "is_correct": false, "explanation": "搭配：刀用来切割，不说“刀用来咬东西”。"}], "explanations": {"牙": "正确答案：“牙”是咬嚼食物的器官，符合“用来咬东西，也帮我们嚼食物”。", "手": "语义：手不用来咬东西，也不能嚼食物。", "筷子": "语义：筷子夹食物，不能咬东西或嚼食物。", "刀": "搭配：刀用来切割，不说“刀用来咬东西”。"}, "sentence_index": 0, "correct_answer": "牙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生拔掉了一只牙，很快就好了。", "explanation": "量词错误：“牙”应该用量词“颗”，不能用“只”，“只”用于动物或成对的东西。"}, {"text": "他的牙把书翻开了。", "explanation": "这里应该用〈手〉。牙是咬嚼的器官，翻书要用手，不能用牙。"}, {"text": "他用牙闻花。", "explanation": "这里应该用〈鼻子〉。牙不能用来闻东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。"}, {"text": "压", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“压”意思是用力按下。"}, {"text": "鸭", "is_correct": false, "explanation": "yā（第一声）与 yá（第二声）声调不同，“鸭”指一种家禽。"}, {"text": "哑", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。"}, {"text": "雅", "is_correct": false, "explanation": "yǎ（第三声）与 yá（第二声）声调不同，“雅”意思是文雅、高雅。"}], "explanations": {"牙": "正确答案：牙（yá，第二声），指长在口腔里、用来咬嚼食物的器官。", "压": "yā（第一声）与 yá（第二声）声调不同，“压”意思是用力按下。", "鸭": "yā（第一声）与 yá（第二声）声调不同，“鸭”指一种家禽。", "哑": "yǎ（第三声）与 yá（第二声）声调不同，“哑”意思是不能说话或声音难听。", "雅": "yǎ（第三声）与 yá（第二声）声调不同，“雅”意思是文雅、高雅。"}, "sentence_index": null, "correct_answer": "牙"}, "level_3": {"options": [{"text": "牙", "is_correct": true, "explanation": "正确答案：“牙”长在鲨鱼口中，符合“又尖又长”的形状描述。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不会又尖又长，与描述不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“又尖又长”形容物体形状，不用来修饰颜色。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：皮肤不会又尖又长，与描述不符。"}], "explanations": {"牙": "正确答案：“牙”长在鲨鱼口中，符合“又尖又长”的形状描述。", "眼睛": "语义：眼睛不会又尖又长，与描述不符。", "颜色": "搭配：“又尖又长”形容物体形状，不用来修饰颜色。", "皮肤": "语义：皮肤不会又尖又长，与描述不符。"}, "sentence_index": 6, "correct_answer": "牙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的牙每天跑步五公里。", "explanation": "这里应该用〈腿〉。牙是口腔器官，跑步要用腿，不能用牙。"}, {"text": "妈妈的牙正在唱歌。", "explanation": "这里应该用〈嗓子〉。牙不能唱歌，唱歌要靠嗓子。"}, {"text": "他用牙写字，写得很漂亮。", "explanation": "“牙”不能用来写字，写字需要用手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c90960a-6c3b-4a06-9171-bce75b911b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EX