INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95731, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "特有是只有这一个才有，别的都没有。", "primary_collocate": null, "pronunciation": "tè yǒu", "ipa": "tʰɤ˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大熊猫是中国特有的动物。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花是这个岛特有的。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋鼠是澳大利亚特有的动物。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖里有一种特有的鱼。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山上有很多特有的树。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金丝猴是我国特有的保护动物。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草只长在这里，是特有的。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾有不少特有的鸟。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼是这个湖特有的，别的地方看不到。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶是南方山区特有的。", "target_word": "特有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "只有某地或某类事物才有，别处没有（多指动植物、物种）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64a64bbf-a09a-4665-ad84-e6d6a40dfd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "正确：“特有”指只有某地才有的事物，修饰“中国”后的动物，符合句意。"}, {"text": "外来", "is_correct": false, "explanation": "语义：大熊猫原产中国，说“外来”与事实相反。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体，不能修饰动物。"}, {"text": "易碎", "is_correct": false, "explanation": "搭配：“易碎”多形容器物，不能用来描述动物。"}], "explanations": {"特有": "正确：“特有”指只有某地才有的事物，修饰“中国”后的动物，符合句意。", "外来": "语义：大熊猫原产中国，说“外来”与事实相反。", "透明": "搭配：“透明”形容物体，不能修饰动物。", "易碎": "搭配：“易碎”多形容器物，不能用来描述动物。"}, "sentence_index": 0, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小楼的设计很特有。", "explanation": "这里应该用〈独特〉。特有强调只有某地或某类才有，形容设计风格时用“独特”，“很特有”不自然。"}, {"text": "麻雀在城市和乡村到处都有，是特有的鸟。", "explanation": "这里应该用〈常见〉。特有表示只有某地才有，而麻雀到处都有，二者矛盾，应说“常见的鸟”。"}, {"text": "听到这个消息，他特有的高兴。", "explanation": "这里应该用〈特别〉。特有表示只有这一个才有，不能表示程度；形容高兴的程度应说“特别高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特有", "is_correct": true, "explanation": "正确：“特有”指只在某地生长，与“只长在这里”的语境一致。"}, {"text": "普遍", "is_correct": false, "explanation": "语义：“普遍”指到处都有，与“只长在这里”的意思相矛盾。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：草不能狡猾，“狡猾”只用于人或动物。"}, {"text": "繁多", "is_correct": false, "explanation": "搭配：“繁多”修饰种类、数量，不修饰草，不能说“是繁多的”。"}], "explanations": {"特有": "正确：“特有”指只在某地生长，与“只长在这里”的语境一致。", "普遍": "语义：“普遍”指到处都有，与“只长在这里”的意思相矛盾。", "狡猾": "语义：草不能狡猾，“狡猾”只用于人或动物。", "繁多": "搭配：“繁多”修饰种类、数量，不修饰草，不能说“是繁多的”。"}, "sentence_index": 6, "correct_answer": "特有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他特有来看我，我很感动。", "explanation": "这里应该用〈特意〉。特有是形容词，表示只有这一个才有，不能当副词表示“特地”，应说“他特意来看我”。"}, {"text": "他说话的声音特有的大，隔壁房间都听得见。", "explanation": "这里应该用〈特别〉。特有表示独有，不表示程度；形容声音大应说“特别大”。"}, {"text": "这首歌在全国都很流行，是特有的。", "explanation": "这里说“全国都流行”，与“特有”的排他含义正相反，用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种植物是中国特有地品种。", "corrected_sentence": "这种植物是中国特有的品种。", "error_description": "结构助词用错：“特有”是形容词，修饰名词“品种”时应用“的”，不能用“地”（“地”用于修饰动词或形容词）。正确为「这种植物是中国特有的品种。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个岛上有很多特有了的植物。", "corrected_sentence": "这个岛上有很多特有的植物。", "error_description": "语法错误：“特有”是形容词，后面不能直接加“了”，“特有了的植物”应说“特有的植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da7ced13-a213-4e55-b961-56fba3a67cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
