INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生涯是一个人做某一件事做了很多年的日子。", "primary_collocate": null, "pronunciation": "shēng yá", "ipa": "ʂɤŋ˥ ja˧˥", "syllable_count": 2, "sentences": [{"text": "他的教师生涯一共有三十年。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在球场上度过了二十年的运动生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，当兵的生涯让他学会了坚强。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工作生涯才刚刚开始。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员的舞台生涯超过四十年。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他常常回忆自己的医生生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的写作生涯很长，写了二十多本书。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的司机生涯从二十岁开始。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的歌手生涯很成功，大家都喜欢她。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结束了十年的足球生涯，开了一家小店。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人长年做某件事所度过的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。生涯指一个人长年做某件事的时期，可以说“教师生涯”，“一共有三十年”说明时长。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，不能持续“三十年”，与“一共有三十年”的时长说法冲突。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”说的是年龄，不说“教师年纪一共有三十年”，与“教师”后面的时期说法不搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不是可以计算年数的时期，与句子的时长不符。"}], "explanations": {"生涯": "正确。生涯指一个人长年做某件事的时期，可以说“教师生涯”，“一共有三十年”说明时长。", "学历": "语义：学历指受教育的程度，不能持续“三十年”，与“一共有三十年”的时长说法冲突。", "年纪": "搭配：“年纪”说的是年龄，不说“教师年纪一共有三十年”，与“教师”后面的时期说法不搭配。", "脾气": "语义：脾气是性格特点，不是可以计算年数的时期，与句子的时长不符。"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次去西藏的旅行是我最难忘的生涯。", "explanation": "这里应该用〈经历〉。生涯指长年从事某件事的时期，一次旅行不能叫生涯。"}, {"text": "毕业以后，我送给老师一份好生涯。", "explanation": "这里应该用〈礼物〉。生涯是抽象的一段时期，不能一份一份地送人，应说“礼物”。"}, {"text": "这个夏天的生涯很短暂。", "explanation": "这里应该用〈时光〉。生涯指长年从事某事的一段时期，用于一个夏天这样的短暂时间不合适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“写作生涯”指长年从事写作的时期，与“很长”和“写了二十多本书”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有长短，不能说“写作颜色很长”，也与写书无关。"}, {"text": "发音", "is_correct": false, "explanation": "语义：发音是说话的声音，不是写作的时期，“写作发音很长”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用来形容写作，句子说“很长”也不通。"}], "explanations": {"生涯": "正确。“写作生涯”指长年从事写作的时期，与“很长”和“写了二十多本书”相合。", "颜色": "语义：颜色没有长短，不能说“写作颜色很长”，也与写书无关。", "发音": "语义：发音是说话的声音，不是写作的时期，“写作发音很长”说不通。", "身高": "体貌：“身高”指人的身体高矮，不能用来形容写作，句子说“很长”也不通。"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛只用了十分钟，却是他的足球生涯。", "explanation": "这里应该用〈时刻〉。生涯指长年从事某事的一段时期，只用十分钟的比赛不能叫生涯，应说“时刻”。"}, {"text": "他把自己的生涯放进了行李箱。", "explanation": "这里应该用〈物品〉。生涯是抽象的一段时期，不是可以装进行李箱的具体东西，应说“物品”。"}, {"text": "妈妈把他的生涯洗干净，晾在阳台上。", "explanation": "这里应该用〈衣服〉。生涯是抽象的一段时期，不能洗涤、晾晒，此处应说“衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这所学校度过了一场漫长的生涯。", "corrected_sentence": "他在这所学校度过了一段漫长的生涯。", "error_description": "量词错误：“生涯”应该用“段”，不能用“场”。“场”用于比赛、演出等事件，“一场漫长的生涯”错误，应改为“一段漫长的生涯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的教师生涯结束起来，她转行做了编辑。", "corrected_sentence": "她的教师生涯结束了，她转行做了编辑。", "error_description": "补语错误：表示事情已经完成，“结束”后应用“了”，不能用“起来”。错误句是“结束起来”，正确句是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
