INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人从事某种活动或职业的经历和时期。", "primary_collocate": null, "pronunciation": "shēng yá", "ipa": "ʂɤŋ˥ ja˧˥", "syllable_count": 2, "sentences": [{"text": "在大学的学习生涯中，她认识了很多朋友。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职业生涯很顺利。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教学生涯充满了快乐。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军队的生涯给他留下了很多回忆。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想写一本书，讲讲自己的律师生涯。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的生涯里有过很多次比赛。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚开始工作的那几年，是我职业生涯最难的时候。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的政治生涯在五十岁时结束了。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的校园生涯从今天开始，我有点紧张。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的生涯很辛苦，但是他很喜欢。", "target_word": "生涯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人从事某种活动或职业的经历和时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“学习生涯”指在某段时间内的学习经历和时期，“大学的学习”与之搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是一段学习的时期，与句子意思不符。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指吃饭的多少，与“学习”的时期无关，句子说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“学习”后面不能接“价格”，“学习价格”的搭配不通。"}], "explanations": {"生涯": "正确。“学习生涯”指在某段时间内的学习经历和时期，“大学的学习”与之搭配。", "体重": "语义：体重是身体的重量，不是一段学习的时期，与句子意思不符。", "饭量": "语义：饭量指吃饭的多少，与“学习”的时期无关，句子说不通。", "价格": "搭配：“学习”后面不能接“价格”，“学习价格”的搭配不通。"}, "sentence_index": 0, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末的生涯很短暂。", "explanation": "这里应该用〈时光〉。生涯指长时间从事某活动或职业的时期，用于一个周末这样的短时间不合适。"}, {"text": "他在军队的生涯只用了十分钟，就结束了训练。", "explanation": "这里应该用〈时间〉。生涯指长时间的一段时期，十分钟这样的短时间应说“时间”。"}, {"text": "他把军队的生涯装进了书包。", "explanation": "这里应该用〈照片〉。生涯是抽象的一段时期，不是可以装进书包的具体东西，应说“照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生涯", "is_correct": true, "explanation": "正确。“职业生涯”指长期从事某种职业的时期，与“最难的时候”相合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的程度，不是工作的时期，“职业学历最难的时候”说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指面部的神情，不能用来说职业阶段，句子不通。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪指年龄，不是工作的一段时期，“职业年纪最难”不符合句意。"}], "explanations": {"生涯": "正确。“职业生涯”指长期从事某种职业的时期，与“最难的时候”相合。", "学历": "语义：学历是受教育的程度，不是工作的时期，“职业学历最难的时候”说不通。", "脸色": "体貌：“脸色”指面部的神情，不能用来说职业阶段，句子不通。", "年纪": "语义：年纪指年龄，不是工作的一段时期，“职业年纪最难”不符合句意。"}, "sentence_index": 6, "correct_answer": "生涯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都给自己的生涯浇水。", "explanation": "这里应该用〈植物〉。生涯是一段时期，不能浇水，浇水的对象应是植物。"}, {"text": "这次体检只用了一个小时，却是他的医生生涯。", "explanation": "这里应该用〈经历〉。生涯指长期从事某职业的时期，一次一个小时的体检不能称为生涯，应说“经历”。"}, {"text": "他把医生的生涯打碎，扔进了垃圾桶。", "explanation": "这里应该用〈碗〉。生涯是抽象的一段时期，不能打碎、扔掉，此处应换成可以打碎的具体器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在工厂的一座生涯里，学会了很多技术。", "corrected_sentence": "他在工厂的一段生涯里，学会了很多技术。", "error_description": "量词错误：“生涯”应该用“段”，不能用“座”。“座”用于山、楼等大型固定物，“一座生涯”错误，应改为“一段生涯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的职业生涯在五十岁时结束着。", "corrected_sentence": "他的职业生涯在五十岁时结束了。", "error_description": "体标错误：“结束”表示动作已经完成，不能加“着”，应说“结束了”。错误句是“结束着”，正确句是“结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
