INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家按行政区域划分出的省一级地区的总称。", "primary_collocate": null, "pronunciation": "shěng fèn", "ipa": "ʂɤŋ˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "中国有很多省份。", "target_word": "省份", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你是哪个省份的人？", "target_word": "省份", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个省份的面积很大。", "target_word": "省份", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方省份夏天很热。", "target_word": "省份", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去过的省份不多。", "target_word": "省份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省份的人口超过了五千万。", "target_word": "省份", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的省份冬天很冷，要穿厚衣服。", "target_word": "省份", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上用不同的颜色表示不同的省份。", "target_word": "省份", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条铁路从东到西经过了五个省份。", "target_word": "省份", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑自行车走遍了南方的好几个省份。", "target_word": "省份", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "行政区划中省一级地区的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省份", "is_correct": true, "explanation": "正确答案：国家按行政区域划分出的省一级地区。"}, {"text": "身份", "is_correct": false, "explanation": "shēn（第一声）与 shěng（第三声）韵母不同（-ēn 与 -ěng），声调也不同，意思是人的身份、地位。"}, {"text": "整份", "is_correct": false, "explanation": "zhěng 与 shěng 声母不同（zh 与 sh），声调相同，意思是整个的一份。"}, {"text": "生分", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声母韵母相同，只有声调不同；意思是疏远、不亲近。"}, {"text": "成分", "is_correct": false, "explanation": "chéng 与 shěng 声母不同（ch 与 sh），声调也不同，意思是组成的部分。"}, {"text": "生粉", "is_correct": false, "explanation": "shēng 与 shěng、fěn 与 fèn 声调都不同，意思是生淀粉。"}], "explanations": {"省份": "正确答案：国家按行政区域划分出的省一级地区。", "身份": "shēn（第一声）与 shěng（第三声）韵母不同（-ēn 与 -ěng），声调也不同，意思是人的身份、地位。", "整份": "zhěng 与 shěng 声母不同（zh 与 sh），声调相同，意思是整个的一份。", "生分": "shēng（第一声）与 shěng（第三声）声母韵母相同，只有声调不同；意思是疏远、不亲近。", "成分": "chéng 与 shěng 声母不同（ch 与 sh），声调也不同，意思是组成的部分。", "生粉": "shēng 与 shěng、fěn 与 fèn 声调都不同，意思是生淀粉。"}, "sentence_index": null, "correct_answer": "省份"}, "level_3": {"options": [{"text": "省份", "is_correct": true, "explanation": "正确：“中国有很多省份”，省份是国家下属的行政区。"}, {"text": "行星", "is_correct": false, "explanation": "语义：行星不属于某个国家，“中国有很多行星”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是器官，不能说国家“有很多眼睛”。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间单位，不能用“很多”来计量一个国家的组成部分。"}], "explanations": {"省份": "正确：“中国有很多省份”，省份是国家下属的行政区。", "行星": "语义：行星不属于某个国家，“中国有很多行星”说不通。", "眼睛": "语义：眼睛是器官，不能说国家“有很多眼睛”。", "星期": "搭配：“星期”是时间单位，不能用“很多”来计量一个国家的组成部分。"}, "sentence_index": 0, "correct_answer": "省份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国是一个大省份。", "explanation": "这里应该用〈国家〉。省份是国家之内划分出的行政区，中国整体是国家，不能称为省份。"}, {"text": "欧洲是一个大省份。", "explanation": "这里应该用〈大洲〉。省份指一国之内的省一级地区，欧洲是洲，不能说成省份。"}, {"text": "这只省份的面积很大。", "explanation": "这里应该用〈个〉。省份用“个”计量，“只”多用于动物，不能修饰省份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省份", "is_correct": true, "explanation": "正确：“北方的省份冬天很冷”，北方各省冬天寒冷，所以要穿厚衣服。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流工具，不是地区，句子说的是北方的气候。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是地区，“北方的音乐冬天很冷”说不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是表示数量的符号，不是地区，“北方的数字冬天很冷”说不通。"}], "explanations": {"省份": "正确：“北方的省份冬天很冷”，北方各省冬天寒冷，所以要穿厚衣服。", "语言": "语义：语言是交流工具，不是地区，句子说的是北方的气候。", "音乐": "语义：音乐不是地区，“北方的音乐冬天很冷”说不通。", "数字": "语义：数字是表示数量的符号，不是地区，“北方的数字冬天很冷”说不通。"}, "sentence_index": 6, "correct_answer": "省份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑自行车走遍了南方的好几条省份。", "explanation": "这里应该用〈个〉。“条”多用于河流、道路等长形事物，省份要用“个”计量。"}, {"text": "他骑自行车走遍了南方的好几块省份。", "explanation": "这里应该用〈个〉。“块”多用于块状物或小片土地，省份是较大的行政区，要用“个”计量。"}, {"text": "他骑自行车走遍了南方的好几片省份。", "explanation": "这里应该用〈个〉。“片”多用于森林、水域、草地等，不能用来计量省份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他来自一条很远的省份。", "corrected_sentence": "他来自一个很远的省份。", "error_description": "量词错误：“省份”应该用“个”计量，不能用“条”（“条”多用于河流、道路等长形事物）。正确说法：“他来自一个很远的省份。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去过很多只省份。", "corrected_sentence": "他去过很多个省份。", "error_description": "量词错误：“省份”应该用“个”计量，“只”用于动物等，不能说“很多只省份”。正确说法：“他去过很多个省份。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
