INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "随自己的意愿行事，不加拘束。", "primary_collocate": null, "pronunciation": "zì biàn", "ipa": "tsɨ˥˩ piɛn˥˩", "syllable_count": 2, "sentences": [{"text": "去留自便，我们不勉强你。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加不参加，你自便。", "target_word": "自便", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会后大家可以自由活动，去哪儿自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有规定，穿什么衣服都自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说我们走不走自便，他不管。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说，周末加不加班自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家来去自便，不用跟主人打招呼。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课不能自便，要听老师的话。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店没有规矩，进店后怎么看、怎么选都自便。", "target_word": "自便", "complexity_tier": "T3", "furigana": "zhè jiā diàn méi yǒu guī ju jìn diàn hòu zěn me kàn zěn me xuǎn dōu zì biàn", "sentence_source": "generated"}, {"text": "晚会很随意，吃饭喝茶都由客人自便。", "target_word": "自便", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按自己的意愿行事，不受约束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。"}, {"text": "自编", "is_correct": false, "explanation": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。"}, {"text": "自贬", "is_correct": false, "explanation": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。"}, {"text": "字面", "is_correct": false, "explanation": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。"}, {"text": "自限", "is_correct": false, "explanation": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}], "explanations": {"自便": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。", "自编": "自编（zì biān）与自便（zì biàn）声调不同，意思是自己编写。", "自贬": "自贬（zì biǎn）与自便（zì biàn）声调不同，意思是自我贬低。", "字面": "字面（zì miàn）与自便（zì biàn）声母不同（m 与 b），意思是文字的表面意思。", "自限": "自限（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自我限制。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示按自己的意愿行事，用在“去留自便”中，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”后要接议题作宾语，“去留讨论”搭配不当，句子不通。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指游泳或游玩，与“去留”的决定无关，句子语义不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“去留”毫不相干，句子语义不通。"}], "explanations": {"自便": "“自便”是动词，表示按自己的意愿行事，用在“去留自便”中，符合句意。", "讨论": "搭配：“讨论”后要接议题作宾语，“去留讨论”搭配不当，句子不通。", "游": "语义：“游”指游泳或游玩，与“去留”的决定无关，句子语义不通。", "睡": "语义：“睡”与“去留”毫不相干，句子语义不通。"}, "sentence_index": 0, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里没有规定，穿衣服很自便。", "explanation": "这里应该用〈自由〉。“自由”可形容穿着不受限；“自便”是动词，不能用“很”修饰“穿衣服”。"}, {"text": "这里没有规定，他的衣服颜色自便。", "explanation": "这里应该用〈随意〉。“随意”可修饰事物；“自便”是动词，不能作谓语描写颜色。"}, {"text": "这里很自便，穿什么衣服都行。", "explanation": "这里应该用〈方便〉。“方便”可形容环境便利；“自便”指按自己意愿行事，不形容地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自便", "is_correct": true, "explanation": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。"}, {"text": "自建", "is_correct": false, "explanation": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。"}, {"text": "自陷", "is_correct": false, "explanation": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。"}, {"text": "自炼", "is_correct": false, "explanation": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}], "explanations": {"自便": "自便（zì biàn）意思是按自己的意愿行事，不受约束，是正确答案。", "自建": "自建（zì jiàn）与自便（zì biàn）声母不同（j 与 b），意思是自己建造。", "自陷": "自陷（zì xiàn）与自便（zì biàn）声母不同（x 与 b），意思是自己陷入。", "自炼": "自炼（zì liàn）与自便（zì biàn）声母不同（l 与 b），意思是自我修炼。"}, "sentence_index": null, "correct_answer": "自便"}, "level_3": {"options": [{"text": "自便", "is_correct": true, "explanation": "“自便”是动词，表示按自己的意愿行事，用在“来去自便”中，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示伤心流泪，与“来去”的自由出入不符，句子语义不通。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”表示喧闹，与“不用打招呼”的语境不合，句子语义不通。"}, {"text": "喊", "is_correct": false, "explanation": "搭配：“喊”一般要接声音内容或对象，“来去喊”搭配不当。"}], "explanations": {"自便": "“自便”是动词，表示按自己的意愿行事，用在“来去自便”中，符合句意。", "哭": "语义：“哭”表示伤心流泪，与“来去”的自由出入不符，句子语义不通。", "吵": "语义：“吵”表示喧闹，与“不用打招呼”的语境不合，句子语义不通。", "喊": "搭配：“喊”一般要接声音内容或对象，“来去喊”搭配不当。"}, "sentence_index": 6, "correct_answer": "自便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会很随意，客人的自便很多。", "explanation": "这里应该用〈自由〉。“自由”可作名词，“自便”是动词，不能用“的”组成名词词组。"}, {"text": "晚会很随意，客人走动很自便。", "explanation": "这里应该用〈自在〉。“自在”可形容行动舒适；“自便”指按自己意愿行事，不能这样形容走动。"}, {"text": "晚会很随意，大家聊天很自便。", "explanation": "这里应该用〈随便〉。“随便聊天”是常见说法；“自便”不用来形容聊天的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次聚会去不去，你自便了吧。", "corrected_sentence": "这次聚会去不去，你自便吧。", "error_description": "“自便”用于请对方随意的说法，句中不能加“了”，应说“你自便吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进了房间，你们尽管自便过。", "corrected_sentence": "进了房间，你们尽管自便。", "error_description": "“自便”后不能加“过”，应说“你们尽管自便”；“过”表示经历，与请对方随意的语境不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "艺人是会唱歌、跳舞或表演的人，靠这个工作。", "primary_collocate": null, "pronunciation": "yì rén", "ipa": "i˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这位艺人会唱歌，也会跳舞。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个艺人每天都要练习唱歌。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺人上台以前，先化了妆。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人想当艺人，因为可以上电视。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺人唱歌很好听，粉丝都喜欢他。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺人的工作很忙，常常要去别的城市表演。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个有名的艺人，在街上总有人找她拍照。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司帮艺人安排演出和拍广告。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是学生，是靠表演赚钱的艺人。", "target_word": "艺人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友是艺人，上个月刚在北京开了演唱会。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "街头艺人", "label": "复合"}, {"form": "藝人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠唱歌、跳舞或表演为职业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：会唱歌、跳舞或表演、靠这个工作的人。"}, {"text": "一人", "is_correct": false, "explanation": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。"}, {"text": "宜人", "is_correct": false, "explanation": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。"}, {"text": "怡人", "is_correct": false, "explanation": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}], "explanations": {"艺人": "艺人：会唱歌、跳舞或表演、靠这个工作的人。", "一人": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。", "宜人": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。", "怡人": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}, "sentence_index": null, "correct_answer": "艺人"}, "level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：会唱歌、会跳舞，靠表演为生，符合句中的描述。"}, {"text": "石像", "is_correct": false, "explanation": "语义：石像不会唱歌跳舞，与句意矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会唱歌跳舞，与后半句矛盾。"}, {"text": "植物人", "is_correct": false, "explanation": "语义：植物人无法唱歌跳舞，与后半句矛盾。"}], "explanations": {"艺人": "艺人：会唱歌、会跳舞，靠表演为生，符合句中的描述。", "石像": "语义：石像不会唱歌跳舞，与句意矛盾。", "婴儿": "语义：婴儿不会唱歌跳舞，与后半句矛盾。", "植物人": "语义：植物人无法唱歌跳舞，与后半句矛盾。"}, "sentence_index": 0, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的艺人，每天都在写小说。", "explanation": "这里应该用〈作家〉。艺人指从事表演艺术的人，写小说的人要说作家。"}, {"text": "我的妈妈是一位艺人，在小学教数学。", "explanation": "这里应该用〈老师〉。艺人指靠表演工作的人，教书的人要说老师。"}, {"text": "我的叔叔是一位艺人，每天在家里画画。", "explanation": "这里应该用〈画家〉。艺人指靠唱歌、跳舞或表演工作的人，靠画画为生的要说画家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：有名、会表演的人，常有人找他拍照，符合句意。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人并不以出名著称，与“有名”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不会因出名而被人找去拍照，与句意矛盾。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“陌生人”与“有名”不能搭配，前后矛盾。"}], "explanations": {"艺人": "艺人：有名、会表演的人，常有人找他拍照，符合句意。", "路人": "语义：路人并不以出名著称，与“有名”矛盾。", "病人": "语义：病人不会因出名而被人找去拍照，与句意矛盾。", "陌生人": "搭配：“陌生人”与“有名”不能搭配，前后矛盾。"}, "sentence_index": 6, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位艺人每天早上五点起来跑步训练。", "explanation": "这里应该用〈运动员〉。艺人指从事表演艺术的人，参加比赛训练的人要说运动员。"}, {"text": "这家饭店的艺人做的面条很好吃。", "explanation": "这里应该用〈厨师〉。艺人指表演艺术的人，做饭的人要说厨师。"}, {"text": "我爸爸是一位艺人，每天开车送我上学。", "explanation": "这里应该用〈司机〉。艺人指表演艺术的人，开车载人的要说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们是两只艺人，经常一起参加节目。", "corrected_sentence": "他们是两位艺人，经常一起参加节目。", "error_description": "量词错误：“艺人”指人，量词应用“位”或“个”，不能用“只”。正确说法是“两位艺人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市里有一个很有名艺人，常常在电视上唱歌。", "corrected_sentence": "这个城市里有一个很有名的艺人，常常在电视上唱歌。", "error_description": "修饰语漏“的”：“很有名”修饰“艺人”时要加“的”，应说“很有名的艺人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
