INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事表演艺术的人，如歌手、演员、曲艺演员等。", "primary_collocate": null, "pronunciation": "yì rén", "ipa": "i˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他在茶馆里说了一辈子相声，是一位艺人。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "广场上有一位艺人在唱歌，很多人停下来听。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "这位艺人把传统故事唱给孩子们听。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "他是一位艺人，从小就在剧团学表演。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "那位艺人说得很有意思，台下笑声不断。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "这个城市有很多艺人，他们在剧院里演出。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺人都要多练习，才能上大舞台。", "target_word": "艺人", "complexity_tier": "T3", "furigana": "yì rén", "sentence_source": "generated"}, {"text": "过年的时候，村里请来了几位艺人唱戏。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺人演过电影，也唱过很多歌。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺人要在台上表演，台下的练习更重要。", "target_word": "艺人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "民间艺人", "label": "复合"}, {"form": "藝人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事表演艺术的人，包括歌手、演员、曲艺演员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：从事表演艺术的人，如歌手、演员、曲艺演员。"}, {"text": "一人", "is_correct": false, "explanation": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。"}, {"text": "宜人", "is_correct": false, "explanation": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。"}, {"text": "怡人", "is_correct": false, "explanation": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}], "explanations": {"艺人": "艺人：从事表演艺术的人，如歌手、演员、曲艺演员。", "一人": "一人（yī，第一声）与艺人（yì，第四声）第一个音节声调不同，意思是一个人。", "宜人": "宜人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是让人感到舒服。", "怡人": "怡人（yí，第二声）与艺人（yì，第四声）第一个音节声调不同，意思是令人愉快，多用于景色。"}, "sentence_index": null, "correct_answer": "艺人"}, "level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：从事表演艺术的人，说相声的人属于这一类，符合句意。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家不说相声，与“说了一辈子相声”矛盾。"}, {"text": "医生", "is_correct": false, "explanation": "搭配：“说相声”是表演者的职业活动，不能和“医生”搭配。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“一辈子”说相声的人不会是学生，与句意矛盾。"}], "explanations": {"艺人": "艺人：从事表演艺术的人，说相声的人属于这一类，符合句意。", "作家": "语义：作家不说相声，与“说了一辈子相声”矛盾。", "医生": "搭配：“说相声”是表演者的职业活动，不能和“医生”搭配。", "学生": "语义：“一辈子”说相声的人不会是学生，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位优秀的艺人，从小就在体校学习训练。", "explanation": "这里应该用〈运动员〉。艺人指从事表演艺术的人，在体校接受训练的人要说运动员。"}, {"text": "他是一位艺人，从小就在实验室做研究。", "explanation": "这里应该用〈科学家〉。艺人指表演艺术的人，做研究的人要说科学家。"}, {"text": "妈妈是一名艺人，每天在医院照顾病人。", "explanation": "这里应该用〈护士〉。艺人指表演艺术的人，在医院照顾病人的要说护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艺人", "is_correct": true, "explanation": "艺人：从事表演艺术的人，要多练习才能上大舞台，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不需要为上大舞台而练习，与句意不合。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不需要为上大舞台而练习，与句意不合。"}, {"text": "保安", "is_correct": false, "explanation": "语义：保安的工作与为上大舞台而练习无关，与句意不合。"}], "explanations": {"艺人": "艺人：从事表演艺术的人，要多练习才能上大舞台，符合句意。", "乘客": "语义：乘客不需要为上大舞台而练习，与句意不合。", "病人": "语义：病人不需要为上大舞台而练习，与句意不合。", "保安": "语义：保安的工作与为上大舞台而练习无关，与句意不合。"}, "sentence_index": 6, "correct_answer": "艺人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位艺人在法庭上为客户说话，很有经验。", "explanation": "这里应该用〈律师〉。艺人指表演艺术的人，在法庭上为客户辩护的要说律师。"}, {"text": "他是一位艺人，每天早起去地里干活。", "explanation": "这里应该用〈农民〉。艺人指表演艺术的人，在地里干活的要说农民。"}, {"text": "我姐姐是艺人，每个月都要核对账目。", "explanation": "这里应该用〈会计〉。艺人指表演艺术的人，核对账目的要说会计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边有一只艺人在拉二胡，很多人围过来看。", "corrected_sentence": "路边有一位艺人在拉二胡，很多人围过来看。", "error_description": "量词错误：“艺人”指人，应该用“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视台请来了一位很红艺人做节目。", "corrected_sentence": "电视台请来了一位很红的艺人做节目。", "error_description": "修饰语漏“的”：“很红”修饰“艺人”时要加“的”，应说“很红的艺人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
