INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "裤子是穿在腿上的衣服。有两个裤腿。", "primary_collocate": null, "pronunciation": "kù zi", "ipa": "kʰu˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "我今天穿了一条黑色的裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子太长了，要剪短一点。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子上有一块红色的东西。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我喜欢穿厚裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一条新裤子。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小弟弟把裤子弄湿了。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子的两个裤腿不一样长。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗好的裤子挂在阳台上。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的裤子太大，要用皮带。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你要穿裤子，别穿短裙。", "target_word": "裤子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "褲子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "穿在腿上、有两个裤腿的衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1881d9c-7008-468f-b42e-60222934a602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 kù（第四声）声母不同（t 与 k），意思是兔子。"}, {"text": "肚子", "is_correct": false, "explanation": "dù（第四声）与 kù（第四声）声母不同（d 与 k），意思是肚子。"}, {"text": "句子", "is_correct": false, "explanation": "jù（第四声）与 kù（第四声）声母不同（j 与 k），意思是句子。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 kù（第四声）声母不同（l 与 k），意思是门路。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。"}], "explanations": {"裤子": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。", "兔子": "tù（第四声）与 kù（第四声）声母不同（t 与 k），意思是兔子。", "肚子": "dù（第四声）与 kù（第四声）声母不同（d 与 k），意思是肚子。", "句子": "jù（第四声）与 kù（第四声）声母不同（j 与 k），意思是句子。", "路子": "lù（第四声）与 kù（第四声）声母不同（l 与 k），意思是门路。", "铺子": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。"}, "sentence_index": null, "correct_answer": "裤子"}, "level_3": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在身上的衣服，量词用“条”，与“穿”和“黑色的”搭配。"}, {"text": "帽子", "is_correct": false, "explanation": "搭配：帽子要说“戴”，量词用“顶”，不能说“穿了一条黑色的帽子”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是背在身上的，不是穿在身上的东西，句中“穿了”说不通。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：手套要说“戴”，量词用“双”，不能说“穿了一条”。"}], "explanations": {"裤子": "正确答案。裤子是穿在身上的衣服，量词用“条”，与“穿”和“黑色的”搭配。", "帽子": "搭配：帽子要说“戴”，量词用“顶”，不能说“穿了一条黑色的帽子”。", "书包": "语义：书包是背在身上的，不是穿在身上的东西，句中“穿了”说不通。", "手套": "搭配：手套要说“戴”，量词用“双”，不能说“穿了一条”。"}, "sentence_index": 0, "correct_answer": "裤子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只裤子。", "explanation": "这里应该用〈条〉。裤子用量词“条”，“只”用于动物或成对器官中的一个，不用于裤子。"}, {"text": "我买了一根裤子。", "explanation": "这里应该用〈条〉。“根”用于绳子等细长的东西，裤子用量词“条”。"}, {"text": "我买了一双裤子。", "explanation": "这里应该用〈条〉。“双”用于成对的鞋袜等，裤子用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。"}, {"text": "锯子", "is_correct": false, "explanation": "jù（第四声）与 kù（第四声）声母不同（j 与 k），意思是锯子。"}, {"text": "扣子", "is_correct": false, "explanation": "kòu（第四声）与 kù（第四声）韵母不同（ou 与 u），意思是扣子。"}, {"text": "酷似", "is_correct": false, "explanation": "kù sì 与 kù zi 的第二个音节声母和声调都不同（s 与 z），意思是非常像。"}], "explanations": {"裤子": "正确答案。裤子是穿在腿上、有两个裤腿的衣服。", "铺子": "pù（第四声）与 kù（第四声）声母不同（p 与 k），意思是铺子。", "锯子": "jù（第四声）与 kù（第四声）声母不同（j 与 k），意思是锯子。", "扣子": "kòu（第四声）与 kù（第四声）韵母不同（ou 与 u），意思是扣子。", "酷似": "kù sì 与 kù zi 的第二个音节声母和声调都不同（s 与 z），意思是非常像。"}, "sentence_index": null, "correct_answer": "裤子"}, "level_3": {"options": [{"text": "裤子", "is_correct": true, "explanation": "正确答案。裤子有两个裤腿，量词用“条”，与“这条”搭配。"}, {"text": "上衣", "is_correct": false, "explanation": "搭配：上衣的量词是“件”，不说“这条上衣”；而且上衣没有裤腿。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：裙子没有裤腿，与“两个裤腿不一样长”的描述矛盾。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是穿的东西，也没有裤腿，句子说不通。"}], "explanations": {"裤子": "正确答案。裤子有两个裤腿，量词用“条”，与“这条”搭配。", "上衣": "搭配：上衣的量词是“件”，不说“这条上衣”；而且上衣没有裤腿。", "裙子": "语义：裙子没有裤腿，与“两个裤腿不一样长”的描述矛盾。", "窗帘": "语义：窗帘不是穿的东西，也没有裤腿，句子说不通。"}, "sentence_index": 6, "correct_answer": "裤子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一块裤子。", "explanation": "这里应该用〈条〉。“块”用于块状或片状的东西，裤子用量词“条”。"}, {"text": "我买了一枚裤子。", "explanation": "这里应该用〈条〉。“枚”用于硬币、徽章等小件的东西，裤子用量词“条”。"}, {"text": "我买了一支裤子。", "explanation": "这里应该用〈条〉。“支”用于笔、枪等细长的东西，裤子用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天穿了一只蓝色的裤子。", "corrected_sentence": "我昨天穿了一条蓝色的裤子。", "error_description": "量词错误：裤子应用量词“条”，“只”用于动物或成对器官中的一个，不能修饰裤子。正确的说法是“一条蓝色的裤子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把她的裤子们都洗干净了。", "corrected_sentence": "妹妹把她的裤子都洗干净了。", "error_description": "词尾错误：“们”只用于指人的名词，不能加在“裤子”后面。正确的说法是“她的裤子都洗干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "参加", "is_correct": false, "explanation": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "参加": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。", "讨论": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。", "旅行": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}, {"text": "决定", "is_correct": false, "explanation": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "研究": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。", "观察": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。", "决定": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赞同是别人说的话，你觉得对，也这样想。", "primary_collocate": null, "pronunciation": "zàn tóng", "ipa": "tsan˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我赞同你的看法，我们就这样办吧。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都赞同他的意见，没有人反对。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得很对，我完全赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法我不太赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈赞同我去北京学习。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我赞同小王的说法，这样做更省钱。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说要早点出发，我很赞同。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人赞同这个计划。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不赞同我一个人去旅行。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话我赞同，天气不好就别出门了。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞同了", "label": "体标"}, {"form": "赞同过", "label": "体标"}, {"form": "贊同", "label": "繁体"}], "register": "中性", "sense_fingerprint": "听了别人的话，觉得对，自己也这样想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示认为对而同意，与后文“就这样办吧”一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与后文“就这样办吧”的同意语气相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指出问题，与“就这样办吧”的认可相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用于“看法”。"}], "explanations": {"赞同": "正确：“赞同”表示认为对而同意，与后文“就这样办吧”一致。", "反对": "语义：“反对”与后文“就这样办吧”的同意语气相反。", "批评": "语义：“批评”指出问题，与“就这样办吧”的认可相矛盾。", "参观": "搭配：“参观”的对象是场所或展览，不能用于“看法”。"}, "sentence_index": 0, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很赞同这幅画的色彩。", "explanation": "这里应该用〈欣赏〉。赞同用于意见、做法或计划，评价画的色彩要用欣赏。"}, {"text": "这次演讲太精彩了，我很赞同他的口才。", "explanation": "这里应该用〈称赞〉。赞同针对意见或做法，夸奖别人的口才要用称赞。"}, {"text": "我很赞同你的帮助。", "explanation": "这里应该用〈感激〉。赞同是对意见的态度，对别人的帮助表示谢意要用感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示同意对方的说法，与“你说要早点出发”相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”是想念过去的人或事，与现在讨论早点出发的语境不符。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”多用于别人的好意或感人的事，与“早点出发”的安排不搭。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”需要说出被嘲笑的对象，“很嘲笑”不能这样用。"}], "explanations": {"赞同": "正确：“赞同”表示同意对方的说法，与“你说要早点出发”相符。", "怀念": "语义：“怀念”是想念过去的人或事，与现在讨论早点出发的语境不符。", "感动": "语义：“感动”多用于别人的好意或感人的事，与“早点出发”的安排不搭。", "嘲笑": "搭配：“嘲笑”需要说出被嘲笑的对象，“很嘲笑”不能这样用。"}, "sentence_index": 6, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于赞同了自己的错误。", "explanation": "这里应该用〈承认〉。赞同是对别人的意见表示同意，承认自己的错误要用承认。"}, {"text": "我很赞同他的遭遇。", "explanation": "这里应该用〈同情〉。赞同针对意见或做法，对别人的不幸表示关切要用同情。"}, {"text": "我很赞同那段日子。", "explanation": "这里应该用〈怀念〉。赞同不能用于时间或经历，回想过去的时光要用怀念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不地赞同这个做法，咱们再想想。", "corrected_sentence": "我不赞同这个做法，咱们再想想。", "error_description": "错误：“不”与“赞同”之间多了助词“地”，“不地赞同”不成立。正确：“我不赞同这个做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很地赞同你的安排，我们就这么定。", "corrected_sentence": "我很赞同你的安排，我们就这么定。", "error_description": "错误：“很地赞同”。正确：“很赞同”。“很”作状语修饰动词时直接放在动词前，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "参加", "is_correct": false, "explanation": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "参加": "无反义关系：“参加”指加入某项活动，与“赞同”的意思无关。", "旅行": "无反义关系：“旅行”指出外游览，与表示同意的“赞同”没有对立关系。", "观察": "无反义关系：“观察”指仔细看，与表示同意的“赞同”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：“反对”与“赞同”意思相反，表示不同意。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。"}, {"text": "决定", "is_correct": false, "explanation": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}], "correct_answer": "反对", "explanations": {"反对": "正确：“反对”与“赞同”意思相反，表示不同意。", "研究": "无反义关系：“研究”指深入探讨问题，与“赞同”的态度无对立关系。", "讨论": "无反义关系：“讨论”指共同交流意见，并不表示相反的态度。", "决定": "无反义关系：“决定”指做出选择，与“赞同”的意思无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为对而表示同意。", "primary_collocate": null, "pronunciation": "zàn tóng", "ipa": "tsan˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "经理赞同这个计划，让我们马上开始。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赞同我们的做法，还给了很多帮助。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板赞同了我的建议。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师赞同他每天跑步的做法。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，大家一致赞同这个决定。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人都赞同我换工作。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点点头，赞同了我的想法。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生赞同病人多休息。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人赞同把会议改到周末。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长赞同学生办一个读书会。", "target_word": "赞同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赞同了", "label": "体标"}, {"form": "赞同过", "label": "体标"}, {"form": "贊同", "label": "繁体"}], "register": "中性", "sense_fingerprint": "认为对，并明确表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示认为对而同意，与后文“让我们马上开始”一致。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与后文“让我们马上开始”的认可相反。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“让我们马上开始”的态度相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用于“计划”。"}], "explanations": {"赞同": "正确：“赞同”表示认为对而同意，与后文“让我们马上开始”一致。", "拒绝": "语义：“拒绝”表示不接受，与后文“让我们马上开始”的认可相反。", "反对": "语义：“反对”表示不同意，与“让我们马上开始”的态度相矛盾。", "参观": "搭配：“参观”的对象是场所或展览，不能用于“计划”。"}, "sentence_index": 0, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很赞同老师的鼓励。", "explanation": "这里应该用〈感谢〉。赞同是对意见或做法的态度，对别人的鼓励表示谢意要用感谢。"}, {"text": "我很赞同他的勇气。", "explanation": "这里应该用〈佩服〉。赞同针对意见或做法，欣赏别人的品质要用佩服。"}, {"text": "我很赞同那个迷路的孩子。", "explanation": "这里应该用〈同情〉。赞同不用于指人，对迷路的孩子表示怜惜要用同情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞同", "is_correct": true, "explanation": "正确：“赞同”表示同意对方的想法，与“点点头”的态度一致。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：“反驳”是提出不同意见，与“点点头”表示认同的动作相矛盾。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指否定原来的观点，与“点点头”的认同态度不符。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是景点或地方，不能用于“想法”。"}], "explanations": {"赞同": "正确：“赞同”表示同意对方的想法，与“点点头”的态度一致。", "反驳": "语义：“反驳”是提出不同意见，与“点点头”表示认同的动作相矛盾。", "推翻": "语义：“推翻”指否定原来的观点，与“点点头”的认同态度不符。", "游览": "搭配：“游览”的对象是景点或地方，不能用于“想法”。"}, "sentence_index": 6, "correct_answer": "赞同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赞同了自己的失误。", "explanation": "这里应该用〈承认〉。赞同是对别人的意见表示同意，承认自己做错要用承认。"}, {"text": "我很赞同那段大学时光。", "explanation": "这里应该用〈怀念〉。赞同不用于时间或经历，回想过去的时光要用怀念。"}, {"text": "我很赞同这首歌的旋律。", "explanation": "这里应该用〈欣赏〉。赞同针对意见或做法，评价音乐的美感要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不地赞同这个提议，咱们再商量一下。", "corrected_sentence": "我不赞同这个提议，咱们再商量一下。", "error_description": "错误：“不”与“赞同”之间多了助词“地”，“不地赞同”不成立。正确：“我不赞同这个提议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很赞同的你的建议，咱们就这么定。", "corrected_sentence": "我很赞同你的建议，咱们就这么定。", "error_description": "错误：“你的建议”前已有定语“你的”，“赞同”后再加“的”引出修饰语，结构重复。正确：“我很赞同你的建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
