INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "送去是把东西拿到别的地方，交给别人。", "primary_collocate": null, "pronunciation": "sòng qù", "ipa": "sʊŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "我要把这封信送去给王老师。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把礼物送去给她。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把早饭送去给奶奶。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把作业送去办公室，交给老师。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天给邻居送去一份报纸。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了饺子，让我送去给舅舅。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份文件送去给经理。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把样品送去给客户看。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把新买的水果送去给朋友。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把药送去给生病的同学。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送去了", "label": "体标"}, {"form": "送去过", "label": "体标"}, {"form": "送過去", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西拿到别处，交给某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送去", "is_correct": true, "explanation": "正确：“送去给”表示把东西送去交给别人，与“我要把这封信送去给王老师”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指出售，与把信交给老师的语境不符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物吃东西，不能用于信件。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，与把信交给老师的语境不符。"}], "explanations": {"送去": "正确：“送去给”表示把东西送去交给别人，与“我要把这封信送去给王老师”相符。", "卖": "语义：“卖”指出售，与把信交给老师的语境不符。", "喂": "语义：“喂”指给人或动物吃东西，不能用于信件。", "烧": "语义：“烧”指燃烧，与把信交给老师的语境不符。"}, "sentence_index": 0, "correct_answer": "送去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把会议送去了下周。", "explanation": "这里应该用〈推迟〉。送去表示把东西送往某地，会议时间往后挪要用推迟。"}, {"text": "他把作业送去了明天。", "explanation": "这里应该用〈拖〉。送去表示送往某地，把作业拖到以后要用拖。"}, {"text": "我想把假期送去下个月。", "explanation": "这里应该用〈延长〉。送去表示送往某地，假期时间变长要用延长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送去", "is_correct": true, "explanation": "正确：“送去给”表示把文件送去交给别人，与“请把这份文件送去给经理”相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指撕毁，与把文件交给经理的意思相反。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指重击，与递交文件的语境不符。"}, {"text": "摇", "is_correct": false, "explanation": "搭配：“摇”指晃动物体，不能用于“文件”。"}], "explanations": {"送去": "正确：“送去给”表示把文件送去交给别人，与“请把这份文件送去给经理”相符。", "撕": "语义：“撕”指撕毁，与把文件交给经理的意思相反。", "砸": "语义：“砸”指重击，与递交文件的语境不符。", "摇": "搭配：“摇”指晃动物体，不能用于“文件”。"}, "sentence_index": 6, "correct_answer": "送去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一下午都送去了游戏上。", "explanation": "这里应该用〈浪费〉。送去表示把东西送往某地，把时间白白耗掉要用浪费。"}, {"text": "这场大雨送去了我的行程。", "explanation": "这里应该用〈耽误〉。送去表示送往某地，天气妨碍行程要用耽误。"}, {"text": "我们把开支送去了一半。", "explanation": "这里应该用〈减少〉。送去表示送往某地，开支数量变少要用减少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把报告送去给经理过。", "corrected_sentence": "我把报告送去给经理了。", "error_description": "错误：“过”表示经历，须紧跟动词（如“送去过”），不能放在宾语之后的句尾；这里是已完成的动作，应用“了”。正确：“我把报告送去给经理了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把礼物送去到给她了。", "corrected_sentence": "我把礼物送去给她了。", "error_description": "“送去给”是一个整体，中间不能再插入“到”。“送去到给她”是错误的，应去掉“到”，正确说法是“我把礼物送去给她了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
