INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西或人送到某个地方。", "primary_collocate": null, "pronunciation": "sòng qù", "ipa": "sʊŋ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈把我送去学校。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把生病的孩子送去医院。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我把书送去你家。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员把包裹送去了公司。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天开车把弟弟送去幼儿园。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些花送去会议室。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把客人送去了机场。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把受伤的学生送去医务室。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把行李送去车站。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把我们送去了火车站。", "target_word": "送去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送去了", "label": "体标"}, {"form": "送去过", "label": "体标"}, {"form": "送過去", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西或人带着送往别处的某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de134b45-02e9-4145-ab12-a355fbb69fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送去", "is_correct": true, "explanation": "正确：“送去”表示把人送往某个地方，与“妈妈把我送去学校”的意思相符。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”指自己逃走，与妈妈主动把我送去学校的意思相反。"}, {"text": "离开", "is_correct": false, "explanation": "配价：“离开”是不及物动词，不能用“把”带人作宾语，不能说“把我离开学校”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与妈妈送我去学校的语境不符。"}], "explanations": {"送去": "正确：“送去”表示把人送往某个地方，与“妈妈把我送去学校”的意思相符。", "逃离": "语义：“逃离”指自己逃走，与妈妈主动把我送去学校的意思相反。", "离开": "配价：“离开”是不及物动词，不能用“把”带人作宾语，不能说“把我离开学校”。", "扔": "语义：“扔”指丢弃，与妈妈送我去学校的语境不符。"}, "sentence_index": 0, "correct_answer": "送去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把旧衣服送去了垃圾桶。", "explanation": "这里应该用〈扔〉。送去表示把东西送到需要的人或地方，丢弃垃圾要用扔。"}, {"text": "他把钥匙送去了河里。", "explanation": "这里应该用〈丢〉。送去表示送到某处供人使用，失手掉进河里要用丢。"}, {"text": "他把钱送去了床底下。", "explanation": "这里应该用〈藏〉。送去表示送给别人或送往某处，把东西藏起来要用藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送去", "is_correct": true, "explanation": "正确：“送去”表示把人送往某地，与“我们把客人送去了机场”的意思相符。"}, {"text": "押", "is_correct": false, "explanation": "语义：“押”指押送或拘押，用于客人不合适，与待客的语境不符。"}, {"text": "摆", "is_correct": false, "explanation": "搭配：“摆”指放置物品，不能用于“客人”。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”用于搬运物品，不能用于人。"}], "explanations": {"送去": "正确：“送去”表示把人送往某地，与“我们把客人送去了机场”的意思相符。", "押": "语义：“押”指押送或拘押，用于客人不合适，与待客的语境不符。", "摆": "搭配：“摆”指放置物品，不能用于“客人”。", "搬": "搭配：“搬”用于搬运物品，不能用于人。"}, "sentence_index": 6, "correct_answer": "送去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把我送去了家。", "explanation": "这里应该用〈送回〉。送去表示送往别处，把人送回原来的地方要用送回。"}, {"text": "他把狗送去了笼子。", "explanation": "这里应该用〈关〉。送去表示送给别人或送往某处，把动物关起来要用关。"}, {"text": "他把书送去了书架。", "explanation": "这里应该用〈放回〉。送去表示把东西送给别人或送往某处，把书放回原处要用放回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午把资料送去到办公室。", "corrected_sentence": "我下午把资料送去办公室。", "error_description": "“送去”后面不能再接“到”。“送去”已表示送往某处，再加“到”就重复了。正确说法是“送去办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把行李送去了在酒店。", "corrected_sentence": "我们把行李送去了酒店。", "error_description": "“送去”后面直接接地点，中间不能加“在”。“送去了在酒店”是错误的，正确说法是“送去了酒店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f9868f-5139-4fce-a8c8-1603e2efa503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
