INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95775, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "遂是“于是”“就”的意思，一件事做完，接着做下一件。", "primary_collocate": null, "pronunciation": "suì", "ipa": "swei˥˩", "syllable_count": 1, "sentences": [{"text": "他吃完饭，遂回家。", "target_word": "遂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天已黑，众人遂散去。", "target_word": "遂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨停之后，他遂出门买菜。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读完信，遂决定去北京。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家说完话，遂一起离开。", "target_word": "遂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人讲完故事，孩子们遂安静地睡去。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看见门开着，遂走进去看了看。", "target_word": "遂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王听了他的话，遂放他回家。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她找到了丢失的书包，遂高兴地回到教室。", "target_word": "遂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想起朋友的约定，遂拿起外衣，快步走出门去。", "target_word": "遂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语，表示一件事做完后接着做另一件，相当于“于是、就”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95775, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遂", "is_correct": true, "explanation": "suì（去声）是“于是、就”的意思，连接前后两件事。"}, {"text": "随", "is_correct": false, "explanation": "随 suí（阳平）与 suì（去声）声调不同，意思是跟随。"}, {"text": "睡", "is_correct": false, "explanation": "睡 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡觉。"}, {"text": "虽", "is_correct": false, "explanation": "虽 suī（阴平）与 suì（去声）只差声调，意思是虽然。"}, {"text": "税", "is_correct": false, "explanation": "税 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是税收。"}, {"text": "四", "is_correct": false, "explanation": "四 sì 比 suì 少了韵母中的 u，声调相同，意思是数字四。"}], "explanations": {"遂": "suì（去声）是“于是、就”的意思，连接前后两件事。", "随": "随 suí（阳平）与 suì（去声）声调不同，意思是跟随。", "睡": "睡 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡觉。", "虽": "虽 suī（阴平）与 suì（去声）只差声调，意思是虽然。", "税": "税 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是税收。", "四": "四 sì 比 suì 少了韵母中的 u，声调相同，意思是数字四。"}, "sentence_index": null, "correct_answer": "遂"}, "level_3": {"options": [{"text": "遂", "is_correct": true, "explanation": "遂是连词，表示吃完饭之后接着回家，相当于“于是”。"}, {"text": "同时", "is_correct": false, "explanation": "搭配：“同时”表示两件事在同一时间发生，与“吃完饭”之后才回家的先后顺序不合。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示为了某个目的，说成“为了回家而吃饭”，与原句先吃后走的意思不符。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后没有对立关系，用在这里语义不通。"}], "explanations": {"遂": "遂是连词，表示吃完饭之后接着回家，相当于“于是”。", "同时": "搭配：“同时”表示两件事在同一时间发生，与“吃完饭”之后才回家的先后顺序不合。", "以便": "语义：“以便”表示为了某个目的，说成“为了回家而吃饭”，与原句先吃后走的意思不符。", "但是": "语义：“但是”表示转折，前后没有对立关系，用在这里语义不通。"}, "sentence_index": 0, "correct_answer": "遂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在看书，遂下雨了。", "explanation": "这里应该用〈忽然〉。“遂”表示同一主体先做完一件事、接着做下一件事，不能用来表示突然发生的自然现象。"}, {"text": "这件事很简单，我遂能做好。", "explanation": "这里应该用〈就〉。“遂”要接在前一件事完成之后，此处没有前一动作，表示条件下的直接结果应用“就”。"}, {"text": "他一边唱歌，遂跳舞。", "explanation": "这里应该用〈同时〉。“遂”表示前一动作完成后接着发生，不能用于两个同时进行的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95775, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遂", "is_correct": true, "explanation": "suì（去声）是“于是、就”的意思，连接前后两件事。"}, {"text": "翠", "is_correct": false, "explanation": "cuì（去声）与 suì 声母不同（c 与 s），声调相同，意思是翠绿。"}, {"text": "最", "is_correct": false, "explanation": "最 zuì 与 suì 声母不同（z 与 s），声调相同，意思是程度最高。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì（去声）与 suì 声母不同（r 与 s），声调相同，意思是吉祥。"}], "explanations": {"遂": "suì（去声）是“于是、就”的意思，连接前后两件事。", "翠": "cuì（去声）与 suì 声母不同（c 与 s），声调相同，意思是翠绿。", "最": "最 zuì 与 suì 声母不同（z 与 s），声调相同，意思是程度最高。", "瑞": "ruì（去声）与 suì 声母不同（r 与 s），声调相同，意思是吉祥。"}, "sentence_index": null, "correct_answer": "遂"}, "level_3": {"options": [{"text": "遂", "is_correct": true, "explanation": "遂是连词，表示看见门开着之后接着走进去，相当于“于是”。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，前后两个动作并不对立，用在这里语义不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示另一种假设结果，与“看见门开着”之后的动作无关，句意不通。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”用于递进补充理由，前文没有需要补充的理由，不能单独接叙述动作。"}], "explanations": {"遂": "遂是连词，表示看见门开着之后接着走进去，相当于“于是”。", "然而": "语义：“然而”表示转折，前后两个动作并不对立，用在这里语义不通。", "否则": "语义：“否则”表示另一种假设结果，与“看见门开着”之后的动作无关，句意不通。", "况且": "搭配：“况且”用于递进补充理由，前文没有需要补充的理由，不能单独接叙述动作。"}, "sentence_index": 6, "correct_answer": "遂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他本以为能赢，遂输了比赛。", "explanation": "这里应该用〈不料〉。“遂”表示顺着前一件事接着发生，不能表示出乎意料的转折结果。"}, {"text": "他答应了朋友，遂没有去。", "explanation": "这里应该用〈却〉。“遂”只表示顺接，不能表示与前文相反的转折。"}, {"text": "天黑了，遂月亮升了起来。", "explanation": "这里应该用〈随后〉。“遂”连接的是同一主体先后完成的动作，此处天黑与月升是两件无关的事，应用〈随后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他洗完澡，遂了上床休息。", "corrected_sentence": "他洗完澡，遂上床休息。", "error_description": "错误：“遂”后面多加了“了”。“遂”是连词，不能带“了”，正确说法是“他洗完澡，遂上床休息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门开了，他很遂走进屋里。", "corrected_sentence": "门开了，他遂走进屋里。", "error_description": "错误：“遂”前面多加了程度副词“很”。“遂”是连词，不能受程度副词修饰，正确说法是“门开了，他遂走进屋里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
