INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95776, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "于是；就。表示前一件事之后接着发生另一件事。", "primary_collocate": null, "pronunciation": "suì", "ipa": "swei˥˩", "syllable_count": 1, "sentences": [{"text": "他写完信，遂睡下。", "target_word": "遂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天亮之后，大家遂上路。", "target_word": "遂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生看完病，遂开了药。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人坐下喝茶，主人遂讲起旧事。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听说山上有花，遂约朋友同去。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲完新课，学生们遂开始做题。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风小了，船遂慢慢靠岸。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看完比赛，遂想起自己小时候的梦想。", "target_word": "遂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母亲病好之后，他遂辞去工作，回到家乡。", "target_word": "遂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书店看到一本好书，遂买下带回家去读。", "target_word": "遂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语，连接前后两件事，前一件事之后接着发生后一件，相当于“于是、就”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遂", "is_correct": true, "explanation": "suì（去声）是“于是、就”的意思，连接前后两件事。"}, {"text": "随", "is_correct": false, "explanation": "随 suí（阳平）与 suì（去声）声调不同，意思是跟随。"}, {"text": "睡", "is_correct": false, "explanation": "睡 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡觉。"}, {"text": "虽", "is_correct": false, "explanation": "虽 suī（阴平）与 suì（去声）只差声调，意思是虽然。"}, {"text": "税", "is_correct": false, "explanation": "税 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是税收。"}, {"text": "四", "is_correct": false, "explanation": "四 sì 比 suì 少了韵母中的 u，声调相同，意思是数字四。"}], "explanations": {"遂": "suì（去声）是“于是、就”的意思，连接前后两件事。", "随": "随 suí（阳平）与 suì（去声）声调不同，意思是跟随。", "睡": "睡 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是睡觉。", "虽": "虽 suī（阴平）与 suì（去声）只差声调，意思是虽然。", "税": "税 shuì 与 suì 声母不同（sh 与 s），声调相同，意思是税收。", "四": "四 sì 比 suì 少了韵母中的 u，声调相同，意思是数字四。"}, "sentence_index": null, "correct_answer": "遂"}, "level_3": {"options": [{"text": "遂", "is_correct": true, "explanation": "遂是连词，表示写完信之后接着睡下，相当于“于是”。"}, {"text": "同时", "is_correct": false, "explanation": "搭配：“同时”表示两件事在同一时间发生，与“写完信”之后才睡下的先后顺序不合。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示另一种假设结果，与“写完信”之后的动作无关，句意不通。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，写信与睡下之间并无对立，用在这里语义不通。"}], "explanations": {"遂": "遂是连词，表示写完信之后接着睡下，相当于“于是”。", "同时": "搭配：“同时”表示两件事在同一时间发生，与“写完信”之后才睡下的先后顺序不合。", "否则": "语义：“否则”表示另一种假设结果，与“写完信”之后的动作无关，句意不通。", "然而": "语义：“然而”表示转折，写信与睡下之间并无对立，用在这里语义不通。"}, "sentence_index": 0, "correct_answer": "遂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在写作业，遂下起了大雨。", "explanation": "这里应该用〈忽然〉。“遂”表示同一主体先做完一件事、接着做下一件事，不能用来表示突然发生的自然现象。"}, {"text": "这次考试很简单，我遂能考个满分。", "explanation": "这里应该用〈就〉。“遂”要接在前一件事完成之后，此处没有前一动作，表示条件下的直接结果应用“就”。"}, {"text": "他一边唱歌，遂跳舞。", "explanation": "这里应该用〈同时〉。“遂”表示前一动作完成后接着发生，不能用于两个同时进行的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遂", "is_correct": true, "explanation": "suì（去声）是“于是、就”的意思，连接前后两件事。"}, {"text": "翠", "is_correct": false, "explanation": "cuì（去声）与 suì 声母不同（c 与 s），声调相同，意思是翠绿。"}, {"text": "最", "is_correct": false, "explanation": "最 zuì 与 suì 声母不同（z 与 s），声调相同，意思是程度最高。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì（去声）与 suì 声母不同（r 与 s），声调相同，意思是吉祥。"}], "explanations": {"遂": "suì（去声）是“于是、就”的意思，连接前后两件事。", "翠": "cuì（去声）与 suì 声母不同（c 与 s），声调相同，意思是翠绿。", "最": "最 zuì 与 suì 声母不同（z 与 s），声调相同，意思是程度最高。", "瑞": "ruì（去声）与 suì 声母不同（r 与 s），声调相同，意思是吉祥。"}, "sentence_index": null, "correct_answer": "遂"}, "level_3": {"options": [{"text": "遂", "is_correct": true, "explanation": "遂是连词，表示风小之后接着船慢慢靠岸，相当于“于是”。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”用于递进补充理由，前文只是陈述风小，没有需要补充的理由。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”表示出乎意料，风小之后船靠岸是顺理成章的事，句意不通。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，风小之后船靠岸是顺理成章的事，句意不通。"}], "explanations": {"遂": "遂是连词，表示风小之后接着船慢慢靠岸，相当于“于是”。", "况且": "搭配：“况且”用于递进补充理由，前文只是陈述风小，没有需要补充的理由。", "不料": "语义：“不料”表示出乎意料，风小之后船靠岸是顺理成章的事，句意不通。", "反而": "语义：“反而”表示与预期相反，风小之后船靠岸是顺理成章的事，句意不通。"}, "sentence_index": 6, "correct_answer": "遂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他本来很高兴，遂哭了起来。", "explanation": "这里应该用〈却〉。“遂”表示顺着前一件事接着发生，不能表示与前文相反的转折。"}, {"text": "他以为会下雨，遂天晴了。", "explanation": "这里应该用〈不料〉。“遂”表示同一主体先做完一件事、接着做下一件事，不能用来表示出乎意料的自然变化。"}, {"text": "书店的生意很遂，每天都有人来。", "explanation": "这里的“遂”不表示“顺利”的意思，此处应用〈顺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看完书，遂了睡下。", "corrected_sentence": "他看完书，遂睡下。", "error_description": "错误：“遂”后面多加了“了”。“遂”是连词，不能带“了”，正确说法是“他看完书，遂睡下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停了，船很遂慢慢靠岸。", "corrected_sentence": "雨停了，船遂慢慢靠岸。", "error_description": "错误：“遂”前面多加了程度副词“很”。“遂”是连词，不能受程度副词修饰，正确说法是“雨停了，船遂慢慢靠岸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
