INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开道是走在前面，让别人有路可以走。", "primary_collocate": null, "pronunciation": "kāi dào", "ipa": "kʰaɪ˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "人太多了，保安在前面开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走在前面开道，让老人慢慢进去。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上都是人，你先去前面开道吧。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明星走进大门时，保安们一起开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子太多，老师在前面开道，大家排着队走。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场里人挤人，哥哥帮妈妈开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出结束后，工作人员在前面给歌手开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷太多，几个警察在前面开道，球员才走出来。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子高，力气大，在人群里给我们开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要出去，同事们赶快在门口开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了道", "label": "体标"}, {"form": "開道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "走在前面，替别人挤出一条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开道", "is_correct": true, "explanation": "开道：走在前面替别人清出一条路，符合人多需要疏通的语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：人太多时需要清出道路，唱歌无法解决问题，与句意矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“人太多了”之后不说“在前面散步”，前后不搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：保安睡觉无法替别人清出道路，与句意矛盾。"}], "explanations": {"开道": "开道：走在前面替别人清出一条路，符合人多需要疏通的语境。", "唱歌": "语义：人太多时需要清出道路，唱歌无法解决问题，与句意矛盾。", "散步": "搭配：“人太多了”之后不说“在前面散步”，前后不搭配。", "睡觉": "语义：保安睡觉无法替别人清出道路，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "开道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支队伍的最后一个人负责开道，防止敌人追上来。", "explanation": "这里应该用〈断后〉。开道是在前面清路，守在最后防备追兵要说断后。"}, {"text": "演出八点开道，观众陆续入场。", "explanation": "这里应该用〈开场〉。开道指在前面清出道路让人通过，演出开始要说开场。"}, {"text": "妈妈常常开道我，让我别再难过。", "explanation": "这里应该用〈开导〉。开道是走在前面让别人有路走，劝慰别人想开要说开导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开道", "is_correct": true, "explanation": "开道：在前面清出一条路，让歌手顺利离开，符合句意。"}, {"text": "打针", "is_correct": false, "explanation": "语义：演出结束后在前面给歌手打针，与“在前面”的语境不合。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：歌手不需要写作业，与演出后的语境矛盾。"}, {"text": "上课", "is_correct": false, "explanation": "搭配：演出结束后“给歌手上课”不是常见的搭配，与句意不合。"}], "explanations": {"开道": "开道：在前面清出一条路，让歌手顺利离开，符合句意。", "打针": "语义：演出结束后在前面给歌手打针，与“在前面”的语境不合。", "写作业": "语义：歌手不需要写作业，与演出后的语境矛盾。", "上课": "搭配：演出结束后“给歌手上课”不是常见的搭配，与句意不合。"}, "sentence_index": 6, "correct_answer": "开道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天在厨房开道做饭，很辛苦。", "explanation": "这里应该用〈做〉。开道指在前面清出道路让人通过，做饭要说做。"}, {"text": "节目晚上七点开道，大家别忘了看。", "explanation": "这里应该用〈开播〉。开道是走在前面让别人有路走，节目开始播出要说开播。"}, {"text": "医院明天一早开道，病人可以来看病了。", "explanation": "这里应该用〈开诊〉。开道指在前面清出道路，医院开始接诊要说开诊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "保安在前面开道过，人群很快散开。", "corrected_sentence": "保安在前面开过道，人群很快散开。", "error_description": "体标位置错误：“过”应紧跟动词，说“开过道”，不能说“开道过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他开道在队伍前面，大家都很安全。", "corrected_sentence": "他在队伍前面开道，大家都很安全。", "error_description": "语序错误：状语“在队伍前面”应放在动词“开道”之前，不能放在“开道”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
