INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在前面开辟道路或清出道路，使后面的人或车通行。", "primary_collocate": null, "pronunciation": "kāi dào", "ipa": "kʰaɪ˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "警车在前面开道，救护车很快过去了。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面有警察开道，车子走得很快。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统的车队来了，摩托车在前面开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪封了山路，工人开着车在前面开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上人太多，警察走在前面开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的时候，一辆摩托车为运动员开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在前面开道，让大车慢慢开进来。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长到了，警车一路开道，别的车都让开。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日游行的时候，两辆警车先开道。", "target_word": "开道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天路很窄，他骑车在前面给我们开道。", "target_word": "开道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了道", "label": "体标"}, {"form": "開道", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在前面清出道路，让后面的人或车通行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8567e9a5-8d50-4bad-843c-2091e84792f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开道", "is_correct": true, "explanation": "开道：在前面清出道路，让救护车通过，符合句意。"}, {"text": "堵路", "is_correct": false, "explanation": "语义：堵路会让救护车过不去，与“很快过去了”矛盾。"}, {"text": "挡道", "is_correct": false, "explanation": "语义：挡道同样会阻碍救护车，与句意相反。"}, {"text": "断后", "is_correct": false, "explanation": "搭配：“断后”指走在最后，与“在前面”矛盾，不能这样搭配。"}], "explanations": {"开道": "开道：在前面清出道路，让救护车通过，符合句意。", "堵路": "语义：堵路会让救护车过不去，与“很快过去了”矛盾。", "挡道": "语义：挡道同样会阻碍救护车，与句意相反。", "断后": "搭配：“断后”指走在最后，与“在前面”矛盾，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "开道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师常常开道学生，让他们想通道理。", "explanation": "这里应该用〈开导〉。开道指在前面清出道路让人通过，劝导别人想通道理要说开导。"}, {"text": "音乐会今天晚上开道，观众很多。", "explanation": "这里应该用〈开幕〉。开道指在前面清出道路，活动正式开始要说开幕。"}, {"text": "工人们正在开道下水道，免得积水。", "explanation": "这里应该用〈疏通〉。开道指在前面清出道路让人通过，清理堵塞的管道要说疏通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开道", "is_correct": true, "explanation": "开道：在前面清出道路，让大车能慢慢开进来，符合句意。"}, {"text": "关门", "is_correct": false, "explanation": "语义：关门会挡住大车，与“让大车开进来”矛盾。"}, {"text": "封路", "is_correct": false, "explanation": "语义：封路会让大车进不来，与句意相反。"}, {"text": "堵车", "is_correct": false, "explanation": "搭配：“在前面堵车”不能用来引导大车进入，前后不搭配。"}], "explanations": {"开道": "开道：在前面清出道路，让大车能慢慢开进来，符合句意。", "关门": "语义：关门会挡住大车，与“让大车开进来”矛盾。", "封路": "语义：封路会让大车进不来，与句意相反。", "堵车": "搭配：“在前面堵车”不能用来引导大车进入，前后不搭配。"}, "sentence_index": 6, "correct_answer": "开道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校下周一开道，学生们都回来了。", "explanation": "这里应该用〈开学〉。开道指在前面清出道路，新学期开始要说开学。"}, {"text": "我们明天下午开道，请大家准时参加。", "explanation": "这里应该用〈开会〉。开道指在前面清出道路，召集大家讨论事情要说开会。"}, {"text": "这家超市下个月开道营业，欢迎大家来。", "explanation": "这里应该用〈开业〉。开道指在前面清出道路让人通过，商店开始营业要说开业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交警在后面开道，车队很快就过去了。", "corrected_sentence": "交警在前面开道，车队很快就过去了。", "error_description": "方位错误：“开道”是走在车队前面清路，应说“在前面开道”，不能说“在后面开道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们开道在前面，车子很快通过了。", "corrected_sentence": "他们在前面开道，车子很快通过了。", "error_description": "语序错误：状语“在前面”应放在动词“开道”之前，不能放在“开道”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '515b787e-e9c8-4c3d-a851-37fee5662111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
