INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于颗粒状的小东西。", "primary_collocate": null, "pronunciation": "kē", "ipa": "kʰɤ˥", "syllable_count": 1, "sentences": [{"text": "他在花盆里放了一颗种子。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的项链上有一颗珍珠。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我每天吃一颗药。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋里有一颗小石头，我走路很疼。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗钻石很贵。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里放了五颗红豆。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟吃了一颗红色的小果子。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口袋里有一颗小纽扣。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗小珠子是奶奶留给我的。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把一颗花生放进嘴里。", "target_word": "颗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗颗", "label": "重叠"}, {"form": "颗粒", "label": "复合"}, {"form": "顆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词：颗粒状的小东西，如种子、珍珠、药、石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6334619f-34d1-4937-8dd3-f10a15a89410') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validati