INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于颗粒状的小东西，如种子、珍珠。"}, {"text": "哥", "is_correct": false, "explanation": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是课程，不是量词。"}, {"text": "渴", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是口渴，不是量词。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于颗粒状的小东西，如种子、珍珠。", "哥": "gē 与 kē 声母不同（g 与 k），意思是哥哥，不是量词。", "课": "kè 与 kē 声调不同，意思是课程，不是量词。", "渴": "kě 与 kē 声调不同，意思是口渴，不是量词。", "咳": "ké 与 kē 声调不同，意思是咳嗽，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于颗粒状的小东西，种子是这类东西。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于整株植物，种子还没长成植物，不说“一棵种子”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不说“一张种子”。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”指大型固定的东西，种子很小，不能用“座”。"}], "explanations": {"颗": "正确答案。颗：用于颗粒状的小东西，种子是这类东西。", "棵": "搭配：“棵”用于整株植物，种子还没长成植物，不说“一棵种子”。", "张": "搭配：“张”用于平面的东西，不说“一张种子”。", "座": "体貌：“座”指大型固定的东西，种子很小，不能用“座”。"}, "sentence_index": 0, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口袋里有一颗钥匙。", "explanation": "这里应该用〈把〉。“颗”用于颗粒状的小东西，钥匙要用“把”。"}, {"text": "我戴了一颗眼镜。", "explanation": "这里应该用〈副〉。“颗”用于颗粒状的小东西，眼镜要用“副”。"}, {"text": "她脖子上挂着一颗项链。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状的小东西，项链要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_vali