INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95784, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：kē，量词，用于颗粒状的小东西。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 kē 声调不同，意思是客人，不是量词。"}, {"text": "可", "is_correct": false, "explanation": "kě 与 kē 声调不同，意思是可以，不是量词。"}, {"text": "壳", "is_correct": false, "explanation": "ké 与 kē 声调不同，意思是外壳，不是量词。"}], "explanations": {"颗": "正确答案。颗：kē，量词，用于颗粒状的小东西。", "客": "kè 与 kē 声调不同，意思是客人，不是量词。", "可": "kě 与 kē 声调不同，意思是可以，不是量词。", "壳": "ké 与 kē 声调不同，意思是外壳，不是量词。"}, "sentence_index": null, "correct_answer": "颗"}, "level_3": {"options": [{"text": "颗", "is_correct": true, "explanation": "正确答案。颗：用于小而圆的东西，果子是这类东西。"}, {"text": "头", "is_correct": false, "explanation": "搭配：“头”用于大型动物，不说“一头红色的小果子”。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画、布等平面的东西，与小果子的意思不合。"}, {"text": "条", "is_correct": false, "explanation": "语义：“条”指细长的东西，小果子不是这种形状。"}], "explanations": {"颗": "正确答案。颗：用于小而圆的东西，果子是这类东西。", "头": "搭配：“头”用于大型动物，不说“一头红色的小果子”。", "幅": "语义：“幅”用于画、布等平面的东西，与小果子的意思不合。", "条": "语义：“条”指细长的东西，小果子不是这种形状。"}, "sentence_index": 6, "correct_answer": "颗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收到了一颗信。", "explanation": "这里应该用〈封〉。“颗”用于颗粒状的小东西，信要用“封”。"}, {"text": "教室里放着一颗桌子。", "explanation": "这里应该用〈张〉。“颗”用于颗粒状的小东西，桌子要用“张”。"}, {"text": "河里游着一颗鱼。", "explanation": "这里应该用〈条〉。“颗”用于颗粒状的小东西，鱼要用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b3c603-9b99-4428-bd7e-8064143e9c28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
