INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95785, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一一是一个接着一个，不漏掉。", "primary_collocate": null, "pronunciation": "yī yī", "ipa": "i˥ i˥", "syllable_count": 2, "sentences": [{"text": "老师对每个问题都一一做了解释。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把要买的东西一一写在纸上。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理一一看过了大家的工作报告。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题，我们会一一解决。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新朋友们来了，我一一给你们介绍。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友们的生日一一记了下来。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游一一说明了参观的要求。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把每一页的错误一一改过来。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一一感谢了帮助过自己的人。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查员一一核对了所有的名单。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一一", "label": "原形"}], "register": "书面", "sense_fingerprint": "一个接着一个不漏掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一一", "is_correct": true, "explanation": "正确：一一，读作 yī yī，意思是一个接着一个，不漏掉。"}, {"text": "一亿", "is_correct": false, "explanation": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。"}, {"text": "意义", "is_correct": false, "explanation": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。"}, {"text": "姨姨", "is_correct": false, "explanation": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}], "explanations": {"一一": "正确：一一，读作 yī yī，意思是一个接着一个，不漏掉。", "一亿": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。", "意义": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。", "姨姨": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}, "sentence_index": null, "correct_answer": "一一"}, "level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每个问题都”的全面性矛盾。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示在同一时间进行，与逐个处理每个问题的语境矛盾。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐个、不遗漏地进行，与“每个问题都……做了解释”相符。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：“渐渐”表示逐步发展，不能修饰一次做完解释的动作。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“每个问题都”的全面性矛盾。", "同时": "语义：“同时”表示在同一时间进行，与逐个处理每个问题的语境矛盾。", "一一": "正确：“一一”表示逐个、不遗漏地进行，与“每个问题都……做了解释”相符。", "渐渐": "搭配：“渐渐”表示逐步发展，不能修饰一次做完解释的动作。"}, "sentence_index": 0, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月亮一一圆了。", "explanation": "这里应该用〈渐渐〉。“一一”强调接着一个、不遗漏地依次进行，月亮逐渐变圆是连续变化，应用“渐渐”。"}, {"text": "他一一看了一眼窗外。", "explanation": "这里应该用〈又〉。“一一”强调依次逐个、不遗漏地进行，“看了一眼”是单次动作，句中也没有多个对象，应改为“他又看了一眼窗外”。"}, {"text": "我一一怀念小时候的家。", "explanation": "这里应该用〈时常〉。“一一”强调依次逐个、不遗漏地进行，“怀念”是心理活动，表示反复想起应用“时常”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗地里进行，与“说明参观的要求”的公开性矛盾。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：“逐渐”表示变化的过程，不能修饰一次性的说明动作。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐项、依次说明，与“导游……说明了参观的要求”相符。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”表示马虎、不认真，与“依次详细说明”的语境相反。"}], "explanations": {"偷偷": "语义：“偷偷”表示暗地里进行，与“说明参观的要求”的公开性矛盾。", "逐渐": "搭配：“逐渐”表示变化的过程，不能修饰一次性的说明动作。", "一一": "正确：“一一”表示逐项、依次说明，与“导游……说明了参观的要求”相符。", "草率": "语义：“草率”表示马虎、不认真，与“依次详细说明”的语境相反。"}, "sentence_index": 6, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的心一一碎了。", "explanation": "这里应该用〈彻底〉。“一一”强调依次逐个、不遗漏地进行，心碎是一次性的整体变化，应用“彻底”。"}, {"text": "河水一一流进了大海。", "explanation": "这里应该用〈源源不断〉。“一一”强调一个接一个、不遗漏地依次进行，河水的持续流动应用“源源不断”。"}, {"text": "我一一生了一场病。", "explanation": "这里应该用〈忽然〉。“一一”要求依次逐个、不遗漏地进行，“生病”是一次性的事件，句中也没有多个对象，应用“忽然”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议上，经理一一听取了大家的意见一一。", "corrected_sentence": "会议上，经理一一听取了大家的意见。", "error_description": "错误：“一一”重复出现，多出的“一一”放在了宾语“意见”的后面。正确：“一一”只放在动词“听取”的前面，写作“经理一一听取了大家的意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一一看一一完了桌上的文件。", "corrected_sentence": "他一一看完了桌上的文件。", "error_description": "错误：“一一”重复出现，多出的“一一”插在了动词“看”和结果补语“完”之间。正确：“一一”只放在“看完”之前，写作“他一一看完了桌上的文件”，表示逐个、不遗漏地看完。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
