INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个一个地，逐个。", "primary_collocate": null, "pronunciation": "yī yī", "ipa": "i˥ i˥", "syllable_count": 2, "sentences": [{"text": "老师把名字一一念给大家听。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些问题一一回答。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，他一一和他们握手。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把每个病人一一检查了一遍。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书一一放回了书架上。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一一走上台，说出自己的名字。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把礼物一一拿出来给我们看。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子里的东西一一拿了出来。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的保安一一看了大家的证件。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每位老人的名字一一记在本子上。", "target_word": "一一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一一", "label": "原形"}], "register": "书面", "sense_fingerprint": "一个一个地逐个做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一一", "is_correct": true, "explanation": "正确：一一，读作 yī yī，意思是一个一个地、逐个地。"}, {"text": "一亿", "is_correct": false, "explanation": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。"}, {"text": "意义", "is_correct": false, "explanation": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。"}, {"text": "姨姨", "is_correct": false, "explanation": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}], "explanations": {"一一": "正确：一一，读作 yī yī，意思是一个一个地、逐个地。", "一亿": "一亿 yī yì：第二个音节声调不同（yì 为第四声，与 yī 的第一声不同），意思是一亿。", "意义": "意义 yì yì：两个音节的声调都与 yī yī 不同，意思是意义。", "姨姨": "yí yí（两个音节都是第二声）与 yī yī 声调不同，口语中是对年长女性的称呼。"}, "sentence_index": null, "correct_answer": "一一"}, "level_3": {"options": [{"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人单独进行，与“念给大家听”的对象矛盾。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐个依次进行，与“把名字……念给大家听”的语境相符。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：“逐渐”表示变化的过程，不能修饰一次性的朗读动作。"}, {"text": "悄悄", "is_correct": false, "explanation": "语义：“悄悄”指不声张，与“念给大家听”的公开性矛盾。"}], "explanations": {"独自": "语义：“独自”指一个人单独进行，与“念给大家听”的对象矛盾。", "一一": "正确：“一一”表示逐个依次进行，与“把名字……念给大家听”的语境相符。", "逐渐": "搭配：“逐渐”表示变化的过程，不能修饰一次性的朗读动作。", "悄悄": "语义：“悄悄”指不声张，与“念给大家听”的公开性矛盾。"}, "sentence_index": 0, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一一去公园，玩得很开心。", "explanation": "这里应该用〈一起〉。“一一”表示逐个依次进行，不表示共同行动，几个人一起去公园不能用“一一”。"}, {"text": "他一一跑了一整夜。", "explanation": "这里应该用〈一直〉。“一一”要求依次逐个进行，句中只有一个人，连续奔跑应用“一直”。"}, {"text": "爸爸一一喜欢这个礼物。", "explanation": "这里应该用〈很〉。“一一”表示逐个依次进行，不能修饰“喜欢”这类心理状态，表示程度应用“很”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胡乱", "is_correct": false, "explanation": "语义：“胡乱”表示随意、不认真，与“逐个、有序地拿出来给我们看”的动作相反。"}, {"text": "一一", "is_correct": true, "explanation": "正确：“一一”表示逐个拿出，与“把礼物……拿出来”的语境相符。"}, {"text": "渐渐", "is_correct": false, "explanation": "搭配：“渐渐”表示逐步变化，不能修饰一次性的拿出动作。"}, {"text": "暗暗", "is_correct": false, "explanation": "语义：“暗暗”指背地里、不声张，与“给我们看”的行为矛盾。"}], "explanations": {"胡乱": "语义：“胡乱”表示随意、不认真，与“逐个、有序地拿出来给我们看”的动作相反。", "一一": "正确：“一一”表示逐个拿出，与“把礼物……拿出来”的语境相符。", "渐渐": "搭配：“渐渐”表示逐步变化，不能修饰一次性的拿出动作。", "暗暗": "语义：“暗暗”指背地里、不声张，与“给我们看”的行为矛盾。"}, "sentence_index": 6, "correct_answer": "一一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷一一去世了。", "explanation": "这里应该用〈突然〉。“一一”要求多个对象依次进行，句中只有爷爷一人，去世是一次性的事件，应用“突然”。"}, {"text": "天一一亮了。", "explanation": "这里应该用〈渐渐〉。“一一”表示依次逐个进行，天色由暗变亮是逐步的变化，应用“渐渐”，不能分成一个一个。"}, {"text": "一个人一一来了。", "explanation": "这里应该用〈独自〉。“一一”要求多个对象依次进行，句中只有一个人，单独行动应用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把碗一一洗一一干净了。", "corrected_sentence": "妈妈把碗一一洗干净了。", "error_description": "错误：“一一”重复出现，多出的“一一”插在了动词“洗”和补语“干净”之间。正确：“一一”只放在动词“洗”的前面，写作“把碗一一洗干净了”，表示逐个依次洗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把相片一一挂一一在墙上。", "corrected_sentence": "奶奶把相片一一挂在墙上。", "error_description": "错误：“一一”重复出现，多出的“一一”插在了动词“挂”和介词“在”之间。正确：“一一”只放在动词“挂”的前面，写作“把相片一一挂在墙上”，表示逐个挂。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下线", "is_correct": true, "explanation": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。"}, {"text": "下载", "is_correct": false, "explanation": "下载是把网上的文件存到本地，与“上线”不构成反义。"}, {"text": "注册", "is_correct": false, "explanation": "注册是在系统里登记身份，与“上线”不构成反义。"}, {"text": "升级", "is_correct": false, "explanation": "升级是把软件换成新版本，与“上线”不构成反义。"}], "correct_answer": "下线", "explanations": {"下线": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。", "下载": "下载是把网上的文件存到本地，与“上线”不构成反义。", "注册": "注册是在系统里登记身份，与“上线”不构成反义。", "升级": "升级是把软件换成新版本，与“上线”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下线", "is_correct": true, "explanation": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。"}, {"text": "打印", "is_correct": false, "explanation": "打印是把文件印在纸上，与“上线”不构成反义。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译是把一种语言转换成另一种语言，与“上线”不构成反义。"}, {"text": "排队", "is_correct": false, "explanation": "排队是按顺序等候，与“上线”不构成反义。"}], "correct_answer": "下线", "explanations": {"下线": "与“上线”相对，指网站或软件停止对外开放，也指退出网络登录。", "打印": "打印是把文件印在纸上，与“上线”不构成反义。", "翻译": "翻译是把一种语言转换成另一种语言，与“上线”不构成反义。", "排队": "排队是按顺序等候，与“上线”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上线是让网站或软件开始让大家使用。", "primary_collocate": null, "pronunciation": "shàng xiàn", "ipa": "ʂɑŋ˥˩ ɕiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个网站今天上线。", "target_word": "上线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新游戏什么时候上线？", "target_word": "上线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的手机软件下周上线。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的新网站昨天上线了。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个功能还没上线，请再等几天。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司准备把新产品放到网上，下个月上线。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那家书店的网上商城快要上线了。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "程序员改完错误以后，软件才能上线。", "target_word": "上线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学习软件上线第一天，就有一万人下载。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新平台上线后，受到了很多人欢迎。", "target_word": "上线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上线了", "label": "体标"}, {"form": "上线过", "label": "体标"}], "register": "中性", "sense_fingerprint": "网站或软件开始对大家开放使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确答案：网站或软件开始对大家开放使用。"}, {"text": "上香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàn（第四声）韵母不同（-iāng 与 -iàn），意思是烧香拜神。"}, {"text": "上相", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（-iàng 与 -iàn），意思是人拍照好看。"}, {"text": "上弦", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是月亮的上半月。"}], "explanations": {"上线": "正确答案：网站或软件开始对大家开放使用。", "上香": "xiāng（第一声）与 xiàn（第四声）韵母不同（-iāng 与 -iàn），意思是烧香拜神。", "上相": "xiàng 与 xiàn 韵母不同（-iàng 与 -iàn），意思是人拍照好看。", "上弦": "xián（第二声）与 xiàn（第四声）声调不同，意思是月亮的上半月。"}, "sentence_index": null, "correct_answer": "上线"}, "level_3": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确：“这个网站今天上线”指网站今天开始对外开放。"}, {"text": "生病", "is_correct": false, "explanation": "语义：网站不会生病，“这个网站今天生病”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：网站不能结婚，这句话说的是网站开通。"}, {"text": "进行", "is_correct": false, "explanation": "配价：“进行”后面要带宾语，如“进行改版”，单独放在句末不完整。"}], "explanations": {"上线": "正确：“这个网站今天上线”指网站今天开始对外开放。", "生病": "语义：网站不会生病，“这个网站今天生病”说不通。", "结婚": "语义：网站不能结婚，这句话说的是网站开通。", "进行": "配价：“进行”后面要带宾语，如“进行改版”，单独放在句末不完整。"}, "sentence_index": 0, "correct_answer": "上线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校昨天上线了。", "explanation": "这里应该用〈开学〉。学校开始上课要说“开学”，“上线”用于网站、软件。"}, {"text": "这座大楼昨天上线了。", "explanation": "这里应该用〈建成〉。大楼盖好要说“建成”，“上线”不用于建筑。"}, {"text": "这个公园昨天上线了。", "explanation": "这里应该用〈开放〉。公园对游客开放要说“开放”，“上线”不用于公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上线", "is_correct": true, "explanation": "正确：“快要上线了”指网上商城即将对外开放。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：商城不能毕业，“快要毕业了”说不通。"}, {"text": "出差", "is_correct": false, "explanation": "语义：商城不会出差，这句话说的是网上商城快要开放。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”要带宾语，如“参加活动”，“快要参加了”句子不完整。"}], "explanations": {"上线": "正确：“快要上线了”指网上商城即将对外开放。", "毕业": "语义：商城不能毕业，“快要毕业了”说不通。", "出差": "语义：商城不会出差，这句话说的是网上商城快要开放。", "参加": "配价：“参加”要带宾语，如“参加活动”，“快要参加了”句子不完整。"}, "sentence_index": 6, "correct_answer": "上线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座体育馆昨天上线了。", "explanation": "这里应该用〈竣工〉。工程完工要说“竣工”，“上线”不用于建筑。"}, {"text": "这座火车站昨天上线了。", "explanation": "这里应该用〈投入使用〉。车站等设施建成后开始使用要说“投入使用”，“上线”只用于网站、软件等。"}, {"text": "比赛昨天上线了。", "explanation": "这里应该用〈开赛〉。比赛开始要说“开赛”，“上线”不用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个功能下周把上线。", "corrected_sentence": "这个功能下周上线。", "error_description": "把字句错误：“把”字句中“把……上线”后应带宾语，如“把新功能上线”；“把上线”缺少宾语，应去掉“把”，说“这个功能下周上线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新功能下个月会正式的上线。", "corrected_sentence": "这个新功能下个月会正式上线。", "error_description": "错误：状语“正式”修饰动词“上线”时用了“的”。正确：应为“正式上线”。“的”用于修饰名词，状语后直接接动词，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
